["alm_pex_35_01"] = "HADİ UÇALIM!",
["alm_pex_36_01"] = "GİDİYORUZ! HERKES ARABAYA!",
["alm_xmas22_01_01"] = "O NOEL AĞACINI BURALARDA BİR YERE KOYDUKLARINI BİLİYORUM. NEREDE? NEREDE O? O SİNSİ KÜÇÜK AĞAÇ NEREDE?",
["alm_xmas22_01_02"] = "ONU BULMALISINIZ! ŞEY, O... SİKTİR, AĞAÇ! NOEL AĞACI! ÜSTÜNDE KÜÇÜK HEDİYELER FALAN VAR!",
["alm_xmas22_01_03"] = "ÖNCE O LANET NOEL AĞACINI BULMALISINIZ. PİSLİK BURALARDA BİR YERDE.",
["alm_xmas22_02_01"] = "NOEL AĞACI! AH, NOEL AĞACI! NEREDESİİİN?",
["alm_xmas22_02_02"] = "SİKTİR DOSTUM, NE YAPIYORDUK BİZ? EE... AĞAÇ! AĞACI BULUN!",
["alm_xmas22_02_03"] = "PİŞŞT, AĞACIN NEREDE OLDUĞUNU BİLİYORUM AMA SÖYLEMEM. ARSIZ OROSPU ÇOCUĞUNUN TEKİYİMDİR.",
["alm_xmas22_03_01"] = "HEYO! GİDİP HEDİYELERİ O AĞAÇTAN ÇIKARIN!",
["alm_xmas22_03_02"] = "İŞTE ORADA! AĞACI SALLAYIP HEDİYELERİ DÜŞÜRÜN!",
["alm_xmas22_03_03"] = "BANA NOEL AĞACI GİBİ GÖRÜNÜYOR! GİDİP SALLAYIN! BAKALIM NE OLACAK!",
["alm_xmas22_03_04"] = "O AĞACA VURUP HEDİYELERİ DÜŞÜREBİLİRSİNİZ! NEDEN AĞACIN ALTINDA DEĞİLLER, BİLMİYORUM AMA İŞTE POLİS MİLLETİ. HER ŞEYİ KARIŞTIRIRLAR.",
["alm_xmas22_03_05"] = "HEDİYELER O AĞACIN İÇİNDE! VURUN! VURUN ŞU LANET AĞACA!",
["alm_xmas22_04_01"] = "AĞAÇTAN BİR HEDİYE DÜŞTÜ! BANA VERİN!",
["alm_xmas22_04_02"] = "AĞAÇ AZ ÖNCE BİR HEDİYE KUSTU! KAPIN!",
["alm_xmas22_04_03"] = "BAKIN! HEDİYE! GİDİP ALIN!",
["alm_xmas22_04_04"] = "İŞTE BİR HEDİYE! TEŞEKKÜRLER, GÜZEL AĞAÇ!",
["alm_xmas22_04_05"] = "HEDİYEYİ İLK KAPAN... HEDİYE KAZANIR!",
["alm_xmas22_05_01"] = "ŞU GÜZELLİĞİ KIZAĞIMA ATIN! POLİSLER ORADAN ALAMAZ! NOEL BÜYÜSÜ FALAN İŞTE!",
["alm_xmas22_05_02"] = "HEDİYEYİ KIZAĞIMDA GÜVENCEYE ALABİLİRSİNİZ! KIZAKLAR BUNUN İÇİN VAR!",
["alm_xmas22_05_03"] = "HEDİYEYİ BANA GETİRİN! TAM DA BUNUN İÇİN KIZAK ÇALDIM!",
["alm_xmas22_05_04"] = "HEDİYEYİ BANA GETİRİN! BÜYÜK ÇUVALLI ADAM BENİM!",
["alm_xmas22_05_05"] = "ŞİMDİ O HEDİYEYİ ALIP KIZAĞIMA GETİRECEKSİNİZ! MÜTHİŞ OLACAK!",
["alm_xmas22_06_01"] = "BAHSE GİRERİM İÇİNDE DEĞERLİ BİR ŞEY VARDIR. UMARIM AÇACAK KADAR UZUN YAŞARSINIZ!",
["alm_xmas22_06_02"] = "BURADAN CANLI ÇIKARSANIZ O HEDİYEDEN ÇOK GÜZEL BİR ŞEY ALACAKSINIZ!",
["alm_xmas22_06_03"] = "‘KUTUDA NE VAR?!’ NE BİLEYİM DOSTUM AMA KESİN DEĞERLİDİR. ÖĞRENMEK İÇİN HAYATTA KALIN!",
["alm_xmas22_06_04"] = "O KUTUDAN BÜYÜK ÖDÜL ÇIKACAK! TABİİ NALLARI DİKMEZSENİZ. ÖLÜLER HEDİYE AÇAMAZ.",
["alm_xmas22_06_05"] = "BURADAN ÇIKINCA O HEDİYEYİ BİR GÜZEL AÇACAĞIZ! SAKIN ÖLMEYİN!",
["alm_xmas22_07_01"] = "AZ ÖNCE O HEDİYENİN RUHUNU MU YEDİNİZ?! PARÇALAMAK SİZİ GÜÇLENDİRDİ!",
["alm_xmas22_07_02"] = "NOEL BABA'YA BİR KURBAN SUNDUNUZ! ŞİMDİ BÜTÜN EKİP BONUS ALIYOR!",
["alm_xmas22_07_03"] = "ASIL HEDİYE BU YOLDA EDİNDİĞİMİZ DOSTLARDI. BİR DE AZ ÖNCE ALDIĞINIZ GÜÇLENDİRME!",
["alm_xmas22_07_04"] = "HEDİYE, BİZ YAŞAYALIM DİYE ÖLDÜ! HERKESE TAKIM BONUSU!",
["alm_xmas22_07_05"] = "ZATEN O HEDİYE BOKTANDI KESİN. ŞİMDİ GERÇEKTEN İYİ BİR ŞEY ALIYORSUNUZ!",
["alm_xmas22_08_01"] = "POLİSLER İYİCE KUDURUYOR MİLLET! HEDİYE ÇALMAYA DEVAM EDERSENİZ DAHA SERT SALDIRACAKLAR!",
["alm_xmas22_08_02"] = "POLİSİN NE KADAR DELİREBİLDİĞİNİ GÖRMEK İSTER MİSİNİZ? YETERİNCE HEDİYE ÇALARSANIZ ÖĞRENİRİZ!",
["alm_xmas22_08_03"] = "AH DOSTUM, POLİSLER ÇILDIRIYOR! İŞLERİ BİRAZ DAHA KIZIŞTIRMAK ÜZERELER!",
["alm_xmas22_08_04"] = "POLİSLER NOEL NEŞEMİZİ BOZMAK İSTİYOR! YETERİNCE HEDİYE ALDIĞINIZDA DAHA SERTLEŞECEKLER. DİKKAT EDİN!",
["alm_xmas22_08_05"] = "YETERİNCE HEDİYE ÇALDIĞINIZDA BİR MELEK KANATLARINA KAVUŞUR! POLİSLER DE ÇOK GÜÇLENİR!",
["alm_xmas22_09_01"] = "KARDAN ADAM ÇAĞIRIYORLAR! SOĞUKKANLI KALIN! ANLADINIZ MI? KAR, SOĞUK... AH, ANLADINIZ İŞTE!",
["alm_xmas22_09_02"] = "KARDAN ADAM GELİYOR!",
["alm_xmas22_09_03"] = "DİKKAT! O KARDAN ADAM ŞAKA YAPMIYOR LAN!",
["alm_xmas22_10_01"] = "O KARDAN ADAMI KAFASININ ARKASINDAN VURMALISINIZ!",
["alm_xmas22_10_02"] = "KARDAN ADAMIN ZAYIF NOKTASININ KAFASININ ARKASI OLDUĞUNU HERKES BİLİR! BİR KİTAP OKUYUN!",
["alm_xmas22_10_03"] = "KARDAN ADAM KAFASININ ARKASINA ZIRH TAKMAYI UNUTMUŞ! NE EŞEK HERİF!",
["alm_xmas22_11_01"] = "O HEDİYELERİ ORTADA BIRAKMAYIN! NOEL BABA NE DÜŞÜNÜR?",
["alm_xmas22_11_02"] = "O HEDİYELERİ GÜVENCEYE ALMALISINIZ! BEN YAPARDIM AMA ZİLZURNA SARHOŞUM AMINA KOYAYIM!",
["alm_xmas22_11_3"] = "HEDİYELERİ ORADA ÖYLECE BIRAKACAK MISINIZ! YAPMAYIN! BÖYLE BİRİ OLMAYIN!",
["alm_xmas22_brf_01"] = "ÇINGIRAKLAR ÇALAR! POLİSLER HEP KOKAR! HEDİYELERİNİ ÇALACAĞIZ! AĞACI SALLA! HEDİYELERİ BANA YOLLA! AMA DİKKAT, POLİSLER ÇOK KIZACAK!",
["alm_xmas22_brf_02"] = "POLİSLER BİRBİRİNE HEDİYE ALMIŞ DA BİZE HİÇBİR ŞEY ALMAMIŞ MI DİYORSUN? SİKTİR ORADAN! GİDİP HEDİYELERİ O LANET NOEL AĞAÇLARINDAN DÜŞÜRÜN! AMA UNUTMAYIN: OYUNCAKLARINI ÇALDIĞINIZDA HİÇ DE MUTLU OLMAYACAKLAR.",
["alm_xmas22_brf_03"] = "POLİSLER BU YIL GÜZEL HEDİYELER ALMIŞ DİYE DUYDUM! ÇALMAK İSTER MİSİNİZ? TABİİ Kİ İSTERSİNİZ LAN! NOEL AĞACINA VURUP HEDİYELERİ DÜŞÜRÜN. DİKKATLİ OLUN, POLİSLER EKSTRA HUYSUZ OLACAK.",
["alm_xmas22_cbf_01"] = "NOEL! NOEL GELDİ MİLLET! HADİ NOEL'E YAKIŞIR BİR ŞEY YAPALIM!",
["alm_xmas22_cbf_02"] = "POLİSLER BU YIL YARAMAZDI. BİRİ HEDİYELERİNİ ALMALI! NOEL BABA ÖYLE DEDİ!",
["alm_xmas22_cbf_03"] = "NOEL'İN RUHU VERMEKTİR! O ZAMAN KENDİMİZE HEDİYE VERELİM! VUHUU!",
["alm_xmas22_end_fail_01"] = "HEDİYELERİ KAYBETTİNİZ! NOEL MAHVOLDU!",
["alm_xmas22_end_fail_02"] = "AH, BATIRDINIZ. SİZE HEDİYE YOK.",
["alm_xmas22_end_fail_03"] = "HİÇ HEDİYE ALMAYACAK MIYIZ? BU NE LAN, BENİM ÇOCUKLUĞUM MU?!",
["alm_xmas22_end_win_01"] = "İYİ İŞ! BU HEDİYELERİ POLİSLERDEN ÇOK DAHA FAZLA HAK EDİYORUZ. BU YIL ÇOK USLUYDUK!",
["alm_xmas22_end_win_02"] = "ÇOK MUTLU BİR NOEL GEÇİRECEĞİZ! POLİSLER GEÇİRMEYECEK! ÇİFTE KAZANÇ!",
["alm_xmas22_end_win_03"] = "POLİSLERE ÜZÜLMEYİN. NOEL'İN HEDİYE ALMAK DEMEK OLMADIĞINI ÖĞRENMELİLER. TABİİ BİZ DEĞİLSENİZ; BİZİM İÇİN KESİNLİKLE ÖYLE!",
["american_desc"] = "UYRUK: AMERİKALI$NL;YAŞ: 31$NL;$NL;HOUSTON, HAYATI BUNA BAĞLI OLSA BİLE BİR İŞTE TUTUNAMAZDI. YAŞAM TARZI ONU DOLANDIRICILIĞA VE HIRSIZLIĞA SÜRÜKLEDİ. BORÇLARI DA YILLAR SÜREN ÜÇKÂĞITÇILIĞININ KAZANDIRDIĞI DÜŞMANLARI DA ÇOĞALDI. TEFECİLERİ UZAK TUTMAK İÇİN GİDEREK DAHA BÜYÜK PARALAR BULMASI GEREKİYORDU. İLK BÜYÜK SUÇUNU 24 YAŞINDA İŞLEDİ; O GÜNDEN BERİ RİSKLER HEP BÜYÜDÜ.",
["american_desc_codex"] = "HOUSTON, HAYATI BUNA BAĞLI OLSA BİLE BİR İŞTE TUTUNAMAZDI. YAŞAM TARZI ONU DOLANDIRICILIK VE HIRSIZLIĞA SÜRÜKLEDİ. İLK BÜYÜK SUÇUNU 24 YAŞINDA İŞLEDİ; O GÜNDEN BERİ RİSKLER YALNIZCA BÜYÜDÜ.",
["ammo_bag"] = "MÜHİMMAT ÇANTASI, SENİN VE EKİBİNİN KULLANABİLMESİ İÇİN YERE YERLEŞTİRİLEBİLİR.$NL;HERKESE MÜHİMMAT.",
["ammo_bag_increase"] = "BU YÜKSELTME, ÇANTADAN ALINABİLECEK MÜHİMMAT MİKTARINI ARTIRIR.$NL;HERKESE DAHA DA FAZLA MÜHİMMAT.",
["bar_chca_01_01"] = "SİZİ BEKLİYORDUM. EKİPMANINIZ KABİN TUVALETLERİNDEN BİRİNDE BEKLİYOR AMA UFAK BİR SORUN VAR. KASA DAİRESİNİN GÜVENLİĞİ DEĞİŞTİ. KOD HÂLÂ Lİ DENG'DE AMA AÇMAK İÇİN XUN KANG'İN EL İZİ DE GEREKECEK. BİRAZ KALIP MUMU BULUP EKİPMANINIZIN YANINA KOYABİLDİM. BOL ŞANS.",
["be1_fwb_01_01"] = "O YÜKLÜ KURTARMA PARASI GELİNCE BİR EV DAHA ALACAĞIM. FEDERALLER GELİNCE SAKLANACAK YER. GELECEKLER DE.",
["be1_fwb_01_02"] = "O YÜKLÜ KURTARMA PARASI GELİNCE BELKİ BİR TEKNE ALIRIM. İSPANYOL KARAYİPLERİ'NDE YELKEN AÇMAYI HEP İSTEMİŞİMDİR.",
["be1_fwb_01_03"] = "O KURTARMA PARASINI ELE GEÇİRİNCE VEGAS'A GİDİP HATUNLARLA KOKAİNİN DİBİNE VURACAĞIM. EFSANE GİBİ AMINA KOYAYIM!",
["be1_fwb_01_04"] = "PARA GEÇER GEÇMEZ GÖRDÜĞÜNÜZ EN KALIN ESRARLI SİGARAYI YAKACAĞIM AMINA KOYAYIM.",
["be1_fwb_01_05"] = "O PRİMİ ALINCA PARTİ ZAMANI BAŞLAYACAK. CABO SAN LUCAS BEBEĞİM, HEM DE NASIL!",
["be1_fwb_01_06"] = "PRİMİM GELİNCE SONUNDA O GİTARI ALABİLECEĞİM. HENDRİX'İN KULLANDIĞI. HANİ ELVİS'İN KIÇINA VURDUĞU VAR YA.",
["be1_fwb_01_07"] = "O KURTARMA PARASI GELDİĞİNDE MASAMI ALTIIIIIIIINLA KAPLATACAĞIM.",
["be1_fwb_01_08"] = "KURTARMA PARASI GELİR GELMEZ LÜKS FAHİŞELERE TAŞAKLARIMA KADAR GÖMÜLECEĞİM!",
["be1_fwb_01_09"] = "DOSTUM, DEVLETİN KURTARMA PARASI GELSİN, DETROİT'İ SATIN ALACAĞIM LAN!",
["be1_fwb_01_10"] = "HEP BİR HELİKOPTER İSTEMİŞİMDİR. KURTARMA PARASI GELİNCE İKİ TANE ALACAĞIM.",
["be1_fwb_01_11"] = "DEVLETİN KURTARMA PARASINI ALINCA ŞU DİNOZORLU ADAYA TAŞINACAĞIM.",
["be1_fwb_02_01"] = "EE... HARİKA. EVET, BEN DE BİRAZ ÖYLE YAPABİLİRİM.",
["be1_fwb_02_02"] = "ŞEY... MANTIKLI SANIRIM. BEN DE ÖYLE YAPABİLİRİM.",
["be1_fwb_02_03"] = "AH... EE, EVET. SANIRIM BU... İHTİYATLI OLUR.",
["be1_fwb_02_04"] = "AH... EVET. İYİ FİKİR GİBİ. SANIRIM.",
["be1_fwb_02_05"] = "AA, GERÇEKTEN Mİ? SENCE... BELKİ BEN DE YAPMALIYIM.",
["be1_fwb_02_06"] = "MANTIKLI GÖRÜNÜYOR. EVET. BELKİ BUNUN İÇİN BİRAZ KENARA AYIRIRIM.",
["be1_fwb_02_07"] = "EE, EVET. BİLİYOR MUSUN, SİKTİR ET. ONU DA YAPARIM!",
["be2_fwb_01_01"] = "ZOR ZAMANLARDAN GEÇTİĞİNİZİ ANLIYORUM. FIRST WORLD BANK GERÇEKTEN ANLIYOR. AMA NE YAZIK Kİ 'FAT PAT'İN SİGORTA PARASI GELDİĞİNDE GERİ ÖDEYECEĞİNİZ SÖZÜYLE $10,000 KREDİYE ONAY VEREMEYİZ.",
["be2_fwb_01_02"] = "ÜZGÜNÜM. BİNAMIZDA REHBERSİZ TUR SUNAMIYORUZ. HELE DE ‘BÜTÜN PARANIN TUTULDUĞU ODADA’ HİÇ SUNAMIYORUZ.",
["be2_fwb_01_03"] = "HAYIR, O TÜR BİR BANKA DEĞİL BURASI. SANIRIM HASTANEDEKİNİ ARIYORSUNUZ. YA DA YOLUN AŞAĞISINDAKİ BARI.",
["be2_fwb_01_04"] = "ÜZGÜNÜM. HAYIR. DOMUZLARIN BUNU HOŞ KARŞILAYACAĞINI SANMIYORUM. ÖLMÜŞ OLSALAR BİLE.",
["be2_fwb_01_05"] = "MAALESEF HAYIR. BANKAMIZI SATIN ALMANIZ İÇİN KREDİ VEREMEYİZ.",
["be2_fwb_01_06"] = "NE YAZIK Kİ 'OSURUK KRAKERLERİ' GİBİ BİR ŞEYİ ÜRETİP PAZARLAMA PLANINIZDA CİDDİ OLDUĞUNUZDAN ŞÜPHELİYİM.",
["be2_fwb_01_07"] = "NE YAZIK Kİ KREDİ LİMİTİNİZİ 'FAHİŞELER VE KOKAİN' GİBİ EK MASRAFLARI KARŞILAMAK İÇİN ARTIRAMAYIZ.",
["be2_fwb_01_08"] = "ÜZGÜNÜM AMA KONFEDERASYON BAYRAKLI ÇARŞAFLARA PEK TALEP OLDUĞUNU SANMIYORUM.",
["be2_fwb_02_01"] = "BAYAĞI GÜZELMİŞ. KENDİMİNKİNİ NEYE HARCAYACAĞIMI BİLMİYORUM. BELKİ UZUN VADELİ MEVDUAT SERTİFİKASINA YATIRIRIM.",
["be2_fwb_02_02"] = "KULAĞA GÜZEL GELİYOR. BENİMKİNİ 401K EMEKLİLİK HESABIMA KOYARIM SANIRIM.",
["be2_fwb_02_03"] = "KULAĞA EĞLENCELİ GELİYOR. BEN AİLEMİN KONUT KREDİSİNİ KAPATIRIM SANIRIM.",
["be2_fwb_02_04"] = "HARİKA GÖRÜNÜYOR. KREDİ KARTI BORÇLARIMI KAPATIP BİRAZINI DA BİRİKİM HESABINA KOYACAĞIM.",
["be2_fwb_02_05"] = "HEY, HARİKA! BEN HİNDİSTAN ÇELİĞİNE YATIRIM YAPIYORUM.",
["be2_fwb_02_06"] = "HARİKA! BEN BENİMKİNİ BANKADA TUTARIM GALİBA.",
["be2_fwb_02_07"] = "BU HARİKA! ARKADAŞLARIMLA VE AİLEMLE PAYLAŞMAYI DÜŞÜNÜYORUM.",
["bigbank_gensec_part1_01"] = "İYİ GÜNLER. BENEVOLENT BANK. BEN MARTİN.",
