["bkl_brn_01_01"] = "İNTİKAM!",
["bkl_brn_01_02"] = "HESAPLAŞMA VAKTİ!",
["bkl_brn_01_03"] = "BANA TANIK OLUN!",
["bkl_brn_intro_01"] = "ŞU HÂLİNİZE BAKIN OROSPU ÇOCUKLARI, APTAL GÖT MASKELERİNİZLE İÇERİ DALIYORSUNUZ. RUST'IN SİZ UCUBELERDEN BİRİ OLMAK İSTEMESİNE İNANAMIYORUM AMINA KOYAYIM. HER NEYSE, ŞİMDİ İKİ ŞEY OLACAK.",
["bkl_brn_intro_01b"] = "ÖNCE BU BOK PARÇASI TAMİRCİNİN KAFASINI UÇURACAĞIM. SONRA DA BU ODAYI SİZİN PALYAÇO KANINIZLA BOYAYACAĞIZ. EN GÜZELİ DE BUNU DURDURMAK İÇİN BİR BOK YAPAMAYACAK OLMANIZ. ",
["bkl_brn_intro_02"] = "RUST BİZİ NİYE SIRTIMIZDAN BIÇAKLADI BİLMİYORUM AMA SİKİMDE DE DEĞİL. O KIR SAÇLI PİÇİ ZATEN HİÇ SEVMEZDİM. AMA BURAYA GELEREK BÜYÜK APTALLIK ETTİNİZ, DUYDUNUZ MU LAN? ",
["bkl_brn_intro_02b"] = "BURADAN SAĞ ÇIKMANIZIN İMKÂNI YOK. ÖNCE BU TAMİRCİNİN KAFASINA KURŞUN SIKIŞIMI İZLEYECEKSİNİZ, SONRA EKİBİM SİZİ FENA SİKECEK.",
["bkl_brn_intro_03"] = "RUST'IN İHANETİNE PEK ŞAŞIRMADIM, BİLİYOR MUSUNUZ? HEP YAŞLI VE AÇGÖZLÜ BİR PİÇTİ. AMA KANIN BEDELİ KANLA ÖDENİR. BURAYA GELEREK KOCAMAN BİR HATA YAPTINIZ. ",
["bkl_brn_intro_03b"] = "BUNU KURTARMA GÖREVİ FALAN MI SANDINIZ? YOK, ÖYLE OLMAYACAK. SİZ APTALLAR ÖNCE BU BOK PARÇASI TAMİRCİYİ ÖLDÜRÜŞÜMÜ İZLEYECEKSİNİZ, SONRA ÖBÜR DÜNYADA ONA KATILACAKSINIZ.",
["bkm_cs1_01_01"] = "EVET EFENDİM, HEMEN YARDIMCI OLACAĞIZ.",
["bkm_cs1_01_02"] = "EVET HANIMEFENDİ, UYGUN ÜCRETLE ULUSLARARASI PARA TRANSFERİ SUNUYORUZ.",
["bkm_cs1_01_03"] = "YENİ HESAP. HEMEN HALLEDEBİLİRİZ.",
["bkm_cs1_01_04"] = "PARALARININ SİKİMDE OLDUĞUNU NEDEN SANIYORLAR? NEDEN?",
["bkn_pal_01_01"] = "ÇEKİL ORADAN. GÜNEŞİMİ KESİYORSUN.",
["bkn_pal_01_02"] = "NEYE BAKIYORSUN?",
["bkn_pal_01_03"] = "ÇEKİLİN ORADAN. GÜNEŞİ KESİYORSUNUZ...",
["bkn_pal_02_01"] = "BANA BİRAZ BRONZLAŞMA LOSYONU GETİR. ",
["bkn_pal_02_02"] = "BANA BİRAZ BRONZLAŞMA LOSYONU GETİRİR MİSİN?",
["bkn_pal_02_03"] = "BANA BİRAZ BRONZLAŞMA LOSYONU GETİR BEBEĞİM.",
["bkn_pal_03_01"] = "HA, BİZE BİRAZ DA OT ALSANIZ İYİ OLUR.",
["bkn_pal_03_02"] = "AH, BİZE BİRAZ DA OT GETİRSENİZE KESİNLİKLE. ",
["bkn_pal_03_03"] = "OO, BİZE KESİN BİRAZ DA OT GETİRMELİSİNİZ. ",
["bkn_pal_04_01"] = "MITCHELL, YİNE ALIŞVERİŞE GİDEBİLİR MİYİZ?",
["bkn_pal_04_02"] = "HEY MITCHELL, YİNE ALIŞVERİŞE ÇIKABİLİR MİYİM?",
["bkn_pal_05_01"] = "O HAVUZU TAMİR ET. YÜZMEK İSTİYORUM... DÜNDEN BERİ.",
["bkn_pal_05_02"] = "MITCHELL, O HAVUZU TAMİR ETTİR, TAMAM MI?",
["bkn_pal_05_03"] = "HEY MITCHELL, HAVUZ NE ZAMAN HAZIR OLACAK? ",
["bkn_pal_05_04"] = "ŞU HAVUZU TAMİR EDİN, YÜZMEK İSTİYORUM.",
["bkn_pal_05_05"] = "HEY MITCHELL... HAVUZ NE ZAMAN HAZIR OLACAK?",
["blm_cs1_01_01"] = "ORADA NE DÖNDÜĞÜNÜ BİLİYORUM, BEN DE PASTADAN PAYIMI İSTİYORUM. BİR ÇANTAYI PARAYLA DOLDURUP OTO TAMİRCİSİ JİMBOS'UN YANINDAKİ SARI DUVARIN ÜZERİNDEN ATIN. DUYDUNUZ MU? SOKAKTAN GEÇEN TEK BİR ÇANTA GÖRÜRSEM POLİSİ ARARIM.",
["blm_cs1_01_02"] = "HEY, PİSLİKLER. 911'İ ARAMAMI İSTEMİYORSANIZ TAMİRHANENİN YANINDAKİ SARI DUVARDAN BİR PARA ÇANTASI ATIN. HEMEN! SİZ OROSPU ÇOCUKLARINDAN BİRİNİN BİR ÇANTAYI KARŞIYA GEÇİRMEYE ÇALIŞTIĞINI GÖRÜRSEM POLİSİ ARARIM.",
["blm_cs1_01_03"] = "BENİ TANIMIYORSUNUZ AMA NE ÇEVİRDİĞİNİZİ GÖRÜYORUM, BEN DE PAY İSTİYORUM. JİMBO'S'UN YANINDAKİ SARI DUVARIN ÜZERİNDEN BİRAZ PARA ATIN. HİÇBİRİNİZ SAKIN KARŞIYA GEÇMEYE KALKIŞMASIN, YOKSA POLİSİ ARARIM. DUYDUNUZ MU?",
["bm_ability_chico_injector"] = "ENJEKTÖR",
["bm_ability_chico_injector_desc"] = "KULLANILDIĞINDA KULLANICI ACI HİSSETMEZ VE KORKUSUZLAŞIR. ACI DUYMAMASI, ÇATIŞMANIN KALBİNDE HERKESTEN UZUN SÜRE ORTALIĞI KASIP KAVURMASINI SAĞLAR. KORKUSUZLUĞUYSA ONU DÜŞMANLARI İÇİN KORKUTUCU VE BARİZ BİR TEHDİDE DÖNÜŞTÜRÜR.",
["bm_ace_desc"] = "ÇOK ESKİDEN, GÜNEYDOĞU ASYA’DAKİ GİZLİ VE SON DERECE TEHLİKELİ BİR PARALI ASKER GÖREVİNDE CHAINS BU ESKİ ABD ORDUSU MİĞFERİNİ EDİNDİ. ÖNCEKİ SAHİBİNİN KİM OLDUĞUNU KİMSE BİLMİYOR.",
["bm_al_pacino_desc"] = "SUÇ HAYATINI GERÇEKTEN ÖZENECEK BİR ŞEYE DÖNÜŞTÜREN ASIL MAFYA BABASI. BUGÜN YAŞASAYDI PAYDAY EKİBİNİN KESİN ÜYESİ OLURDU. AMA EN AZINDAN KILIĞINA GİRİP HAYALET GÖRDÜKLERİNİ SANAN POLİSLERİ KORKUTABİLİRSİN.",
["bm_armor_chainmail"] = "ZİNCİR ZIRH",
["bm_armor_leather"] = "DERİ",
["bm_armor_level_1"] = "İKİ PARÇALI TAKIM ELBİSE",
["bm_armor_level_1_desc"] = "HAREKET CEZASI YOK, DİKKAT ÇEKMEZ.$NL;$NL;KENDİNE SAYGISI OLAN HER SUÇLUNUN GİYMESİ GEREKEN STANDART İKİ PARÇALI TAKIM ELBİSEDİR.$NL;$NL;EK KORUMA SAĞLAMAZ AMA EN YÜKSEK GİZLENEBİLİRLİĞE SAHİPTİR. FARK EDİLMEDEN KALABALIĞA KARIŞMAK İSTEDİĞİN SOYGUNLAR İÇİN EN İYİ SEÇİMDİR.$NL;$NL;TAKIM ELBİSELER GENELLİKLE DÜĞÜN, CENAZE VE BANKA SOYGUNU GİBİ ÖZEL GÜNLERE SAKLANIR.",
["bm_armor_level_2"] = "HAFİF BALİSTİK YELEK",
["bm_armor_level_2_desc"] = "HAFİF HAREKET CEZASI, DÜŞÜK GÖRÜNÜRLÜK.$NL;$NL;HAFİF BALİSTİK YELEK, GİYMESİ KOLAY VE GİZLENEBİLİR BİR KURŞUNGEÇİRMEZ YELEKTİR. ÖZEL GELİŞTİRİLMİŞ TRAVMA ASTARI, KÜNT DARBELERİN ETKİLERİNE KARŞI ETKİLİ KORUMA SAĞLAYARAK ONU İYİ BİR SAVUNMA SEÇENEĞİ YAPAR.$NL;$NL;HAFİF BALİSTİK YELEKLER; DEVLET BÜYÜKLERİ, ÖNEMLİ KİŞİLER, HAVA GÜVENLİĞİ GÖREVLİLERİ VE ÜST DÜZEY YÖNETİCİ VE DİPLOMAT KORUMALARI TARAFINDAN KULLANILIR.",
["bm_armor_level_3"] = "BALİSTİK YELEK",
["bm_armor_level_3_desc"] = "HAFİF HAREKET CEZASI, DÜŞÜK GÖRÜNÜRLÜK.$NL;$NL;BALİSTİK YELEK, GÖVDEYE GİYİLEN, STANDART KULLANIMDA OLAN YUMUŞAK YAPILI KURŞUNA DAYANIKLI BİR YELEKTİR. KÜÇÜK KALİBRELİ TABANCA VE POMPALI TÜFEK MERMİLERİNE KARŞI İYİ KORUMA SAĞLAYARAK ATEŞ HATTINDAKİ HERKES İÇİN TEMEL BİR EKİPMAN OLUR.$NL;$NL;BALİSTİK YELEKLER; POLİSLER, GÜVENLİK GÖREVLİLERİ VE KORUMALAR TARAFINDAN KULLANILIR.",
["bm_armor_level_4"] = "AĞIR BALİSTİK YELEK",
["bm_armor_level_4_desc"] = "AZ HAREKET CEZASI, ORTA GÖRÜNÜRLÜK.$NL;$NL;AĞIR BALİSTİK YELEK, GÖVDEYE GİYİLEN VE SERT PLAKALARLA GÜÇLENDİRİLMİŞ BİR YELEKTİR. BALİSTİK YELEĞİ OMUZ VE YAN KORUMA PARÇALARIYLA BİRLEŞTİREN MODERN BİR VÜCUT ZIRHI OLARAK GÜÇLÜ BİR KORUMA SUNAR.$NL;$NL;AĞIR BALİSTİK YELEKLER; ASKERLER, POLİS TAKTİK BİRİMLERİ VE REHİNE KURTARMA EKİPLERİ TARAFINDAN KULLANILIR.",
["bm_armor_level_5"] = "ŞARAPNEL YELEĞİ",
["bm_armor_level_5_desc"] = "ORTA HAREKET CEZASI, ORTA GÖRÜNÜRLÜK.$NL;$NL;GENSEC SECURİTY INDUSTRİES ÜRETİMİ ŞARAPNEL YELEĞİ, KLASİK TASARIMIN MODERN BİR YORUMUDUR. ATEŞLİ SİLAH MERMİLERİNİN VE PATLAMALARDAN SAÇILAN ŞARAPNELLERİN DARBESİNİ EMER.$NL;$NL;AĞIR BALİSTİK YELEĞİ OMUZ VE YAN KORUMA PARÇALARIYLA BİRLEŞTİRİR; AYRICA OMURGAYI DA KORUR.$NL;$NL;ŞARAPNEL YELEKLERİ; DENİZ PİYADELERİ, MUHARİP ASKERLER VE GENSEC FTSU GÖREV KUVVETLERİ TARAFINDAN KULLANILIR.",
["bm_armor_level_6"] = "BİRLEŞİK TAKTİK YELEK",
["bm_armor_level_6_desc"] = "ORTA HAREKET CEZASI, YÜKSEK GÖRÜNÜRLÜK.$NL;$NL;BİRLEŞİK TAKTİK YELEK, MODERN SAVAŞIN ZORLUKLARI NEDENİYLE GELİŞTİRİLDİ. YÜKSEK PERFORMANSLI BALİSTİK MALZEMELERDEN YAPILIR VE MÜHİMMAT KESELERİ, TELSİZLER VE DİĞER AKSESUARLAR GİBİ AĞIR YÜKLERİ TAŞIMAK İÇİN TASARLANMIŞTIR. $NL;$NL;BİRLEŞİK TAKTİK YELEKLER, DÜNYANIN DÖRT BİR YANINDAKİ ASKERLER, ÖZEL KUVVETLER VE DİĞER DÜZENLİ ASKERÎ BİRİMLER TARAFINDAN KULLANILIR.",
["bm_armor_level_7"] = "GELİŞTİRİLMİŞ BİRLEŞİK TAKTİK YELEK",
["bm_armor_level_7_desc"] = "AĞIR HAREKET CEZASI, YÜKSEK GÖRÜNÜRLÜK.$NL;$NL;GELİŞTİRİLMİŞ BİRLEŞİK TAKTİK YELEK, GENSEC SECURİTY INDUSTRİES TARAFINDAN ÜRETİLMİŞ, ÇALINMIŞ DENEYSEL BİR PROTOTİPTİR.$NL;$NL;WHİTE MESA TEKNOLOJİSİNE DAYANIR VE HEM YUMUŞAK HEM DE SERT ZIRH ÇÖZÜMLERİNİ KULLANIR. METAL PLAKALARLA SIKICA ÖRÜLMÜŞ, BİRBİRİNE TAM OTURAN KİLİTLİ LİF KATMANLARI; MERMİLERİ SAPTIRMAK VE PATLAMALARDAN KORUMAK İÇİN ÖZEL AÇILARLA YERLEŞTİRİLMİŞTİR. KISACASI TAM KORUMA SAĞLAR.",
["bm_armor_scale"] = "PUL",
["bm_askn_cas_police"] = "POLİS",
["bm_askn_find_in_crime_spree"] = "BU ZIRH ##SUÇ SERİSİ## OYUN MODUNDA KAZANILABİLİR. KAPLAMA TAKAS EDİLEMEZ VEYA SATILAMAZ.",
["bm_askn_none"] = "KAPLAMA YOK",
["bm_askn_tam_unlock"] = "BU ZIRH ##1000 BAŞARIM DÖNÜM NOKTASI## ÖDÜLÜ OLARAK KAZANILIR. KAPLAMA TAKAS EDİLEMEZ VEYA SATILAMAZ.",
["bm_bandana_desc"] = "BU KIRMIZI ALIN BANDINI TAKAN ASKERİN KİMLİĞİ GİZLİ. SIZAN RAPORLAR, GERİLLA TAKTİKLERİNDE UZMAN BİR SAVAŞ GAZİSİNDEN VE ESKİ BİR U.S. ARMY SPECIAL FORCES ASKERİNDEN SÖZ EDİYOR. SİLAH ARKADAŞLARI ONU SERT, GÖZÜ KARA VE AŞIRI SALDIRGAN DİYE TANIMLIYORDU. İZİNİ BULUP KATLETTİĞİ ÜST DÜZEY SUBAY SAYISINA BAKILIRSA OTORİTEYLE CİDDİ BİR SORUNU OLABİLİR...",
["bm_beret_desc"] = "CHAINS BU BEREYİ BATI AFRİKA’DAKİ BİR PARALI ASKER OPERASYONUNA HAZIRLANIRKEN ÖZEL YAPTIRDI. AMA ONU TAKARKEN NELER YAPTIĞINI ANLATMIYOR.",
["bm_bugsy_desc"] = "AL CAPONE’UN RAKİBİ. İÇKİ YASAĞI DÖNEMİ BİRKAÇ ŞİŞE VİSKİ BULABİLEN HERKESE İÇKİYİ ALTINA ÇEVİRİRKEN BU İKİ ADAM KAPIŞIYORDU. CAPONE, KÖTÜ ŞÖHRETLİ SAİNT VALENTİNE’S DAY MASSACRE SIRASINDA ONU VURDURMAYA BİLE ÇALIŞTI. AMA BAŞARAMADI.",
["bm_c_trousers1"] = "PANTOLON 1",
["bm_c_trousers2"] = "PANTOLON 2",
["bm_c_trousers3"] = "PANTOLON 3",
["bm_c_trousers4"] = "PANTOLON 4",
["bm_cap_n_beard_desc"] = "ÇOK GİZLİ RAPORLARDA SEÇKİN BİR ÖZEL HAREKÂT BİRLİĞİNİN BU ASKERİNDEN SÖZ EDİLİYOR. ÖNEMLİ ASKERÎ OPERASYONLARA KATILIYOR, SÜREKLİ TETİKTE YAŞIYORDU; HAYATI AŞIRI BASKI VE KESİNTİSİZ ADRENALİNLE GEÇİYORDU. KANITLAR, HASSAS BİR STRATEJİK OPERASYON SIRASINDA KENDİ BİRLİĞİNE SALDIRDIĞINI GÖSTERİYOR. AMA KATLİAMDAN SAĞ KALAN OLMADIĞI İÇİN KİMSE KESİN OLARAK BİLMİYOR. ASKER FİRAR ETTİ VE O GÜNDEN BERİ BİR DAHA GÖRÜLMEDİ.",
["bm_chains_rising_desc"] = "KARANLIĞA GİR, ÇAĞRIYI DUY VE PARMAĞI TETİKTE BİR KÂBUS GÖZÜ KARASINA DÖNÜŞ. BU, SAHADA ÖLÜMÜ ALDATTIĞIN TÜM ANLARA BİR SAYGI DURUŞUDUR. KARANLIK ORDUSUNUN ASKERİSİN. DAMARLARINDA ADRENALİN AKIYOR; CEHENNEME BİLE MEYDAN OKUYACAK KADAR MÜHİMMAT TAŞIYORSUN. KARANLIKTA YENİLMEZ, ÖLÜME MEYDAN OKUMAYA HAZIRSIN. BU KEZ TÜM ZİNCİRLER KIRILACAK VE YOLUNA ÇIKAN HERKES YARATICISINA KAVUŞACAK.",
["bm_cloaker_desc"] = "FİZİK YASALARINI BİR ŞEKİLDE BÜKEN, \"CLOAKER\" LAKAPLI WPD ÖZEL BİRİMİ, HER ŞEYİ TEK BAŞINA YAPABİLECEĞİNİ KANITLAMAYA ÇALIŞAN KÖTÜ ADAMLARIN BAŞ BELASIDIR. SÖYLENTİYE GÖRE İLK CLOAKER, KİMSENİN EKİP KURMAK İSTEMEDİĞİ SIRADAN BİR SWAT POLİSİYDİ. BUNUN NEDENİ BELKİ DE ETRAFINDA MERMİLER UÇUŞURKEN KUNG FU TEKMELERİ SAVURAN KAÇIK BİR ÖLÜM MAKİNESİ OLMASIYDI. NEREDEYSE HER ZAMAN AŞIRI GÜÇ KULLANIR; EKİBİYLE BİRLİKTE TÜM SAVAŞ TAKTİKLERİNİ GERİDE BIRAKIRDI. AMA SONUÇ ALIYORDU. ÜSTLERİ DE ONU GÖREVDE TUTUP BENZER KAFADAKİLERİ EĞİTMESİNİ SAĞLADI.$NL;$NL;GECE GÖRÜŞÜ MODUNU ETKİNLEŞTİRMEK İÇİN ATIŞ MODU DÜĞMESİNİ BASILI TUT.",
