["bm_concussion"] = "SERSEMLETİCİ EL BOMBASI",
["bm_concussion_desc"] = "BU SERSEMLETEN KÜÇÜK GÜZELLİK HERKESİN NEFESİNİ KESECEK, ONLARI ÖLDÜRMEK İÇİN GEREKEN FAZLADAN BİRKAÇ SANİYEYİ SANA VERECEK.",
["bm_cop_kawaii_desc"] = "KAWAİİ ADINA SENİ CEZALANDIRACAĞIM! AŞK İÇİN, ADALET İÇİN, MERCURY BUBBLE BLAST İÇİN!$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_cop_mega_skull_desc"] = "SIKI SOYGUNCULARIN KENDİLERİNE NEDEN DEATH WİSHERS DEMEDİĞİNİ HİÇ ANLAMADIK. BELKİ FAZLA HAVALIDIR.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_cop_plague_doctor_desc"] = "YILLARCA İYİLEŞTİRMEK ONU YIPRATTI. İNSANLARIN ÇARESİZLİKTEN DOĞAN ZALİM YOLLARINA TANIK OLDU. VEBAYI BİR HASTALIK OLARAK GÖRMEKTEN VAZGEÇİP ÇARE OLARAK YAYMAYA BAŞLADI.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_cs_continental_coin_cost"] = "$cost; SİKKE",
["bm_cs_not_enough_coins"] = "YETERLİ SİKKE YOK",
["bm_dallas_rising_desc"] = "BUGÜNÜN TOPLUMUNUN HER LİFİNE İŞLEYEN ÇÜRÜMÜŞ YOZLAŞMAYA SERT BİR KARŞILIK VERMEK GEREKİYOR. KENDİNİ KANDIRMAYA, SAHTE BİR GÜVENLİK DUYGUSU İÇİN ÇIRPINMAYA. AMA GÜVENDE DEĞİLSİN; NE ŞİMDİ NE DE HİÇBİR ZAMAN. AMERİKAN RÜYASI, ZAVALLI RUHLARI YOLDAN ÇIKARMAK İÇİN KILIK DEĞİŞTİRMİŞ, KORKUNÇ YARALARLA DOLU BİR KÂBUS. İHTİYACINI AL; GELECEĞİNİ BOĞAZINDAN YAKALA, HIRSINI BOĞULANA KADAR BOĞAZINDAN AŞAĞI TIK. GEÇTİĞİN YERLERİ ARKANDA BIRAKTIĞIN CESETLERLE İŞARETLE.",
["bm_donald_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETMEYİ AMAÇLIYORDU. KONUŞKAN BİR ADAM OLDUĞUNA ŞÜPHE YOK.$NL;$NL;45. BAŞKAN, TARİHİN EN TARTIŞMALI BAŞKANLARINDAN BİRİYDİ. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_donald_mega_desc"] = "ÖNÜNDE EĞİL.$NL;$NL;MEGA 45TH MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_dynamite"] = "DİNAMİT",
["bm_dynamite_desc"] = "İSVEÇLİ MÜHENDİS ALFRED NOBEL DİNAMİTİ VE KAYALARI PATLATMADAKİ ETKİSİNİ KEŞFETTİ. AMA İNSANLARI PATLATMADAKİ ETKİSİNİ KEŞFEDEN, SARHOŞ MADEN ARAYICISI OL’ KENNETH OLDU.",
["bm_e_wish_desc"] = "TAM POTANSİYELİNE AZ KALDI. DEĞİŞİMİ KUCAKLA. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. AMA BU İNSAN KAFATASINA BENZEMİYOR; YİNE DE ENDİŞELENMENE GEREK YOK.$NL;$NL;BÜTÜN SOYGUNLARI MAYHEM ZORLUĞUNDA BİTİRDİN Mİ? SEN NESİN, YARATIK FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_equipment_ammo_bag"] = "MÜHİMMAT ÇANTASI",
["bm_equipment_ammo_bag_desc"] = "MÜHİMMAT ÇANTASINI YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. YERLEŞTİRİLEN ÇANTA TAŞINAMAZ. SEN VEYA EKİP ARKADAŞLARIN, $BTN_INTERACT; TUŞUNU BASILI TUTARAK ÇANTADAN MÜHİMMAT ALABİLİR. ÇANTA, SİLAHLARINDAN BİRİNİN MÜHİMMATINI DÖRT KEZ TAMAMEN DOLDURABİLİR. MÜHİMMAT ÇANTASININ İÇERİĞİ TÜKENDİĞİNDE ÇANTA KAYBOLUR. KALAN MÜHİMMAT MİKTARINI ÇANTAYA BAKARAK ANLAYABİLİRSİN.$NL;$NL;MÜHİMMAT ÇANTASI, ASKERLERİN ÇATIŞMAYA EK MÜHİMMAT TAŞIMASINI SAĞLAMAK AMACIYLA TASARLANMIŞ TAŞINABİLİR BİR ÇANTADIR.",
["bm_equipment_armor_kit"] = "ZIRH ÇANTASI",
["bm_equipment_armor_kit_desc"] = "ZIRH ÇANTASINI KULLANMAK İÇİN $BTN_USE_ITEM; DÜĞMESİNİ BASILI TUTARAK SEÇİLİ ZIRHINI GİY. O ZAMANA KADAR İKİ PARÇALI TAKIM ELBİSE GİYERSİN.$NL;$NL;ZIRH ÇANTASI YALNIZCA BİR KEZ KULLANILIR VE KULLANILDIĞINDA KAYBOLUR. ZIRH ÇANTASI, SEÇTİĞİN ZIRHI TAŞIMAYA YARAYAN, SOYGUN SIRASINDA KULLANILABİLEN TAŞINABİLİR BİR ÇANTADIR.",
["bm_equipment_bodybags_bag"] = "CESET TORBASI ÇANTASI",
["bm_equipment_bodybags_bag_desc"] = "CESET TORBASI KUTUSUNU KULLANMAK İÇİN $BTN_USE_ITEM; DÜĞMESİNİ BASILI TUTARAK YERLEŞTİR. YERLEŞTİRİLDİKTEN SONRA TAŞINAMAZ. SEN VE EKİBİN $BTN_INTERACT; DÜĞMESİNİ BASILI TUTARAK İÇİNDEN CESET TORBASI ALABİLİRSİNİZ.$NL;$NL;CESET TORBASI KUTUSUNUN KULLANIM SAYISI SINIRLIDIR. KALAN KULLANIM SAYISINI CESET TORBASI KUTUSUNA BAKARAK GÖREBİLİRSİN. CESET TORBASI KUTUSU, GİZLİLİK SIRASINDA CESETLERİ TAŞIMAK İÇİN EK TORBALAR İÇERİR.",
["bm_equipment_doctor_bag"] = "DOKTOR ÇANTASI",
["bm_equipment_doctor_bag_desc"] = "DOKTOR ÇANTASINI YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. YERLEŞTİRİLEN ÇANTA TAŞINAMAZ. SEN VEYA EKİP ARKADAŞLARIN, $BTN_INTERACT; TUŞUNU BASILI TUTARAK ÇANTAYI KULLANABİLİR VE SAĞLIĞINI YENİLEYEBİLİR. DOKTOR ÇANTASINI KULLANMAK, GÖZALTINA ALINMADAN ÖNCE YERE DÜŞEBİLECEĞİN KALAN HAKLARINI DA YENİLER. ÇANTA İKİ KEZ KULLANILABİLİR.$NL;$NL;DOKTOR ÇANTASININ KULLANIM HAKKI TÜKENDİĞİNDE ÇANTA KAYBOLUR. KALAN KULLANIM SAYISINI ÇANTAYA BAKARAK ANLAYABİLİRSİN.$NL;$NL;DOKTOR ÇANTASI, HEKİMLERİN VE DİĞER SAĞLIK ÇALIŞANLARININ TIBBİ MALZEME VE İLAÇ TAŞIMAK İÇİN KULLANDIĞI TAŞINABİLİR BİR ÇANTADIR.",
["bm_equipment_ecm_jammer"] = "ECM KARIŞTIRICI",
["bm_equipment_ecm_jammer_desc"] = "ECM KARIŞTIRICIYI YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. YERLEŞTİRİLEN CİHAZ TAŞINAMAZ VE 20 SANİYE BOYUNCA ETKİN KALIR.$NL;$NL;$BTN_INTERACT; TUŞUNA BASARAK ECM KARIŞTIRICININ GERİ BESLEME İŞLEVİNİ AÇIP KAPATABİLİRSİN. BU İŞLEVİN, BELİRLİ BİR YARIÇAP İÇİNDEKİ DÜŞMANLARI ETKİSİZ HÂLE GETİRME ŞANSI VARDIR. KULLANIM SÜRESİ DOLDUĞUNDA CİHAZ ÇALIŞMAYI DURDURUR.$NL;$NL;ELEKTRONİK KARŞI TEDBİR (ECM), RADAR, SONAR VE DİĞER TESPİT SİSTEMLERİNİ YANILTMAK İÇİN TASARLANMIŞ BİR ELEKTRONİK CİHAZDIR. HEDEFİNE ULAŞMANI KOLAYLAŞTIRIR.",
["bm_equipment_first_aid_kit"] = "İLK YARDIM KİTİ",
["bm_equipment_first_aid_kit_desc"] = "İLK YARDIM KİTİ, İLK YARDIM İÇİN GEREKEN TIBBİ MALZEME VE EKİPMANLARI İÇERİR.$NL;$NL;İLK YARDIM KİTİNİ YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. YERLEŞTİRİLEN KİT TAŞINAMAZ. SEN VEYA EKİP ARKADAŞLARIN, $BTN_INTERACT; TUŞUNU BASILI TUTARAK KİTİ KULLANABİLİR VE SAĞLIĞINI YENİLEYEBİLİR.$NL;$NL;HER İLK YARDIM KİTİ BİR KEZ KULLANILABİLİR. KULLANILDIKTAN SONRA KAYBOLUR.",
["bm_equipment_grenade_crate"] = "PATLAYICI ÇANTASI",
["bm_equipment_grenade_crate_desc"] = "PATLAYICI ÇANTASINI KULLANMAK İÇİN $BTN_USE_ITEM; DÜĞMESİNİ BASILI TUTARAK YERLEŞTİR. YERLEŞTİRİLDİKTEN SONRA TAŞINAMAZ AMA HEM SEN HEM DE EKİBİN KULLANABİLİR. FIRLATILABİLİR EŞYALARINI YENİLEMEK İÇİN PATLAYICI ÇANTASININ YAKININDA $BTN_INTERACT; DÜĞMESİNİ BASILI TUT. YALNIZCA DÖRT KEZ KULLANILABİLİR.$NL;$NL;PATLAYICI ÇANTASI TÜKENDİĞİNDE KAYBOLUR. KALAN KULLANIM SAYISINI PATLAYICI ÇANTASINA BAKARAK GÖREBİLİRSİN. $NL;$NL;PATLAYICI ÇANTASI, MUHAREBE PERSONELİNİN PATLAYICILARI VE DİĞER FIRLATILABİLİR SİLAHLARI ÇATIŞMA ALANINA TAŞIMAK İÇİN KULLANDIĞI TAŞINABİLİR BİR ÇANTADIR.",
["bm_equipment_sentry_gun"] = "OTOMATİK TARET",
["bm_equipment_sentry_gun_desc"] = "OTOMATİK TARETİ YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. TARETİ YERLEŞTİRMEK, SİLAHLARINDAKİ TOPLAM MÜHİMMATIN %30'UNU TÜKETİR. TARET ATEŞ EDİLEREK YOK EDİLEBİLİR. TAMAMEN YOK EDİLMEDİĞİ SÜRECE TARETİ GERİ TOPLAMAK, ONU OTOMATİK OLARAK ONARIR VE İÇİNDE KALAN MÜHİMMATI İADE EDER. MÜHİMMATI BİTTİĞİNDE ATEŞ ETMEYİ DURDURUR. TARETİ GERİ TOPLAYIP YENİDEN YERLEŞTİREREK DOLDURABİLİRSİN.$NL;$NL;OTOMATİK TARET, SENSÖRLERİNİN ALGILADIĞI HEDEFLERE OTOMATİK OLARAK NİŞAN ALIR VE ATEŞ EDER. GENELLİKLE DÜŞMANLARIN DİKKATİNİ SENDEN VE EKİBİNDEN UZAKLAŞTIRMAK İÇİN KULLANILIR.",
["bm_equipment_sentry_gun_old"] = "OTOMATİK TARET",
["bm_equipment_sentry_gun_old_desc"] = "OTOMATİK TARET, SENSÖRLERİNİN ALGILADIĞI HEDEFLERE OTOMATİK OLARAK NİŞAN ALAN VE ATEŞ EDEN BİR SİLAHTIR. ASKERÎ TARETLER GEÇMİŞTE YAKIN MESAFEDEN GELEN FÜZELERİ VE DÜŞMAN UÇAKLARINI TESPİT EDİP YOK ETMEK İÇİN KULLANILMIŞTIR.$NL;$NL;OTOMATİK TARETİ YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. YERLEŞTİRİLEN TARET TAŞINAMAZ. TARET ATEŞ EDİLEREK YOK EDİLEBİLİR. MÜHİMMATI BİTTİĞİNDE ATEŞ ETMEYİ DURDURUR.",
["bm_equipment_sentry_gun_silent"] = "SUSTURUCULU OTOMATİK TARET",
["bm_equipment_sentry_gun_silent_desc"] = "SUSTURUCULU OTOMATİK TARETİ YERLEŞTİRMEK İÇİN $BTN_USE_ITEM; TUŞUNU BASILI TUT. TARETİ YERLEŞTİRMEK, SİLAHLARINDAKİ TOPLAM MÜHİMMATIN %30'UNU TÜKETİR. TARET ATEŞ EDİLEREK YOK EDİLEBİLİR. TAMAMEN YOK EDİLMEDİĞİ SÜRECE TARETİ GERİ TOPLAMAK, ONU OTOMATİK OLARAK ONARIR VE İÇİNDE KALAN MÜHİMMATI İADE EDER. MÜHİMMATI BİTTİĞİNDE ATEŞ ETMEYİ DURDURUR. TARETİ GERİ TOPLAYIP YENİDEN YERLEŞTİREREK DOLDURABİLİRSİN.$NL;$NL;SUSTURUCULU OTOMATİK TARET, STANDART OTOMATİK TARETİN DAHA SESSİZ SÜRÜMÜDÜR. DİKKAT DAĞITMAKTAN ÇOK DÜŞMANLARI ORTADAN KALDIRMAK İÇİN KULLANILIR.",
["bm_equipment_trip_mine_desc"] = "TUZAK MAYININI KULLANMAK İÇİN $BTN_USE_ITEM; DÜĞMESİNİ BASILI TUTARAK YERLEŞTİR. $BTN_INTERACT; DÜĞMESİNE BASARAK TETİKLEYİCİ LAZERİ PATLAMA VE ALGILAMA MODLARI ARASINDA DEĞİŞTİREBİLİRSİN.$NL;$NL;YÖNLENDİRİLMİŞ PATLAYICILARI KULLANMAK İÇİN $BTN_USE_ITEM; DÜĞMESİNİ BASILI TUTARAK YERLEŞTİR. YERLEŞTİRİLEN PATLAYICI BİRKAÇ SANİYE İÇİNDE PATLAR. TUZAK MAYINLARI, IŞINI GEÇEN DÜŞMANLARI YARALAYAN VEYA ÖLDÜREN TUZAKLARDIR. YÖNLENDİRİLMİŞ PATLAYICILAR GENELLİKLE KASA VE KAPILARI AÇMAK İÇİN KULLANILIR. İKİSİ DE HER TÜRLÜ ÇATIŞMADA İYİ BİR DESTEKTİR.",
["bm_fwb_01_01"] = "YAPMIYOR MU? PEKİ DÜNYANIN GERİ KALANIYLA NASIL İLETİŞİM KURUYOR?",
["bm_fwb_01_02"] = "BU PAHA BİÇİLEMEZ!",
["bm_fwb_01_03"] = "EVET, ISINMA KREDİSİ! BEN DE DEDİM Kİ: \"YETİMLER BİRBİRLERİNE BİRAZ DAHA SOKULSALAR OLMAZ MI?\" ",
["bm_fwb_01_04"] = "EVET, HAHAHA. EVET, ONLARA \"MUHASEBE HATASI\" DEDİM. ",
["bm_fwb_01_05"] = "BİLİRSİN İŞTE, GÜLÜMSERSİN, BAŞINI SALLARSIN. AMA ÇİZGİNİN ÜSTÜNÜ İMZALADILAR MI... RUHLARI SENİNDİR!",
["bm_fwb_01_06"] = "O KURTARMA PARASI GELİR GELMEZ İLK YAPTIĞIM ŞEY BİR LONGFELLOW ALMAK OLDU. HEY, OTOMOTİV SEKTÖRÜNÜ DESTEKLİYORUM!",
["bm_fwb_01_07"] = "KREDİ İSTEYEN ADAMA FTS YÖNETMELİĞİ YÜZÜNDEN VEREMEYİZ DEDİM. FTS Mİ? FUCK THAT SHİT. YANİ SİKTİR ET O BOKU!",
["bm_fwb_01_08"] = "BİR ÖĞRENCİ GELİYOR, KREDİSİNİ YENİDEN YAPILANDIRMAK İSTİYOR. BİLİYORUM! HAHAHAHAHA. NE APTAL AMA!",
["bm_fwb_01_09"] = "HEY, O RAPORDA İYİ İŞ ÇIKARDIN! ",
["bm_fwb_01_10"] = "O RAPOR NE KADAR SÜRDÜ? BİR SAAT Mİ? ON SAAT YAZIN FATURAYA.",
["bm_fwb_01_11"] = "ÇOCUKLARLA LONGFELLOW'A ATLAYIP KIYI BOYUNCA GİTTİK. I-95'TE YÜZ MİLE ÇIKTIK. BİR OKUL OTOBÜSÜNE DE ÇIKTIK. SİKEYİM O ÇOCUKLARI!",
["bm_fwb_01_12"] = "MAKARNA RESTORANI İÇİN KREDİ İSTEYEN ŞU KADINI GÖRÜYOR MUSUN? ORAYA BİR ŞEYLER YATIRMAYI ÇOK İSTERDİM.",
["bm_fwb_01_13"] = "YİNE GENEL MERKEZDEKİ İNSAN KAYNAKLARINA ÇAĞIRDILAR. MEĞER BİR BÜYÜKANNEYE BİR TORBA... SİKTİR, DİNLİYOR OLABİLİRLER.",
["bm_fwb_01_14"] = "HAFTA SONUNU LONGFELLOW'U CİLALAYARAK GEÇİRDİM. ŞEFİN KARISINI GEZMEYE ÇIKARDIM. ONUN DA ŞUNU CİLALAMASINA İZİN VERDİM... ANLADIN SEN DOSTUM!",
["bm_fwb_02_01"] = "BAKIN BAŞRAHİBE, YA $300 ÖDERSİNİZ YA DA BACAKLARINIZI KIRARIZ!",
["bm_fwb_02_02"] = "SAKAT ÇOCUKLARIN DİFTERİ OLMUŞ, SİKİMDE BİLE DEĞİL!",
["bm_fwb_02_03"] = "YARDIM MI İSTİYORSUN? ALACAKSIN, ÇÜNKÜ DOĞRU SOSYAL YARDIMA GİDİYORSUN BACIM!",
["bm_fwb_02_04"] = "BAK, KREDİYİ ÖDERSİN YA DA EVİ KAYBEDERSİN. CİDDİYİM ANNE!",
["bm_fwb_02_05"] = "SİZE O KOŞULLARI GAZİ PROGRAMI KAPSAMINDA SUNDUĞUMUZU BİLİYORUM AMA VİETNAM \"OLAYINI\" ARTIK GERÇEK BİR ÇATIŞMA SAYMIYORUZ!",
["bm_fwb_02_06"] = "EVET, STANDART UYGULAMA. ULUSLARARASI HAVALE İÇİN 15 İŞ GÜNÜ. HI HI. PEKİ, SİZE DE BOL SİKTİRLER EFENDİM!",
["bm_fwb_02_07"] = "BENCE DAHA ÇOK KESİNTİ YAPABİLİRİZ, EVET. BÜTÜN BU VEZNEDARLARA İHTİYACIMIZ YOK. İNSANLAR BİR SAAT KUYRUKTA BEKLESE KİMİN UMURUNDA!",
["bm_fwb_02_08"] = "ÜNİVERSİTE HARCIN İÇİN İKİ SIÇIMLIK BİLE UMURSAMAM. GERÇİ SIÇIM BAŞINA 50 BİN DOLAR VERİRSEN BAŞKA.",
["bm_fwb_02_09"] = "SİZE KAÇ KERE SÖYLEMEM GEREKİYOR? BİZ BANKAYIZ. BİZE GÜVENİLMEMESİ GEREKİYOR.",
["bm_fwb_03_01"] = "LONDRA'DAKİ FİNANCİAL TİMES'LA KONUŞMAK BİR ZEVK. AH, LONDRA DEĞİL, LONDON, KENTUCKY.",
["bm_fwb_03_02"] = "YÖNETİM TARZIMI, YÖNETİM KURULU DİNAMİĞİNE YENİ BİR SİNERJİ GETİREN PARALEL... TARZLANDIRMA OLARAK TANIMLARIM.",
["bm_fwb_03_03"] = "FİNANS DÜNYASI HİÇ BU KADAR SAĞLIKLI OLMAMIŞTI! SON BİR GÜNDE SADECE ON ÇALIŞANI İŞTEN ÇIKARDIK.",
["bm_fwb_03_04"] = "BANKAYA YATIRIM EV KADAR SAĞLAMDIR. HEM DE GÜZEL EVLERDEN, TUĞLASI FALAN OLANLARDAN BAHSEDİYORUM!",
["bm_fwb_03_05"] = "EVET, OKURLARINIZA FIRST WORLD BANK'İN KALICI OLDUĞUNU GARANTİ EDERİM. KOLOMBİYA DENİZALTI SEKTÖRÜNDE GÜÇLÜ YATIRIMLARIMIZ VAR.",
["bm_fwb_03_06"] = "RAKİPLERİMİZ KRİZDE AĞIR DARBE ALDI AMA BAŞKANIMIZ PARAYI BAHÇESİNE GÖMDÜĞÜ İÇİN BİZ ÇOĞUNU ATLATTIK.",
["bm_fwb_03_07"] = "BİR ÇİN BANKASININ YATIRIM YAPTIĞI SÖYLENTİLERİNİ YORUMLAYAMAM AMA ŞAHSEN ASYALI EFENDİLERİMİZE HOŞ GELDİNİZ DERİM. ",
["bm_fwb_03_08"] = "ELBETTE ÇOK ÇEŞİTLİ ÇALIŞANLARIMIZ VAR. HATTA LATİN BÖLÜMÜMÜZLE BİR TOPLANTIDAN YENİ ÇIKTIM. 'ÇÖPÜ BOŞALT MİGUEL,' DEDİM.",
