["bm_gloves_bananabike_desc"] = "MOTOSİKLET SÜRERKEN BUNLARI TAKIP KARŞIDAN GELEN EŞEKARILARININ ÖDÜNÜ KOPAR.",
["bm_gloves_bike_red_led_desc"] = "ELE OTURAN YAPISI, ŞIKLIĞI VE O RETRO VAPORWAVE HAVASIYLA YANLIŞ SEÇİM OLMAZ.",
["bm_gloves_bike_yellow_led_desc"] = "ELDİVENLER ARASINDA BUNLAR HEM KULLANIŞLI HEM DE MODAYI TAKİP EDEN TÜRDEN. HER DURUMA FAZLADAN BİR IŞILTI KATARLAR.",
["bm_gloves_biker_blue_desc"] = "DAHA MAVİ AMA BU ELDİVENİN SİYAH ÇEŞİDİ KADAR DAYANIKLI.",
["bm_gloves_biker_desc"] = "RUST’IN SELE ÇANTASINDA GENELLİKLE BUNLARDAN BİR ÇİFT BULUNUR. GERÇİ SÜRMEKTEN ÇOK YUMRUK ATARKEN KULLANMAYI SEVER.",
["bm_gloves_biker_orange_desc"] = "KALİFORNİYA GÜN BATIMLARI İÇİN.",
["bm_gloves_biker_red_desc"] = "EKİM AYINDAKİ MOTOSİKLET GEZİLERİ İÇİN.",
["bm_gloves_blackstar_desc"] = "SEN GELDİĞİNDE CEHENNEM DE PEK GERİDE DEĞİLDİR.",
["bm_gloves_bonemittens_desc"] = "İÇİNDEKİNİ DIŞINA YANSIT.",
["bm_gloves_chopper_desc"] = "GÖSTERİŞTEN KAÇINAN SOYGUNCULAR BU SADE ELDİVEN ÇİFTİNİ TAM KENDİLERİNE GÖRE BULABİLİR.",
["bm_gloves_chromecross_desc"] = "AÇIK DENİZDE DE AÇIK YOLDA DA SENİN HAYATIN KORSAN HAYATI.",
["bm_gloves_continental_desc"] = "SOYGUNCULAR MUHATAP OLDUKLARI KİŞİLERCE SÜREKLİ YARGILANIR. BİR TOPLANTIYA YANLIŞ KRAVATLA GİT, ÇIKARKEN HAKKINDA ÖLÜM EMRİ VERİLMİŞ OLABİLİR. PATRONUN KIZININ DÜĞÜNÜNE HAZIR TAKIM ELBİSEYLE GİT, BİR SONRAKİ BÜYÜK İŞE ÇAĞRILMAYABİLİRSİN. AMA BÖYLE ELDİVENLER İYİ YA DA KÖTÜ OLMAYAN, SADECE SON DERECE HUZURSUZ EDİCİ VE DİKKAT DAĞITICI BİR İZLENİM BIRAKIR. JIMMY BU YÜZDEN ONLARA BAYILIYOR; ONUN UĞURLU DAMALARI.",
["bm_gloves_cosmos_desc"] = "SOYGUNCU DEDİĞİN NEDİR Kİ? YILDIZ TOZU. SONSUZ EVREN NELER BARINDIRIYOR ACABA? KİM BİLİR UZAYLI GEZEGENLERİNDE, DOĞRU SOYGUNCUNUN GELİP KENDİLERİNİ SOYMASINI BEKLEYEN KAÇ BANKA VARDIR.",
["bm_gloves_darkmat_desc"] = "KOZMİK BİR GÜÇSÜN; GÖRÜNMEZ AMA İNKÂR EDİLEMEZ. SENİ HİÇ KİMSE GÖRMEDİ AMA ÇEKİM GÜCÜNÜN ETKİLERİNE HER GÜN TANIK OLUYORLAR. HER YERDESİN VE HİÇBİR YERDESİN.",
["bm_gloves_default"] = "VARSAYILAN",
["bm_gloves_default_desc"] = "SOYGUNCUNUN VARSAYILAN ELDİVENLERİNİ KULLAN",
["bm_gloves_desperadoleather_desc"] = "HIZLA ÇEKER, HEP HEDEFİ BULUR.",
["bm_gloves_devilclaws_desc"] = "HADİ EL SIKIŞALIM.",
["bm_gloves_dodskull_desc"] = "NE DİYEYİM, KENDİ CENAZEN.",
["bm_gloves_dragonscale_desc"] = "ATEŞLİ PULLARLA KAPLI, SİVRİ DİKENLERLE DOLU BU ELDİVENLERİ NEFRET ETTİĞİN BİRİYLE TOKALAŞACAĞIN ZAMAN TAK.",
["bm_gloves_driverleather_desc"] = "TWITCH’İN GÖZDESİ.",
["bm_gloves_esport_desc"] = "OYNAMAYA HEP HAZIR.",
["bm_gloves_fancycloth_desc"] = "SYDNEY’NİN BİR ZAMANLAR BÖYLE BİR ÇİFTİ VARDI AMA BİR SOYGUNDA HEPSİNİ KANA BULADI.",
["bm_gloves_goldnet_desc"] = "GÜÇLÜ AMERİKAN ARABALARININ SOKAKLARA HÜKMETTİĞİ, FAVORİLERİN UZUNLUĞUNUN SINIRI OLMADIĞI GÜNLERDEN BİR KAÇIŞ ŞOFÖRÜ OLMAK MI İSTİYORSUN? ÖZLEDİĞİN DÖNEM BUYSA BU ELDİVENLER SANA İYİ GELİR, SENİ DOĞRU HAVAYA SOKAR.",
["bm_gloves_hardwork_desc"] = "ELLERİNİ KİRLETMEKTEN KORKMA.",
["bm_gloves_heatleather_desc"] = "BU İŞİ SENDEN İYİ BİLEN YOK.",
["bm_gloves_heistwrinkled_desc"] = "ÇALMAK İÇİN ŞIK GİYİN.",
["bm_gloves_heistwrinkled_purple_desc"] = "GECE VAKTİ, SOYGUN VAKTİ.",
["bm_gloves_heistwrinkled_white_desc"] = "NE GİRERKEN GÖRDÜLER SENİ NE DE ÇIKARKEN.",
["bm_gloves_hockey_desc"] = "BİR SOYGUNCU PARMAKLARINI BUZDAN KORUMALI; HEM DONMUŞ SU OLANDAN HEM DE KARBON TÜRÜNDEN.",
["bm_gloves_jesterstripe_desc"] = "BU SAĞLAM DERİ ELDİVENLERİN DİKİŞLERİ SAF ALTINDAN. DÜNYANIN EN İYİ DOKUMACILARI SEKİZ AYRI İPLİĞİ ÖREREK YAPTI. BİR SOYGUNCUNUN ELLERİ DAHA AZINI HAK ETMEZ; HELE İŞTE GEÇEN SEKİZ ŞANLI YIL KUTLANIYORSA.",
["bm_gloves_kidswool_desc"] = "JOY’UN SOĞUK KIŞ GECELERİNDE HACKLEME YAPARKEN EN SEVDİĞİ ELDİVENLER.",
["bm_gloves_leatherspark_desc"] = "HİÇ ELMAS ELDİVENLERLE ELMAS ÇALDIN MI? İŞTE LÜKS BUDUR!",
["bm_gloves_mnk_desc"] = "BİTKİSEL TABAKLANMIŞ DERİDEN, DOLGULU VE HAVA ALAN, RAHAT VE KULLANIŞLI ELDİVENLER.",
["bm_gloves_mnt_desc"] = "BİTKİSEL TABAKLANMIŞ DERİDEN, DOLGULU VE HAVA ALAN, RAHAT VE KULLANIŞLI ELDİVENLER.",
["bm_gloves_molten_desc"] = "VOLKANLAR GENELLİKLE KÖTÜ HABERDİR. SOYULMAK ÜZERE OLAN YERDE ÇALIŞIYORSAN BUNLARI TAKMIŞ BİR SOYGUNCU ÇOK DAHA KÖTÜ HABERDİR.",
["bm_gloves_murky_desc"] = "İŞİ YAP, VURGUNU KAP.",
["bm_gloves_neoncity_desc"] = "90’LAR ARAYIP ELDİVENLERİ GERİ İSTEDİ AMA PAYDAY GANG \"SİKTİR ET\" DEYİP ELİNDE TUTTU.",
["bm_gloves_overkillpunk_desc"] = "BU TASARIM, BİR DOZ FAZLA ZEKÂ İLACI ALMIŞ, KAFASI BOZUK BİR SİLİKON VADİSİ DÂHİSİNİN ESERİ. ONUN YANMIŞ BEYNİNDEN KAZANÇLI ÇIKAN SENSİN.",
["bm_gloves_postmoto_desc"] = "İNCE, KLASİK SİYAH DERİ ELDİVENLER. HAFİF VE ESNEK OLDUKLARINDAN, GANİMETİNLE ARANA GİREN KİMSEYE KURŞUNU SIKMAN GEREKTİĞİNDE TETİĞE UZANMAYI ÇOK KOLAYLAŞTIRIRLAR.",
["bm_gloves_punkleather_desc"] = "KORKAKÇA BOYUN EĞENLERDEN DEĞİLSİN.",
["bm_gloves_railwork_desc"] = "SENİN SAYENDE PARA TRENİ HER ZAMAN VAKTİNDE ÇALIŞIR.",
["bm_gloves_rainbowmittens_desc"] = "BUNU PARA İÇİN YAPMIYORSUN.",
["bm_gloves_ranchdiesel_desc"] = "ÇİFTLİK HAYATININ SINAV VE SIKINTILARIYLA BAŞ ETMEK İÇİN SAĞLAM EL GEREKİR. ÖZELLİKLE ÇİFTLİĞİN BÜYÜK BİR SİLAH KAÇAKÇILIĞI OPERASYONUNUN PARAVANIYSA.",
["bm_gloves_redhand_desc"] = "SENİ YAKALADILAR AMA YAKALAMAMIŞ OLMAYI DİLEYECEKLER.",
["bm_gloves_saintsleather_desc"] = "ACI VERME ZAMANI.",
["bm_gloves_silver_desc"] = "GÖSTERİŞ VE İHTİŞAM, SPORTİF BİR KESİMLE BİRLEŞTİ. YETER Kİ ÜZERİNE KASA YAĞI BULAŞTIRMA.",
["bm_gloves_sneak_desc"] = "GİZLENEREK ZENGİNLEŞ.",
["bm_gloves_spikeknuckle_desc"] = "DENGESİZ, GERGİN VE HER YANI SİVRİ. EVET, BU ELDİVEN TAM SANA GÖRE.",
["bm_gloves_sportsbike_desc"] = "KIR YOLUNDA HIZ YAPMAK, BANKADA VEZNE CAMINI KIRARKEN BOĞUMLARINI KORUMAK İÇİN.",
["bm_gloves_tactical_desc"] = "BUNLAR WASHINGTON DC POLİSLERİNİN SAHİP OLDUĞU HER ŞEYDEN DAHA KALİTELİ.",
["bm_gloves_tasslefringe_desc"] = "BU MALZEMEDEN KANI YIKAYIP ÇIKARMAK ÇOK KOLAY!",
["bm_gloves_techhigh_bird_desc"] = "ÇİN UZAY PROGRAMI İÇİN GELİŞTİRİLİP SİVİL KULLANIMA UYARLANMIŞ KORUYUCU PLAKALARLA YAPILAN BU ELDİVENLER, ÜSTÜN HAREKET KABİLİYETİ VE RAHATLIK SUNAR.",
["bm_gloves_techhigh_dragon_desc"] = "ÇİN UZAY PROGRAMI İÇİN GELİŞTİRİLİP SİVİL KULLANIMA UYARLANMIŞ KORUYUCU PLAKALARLA YAPILAN BU ELDİVENLER, ÜSTÜN HAREKET KABİLİYETİ VE RAHATLIK SUNAR.",
["bm_gloves_techhigh_tiger_desc"] = "ÇİN UZAY PROGRAMI İÇİN GELİŞTİRİLİP SİVİL KULLANIMA UYARLANMIŞ KORUYUCU PLAKALARLA YAPILAN BU ELDİVENLER, ÜSTÜN HAREKET KABİLİYETİ VE RAHATLIK SUNAR.",
["bm_gloves_techhigh_tortoise_desc"] = "ÇİN UZAY PROGRAMI İÇİN GELİŞTİRİLİP SİVİL KULLANIMA UYARLANMIŞ KORUYUCU PLAKALARLA YAPILAN BU ELDİVENLER, ÜSTÜN HAREKET KABİLİYETİ VE RAHATLIK SUNAR.",
["bm_gloves_techlow_bird_desc"] = "MODERN SENTETİK KUMAŞLARDAN YAPILMIŞ, HAVA GEÇİRGENLİĞİ VE NEM UZAKLAŞTIRMA ÖZELLİĞİ YÜKSEK, İNCE DOLGULU VE KULLANIŞLI BİR MOTOSİKLET ELDİVENİ.",
["bm_gloves_techlow_dragon_desc"] = "MODERN SENTETİK KUMAŞLARDAN YAPILMIŞ, HAVA GEÇİRGENLİĞİ VE NEM UZAKLAŞTIRMA ÖZELLİĞİ YÜKSEK, İNCE DOLGULU VE KULLANIŞLI BİR MOTOSİKLET ELDİVENİ.",
["bm_gloves_techlow_tiger_desc"] = "MODERN SENTETİK KUMAŞLARDAN YAPILMIŞ, HAVA GEÇİRGENLİĞİ VE NEM UZAKLAŞTIRMA ÖZELLİĞİ YÜKSEK, İNCE DOLGULU VE KULLANIŞLI BİR MOTOSİKLET ELDİVENİ.",
["bm_gloves_techlow_tortoise_desc"] = "MODERN SENTETİK KUMAŞLARDAN YAPILMIŞ, HAVA GEÇİRGENLİĞİ VE NEM UZAKLAŞTIRMA ÖZELLİĞİ YÜKSEK, İNCE DOLGULU VE KULLANIŞLI BİR MOTOSİKLET ELDİVENİ.",
["bm_gloves_texriding_desc"] = "BU İŞİ KOLAYMIŞ GİBİ GÖSTERİYORSUN.",
["bm_gloves_tgr_desc"] = "BİTKİSEL TABAKLANMIŞ DERİDEN, DOLGULU VE HAVA ALAN, RAHAT VE KULLANIŞLI ELDİVENLER.",
["bm_gloves_tiger_desc"] = "BU ŞIK EL ISITICILARIYLA DÜNYANIN DÖRT BİR YANINDAKİ BÜYÜK KEDİLERİN YAŞADIĞI ZORLUKLARA KARŞI DAYANIŞMANI GÖSTER.",
["bm_gloves_tornrags_desc"] = "İŞTE RUH BUDUR!",
["bm_gloves_tstp_blackdragon_desc"] = "HER PARMAK DELİĞİNDEN BELALILIK SIZAN DAHA HAVALI ELDİVENLER HAYAL EDEBİLİYORSAN HAYAL GÜCÜN EPEY İYİ DEMEKTİR. EN YENİ TEKNOLOJİLİ KUMAŞLARDAN YAPILAN BU ELDİVENLER PARMAKLARINI HEM SICAKTAN HEM SOĞUKTAN KORUR, ÖZELLİKLE STRESLİ SOYGUNLARDA ELLERİNDE OLUŞAN O NEMİ UZAKLAŞTIRIR.",
["bm_gloves_tstp_flame_desc"] = "MERAK ETMEDEN OLMUYOR... 50’LERDE BU MODERN TEKNOLOJİLİ KUMAŞ ELDİVENLER OLSAYDI BUGÜNÜN HOTROD KÜLTÜRÜ NASIL GÖRÜNÜRDÜ?",
["bm_gloves_tstp_reddragon_desc"] = "BUNLARI TAKIP PARMAKLARININ BÜTÜN O BAŞ BELASI POLİSLERE ATEŞ PÜSKÜRTTÜĞÜNÜ HAYAL ET.",
["bm_gloves_tstp_redstripe_desc"] = "BİR ŞEYİN ÜZERİNDEKİ KIRMIZI ÇİZGİLERİN ONU HIZLANDIRDIĞINA DAİR YAYGIN BİR İNANIŞ VAR. 1980’LERİN ARABA KOVALAMACA FİLMLERİNDE İŞE YARAMIŞ OLABİLİR AMA SOYGUNU HIZLANDIRMASI PEK OLASI DEĞİL. YİNE DE HOŞ GÖRÜNÜYORLAR, SENCE DE ÖYLE DEĞİL Mİ?",
["bm_gloves_vpr_desc"] = "BİTKİSEL TABAKLANMIŞ DERİDEN, DOLGULU VE HAVA ALAN, RAHAT VE KULLANIŞLI ELDİVENLER.",
["bm_gloves_wool_desc"] = "HAVA KARANLIK, SOĞUKTAN DONUYORSUN. ŞEHRİN LÜKS SEMTİNDEKİ ZENGİN BİR PİSLİĞİN MALİKANESİNİ SOYMAYA HAZIRLANIYORSUN. BU ŞIK ELDİVENLER OLMASA SİLAHININ SOĞUK ÇELİĞİ ELLERİNİ BİR DAKİKADA UYUŞTURURDU. ZÜPPELERİ SOYARKEN ELLERİN BİLE ORTAMA UYGUN GÖRÜNMELİ!",
["bm_gloves_workranch_desc"] = "HAYATIN DİZGİNLERİNİ ELİNE AL.",
["bm_grenade_copr_ability"] = "SÜLÜK AMPULÜ",
["bm_grenade_copr_ability_desc"] = "SÜLÜK YETENEĞİNİ ETKİNLEŞTİRMEK İÇİN BURNUNUN ALTINDA KÜÇÜK BİR CAM AMPUL KIRIP DERİN BİR NEFES ALMALISIN. İÇİNDE NE OLDUĞUNU TAM BİLMİYORSUN AMA DÜNYAYI DAHA NET GÖRMENİ SAĞLIYOR, ADRENALİNİNİ DE TAVANA VURDURUYOR. KESİN OLAN BİR ŞEY VAR: BU MERET AYILTMA TUZU DEĞİL.",
["bm_grenade_dada_com_desc"] = "MATRUŞKA EL BOMBASI, FIRLATILABİLİR BİR PATLAYICIDIR. BEBEĞİN DIŞ KATMANLARI İÇ MEKANİZMAYI GİZLER. ANA VATANA SAYGI SUNARKEN CİDDİ HASAR VERİR.",
["bm_grenade_damage_control"] = "STOACININ CEP MATARASI",
["bm_grenade_damage_control_desc"] = "DUKE’A GENÇLİĞİNDE BUDİST KEŞİŞLERLE EĞİTİM GÖRÜRKEN VERİLMİŞ, ÜZERİNDE \"STOİC\" VE \"JW SPİRİTS\" YAZAN 1882 TARİHLİ ANTİKA BİR MATARA. DUKE ONU EN SEVDİĞİ VİSKİYLE DOLU TUTUYOR. BİR YUDUM ALMAK, SAKİNLEŞMEYİ SİMGELEYEN BİR HAREKET; TAŞIYANA ZEN BENZERİ BİR ODAKLANMA ANI SAĞLAYIP HASARI HAFİFLETİYOR.",
["bm_grenade_electric_desc"] = "ŞARAPNEL İYİDİR HOŞTUR AMA BAZI ŞEYLERİ KIZARTMAK GEREKİR. BU KÜÇÜK GÜZELLİK, YÜKSEK VOLTAJLA HASAR VERMEK İÇİN PEK KULLANIŞLI BİR CANAVAR.",
["bm_grenade_fir_com"] = "YANGIN EL BOMBASI",
["bm_grenade_fir_com_desc"] = "YANGIN EL BOMBASI, KENDİLİĞİNDEN TUTUŞAN TEHLİKELİ BİR FOSFOR KABIDIR. BİRKAÇ SANİYE SONRA TUTUŞUR; BU DA ONU DUVARLARDAN SEKTİRİP DÜŞMANLARA GÖNDERMEK İÇİN İDEAL KILAR. TUTUŞTUĞUNDA DÜŞMANLARI ALEVLER İÇİNDE BIRAKARAK CİDDİ HASAR VERİR.",
["bm_grenade_frag"] = "PARÇA TESİRLİ EL BOMBASI",
["bm_grenade_frag_com"] = "HEF EL BOMBASI",
["bm_grenade_frag_com_desc"] = "BU, KLASİK EL BOMBASININ YENİLENMİŞ SÜRÜMÜ. ORİJİNAL PARÇA TESİRLİ EL BOMBASI HÂLÂ KULLANILSA DA BU YENİ, ZARİF TASARIM HER PATLAMAYA OVERKILL DOKUNUŞU KATACAK. HÂLÂ AYNI DERECEDE UCUZ, HÂLÂ AYNI DERECEDE ETKİLİ.",
["bm_grenade_frag_desc"] = "PARÇA TESİRLİ EL BOMBASI İLK ORTAYA ÇIKTIĞINDAN BERİ PEK AZ DEĞİŞMİŞ BİR KAVRAMDIR. FIRLATILAN GÖVDE PATLAYIP PARÇALARINI ÖYLE BİR KUVVETLE SAÇAR Kİ ETİ, KEMİĞİ VE HAFİF ZIRHI KESİP GEÇEBİLİRLER. UCUZ VE ETKİLİ.",
["bm_grenade_molotov"] = "MOLOTOFKOKTEYLİ",
["bm_grenade_molotov_desc"] = "MOLOTOFKOKTEYLİ, EL BOMBASI DENEBİLECEK BELKİ DE EN BASİT SİLAHTIR. \"FİTİLİ\" YANAN BİR BEZLE DEĞİŞTİRİLMİŞ, YANICI SIVI DOLU KIRILABİLİR BİR ŞİŞEDEN İBARETTİR. UCUZ, BASİT VE ÇOK ETKİLİDİR.",
["bm_grenade_pocket_ecm_jammer"] = "CEP ECM CİHAZI",
["bm_grenade_pocket_ecm_jammer_desc"] = "YAKINDAKİ ŞİFRELİ SİNYALLERİ YAKALAYIP DENETİMİNİ ELE GEÇİREN KÜÇÜK BİR CİHAZ. KABLOSUZ VERİLERİ BULUP BOZAN GELİŞMİŞ ALGORİTMALARI SAYESİNDE CEP ECM CİHAZI, HEM GÖLGELERDE GİZLENİRKEN HEM DE ÇATIŞMANIN ORTASINDA KULLANICIYA ÜSTÜNLÜK SAĞLAR.",
["bm_grenade_poison_gas_grenade_desc"] = "HEM ÖLÜMCÜL HEM KÜÇÜK BİR KİMYASAL SİLAH MI ARIYORSUN? DAHA FAZLA ARAMA! BU SON DERECE YASADIŞI EL BOMBASININ PATLAMA YARIÇAPI SINIRLI OLSA DA SALDIĞI GENİŞ ZEHİRLİ GAZ BULUTU, ENGEREĞİN GÜCÜNÜ AVUCUNA VERİR. DÜŞMANLARIN SOLUNUM SİSTEMLERİNE VEDA EDEBİLİR.",
["bm_grenade_smoke_screen_grenade"] = "SİS BOMBASI",
["bm_grenade_smoke_screen_grenade_desc"] = "BUNLARDAN BİRİNİ BIRAK, BİR DUMAN BULUTUNUN İÇİNDE KAYBOL. DÜŞMANLARIN SANA NİŞAN ALMAK İÇİN DEBELENİP DURSUN. SENİ DOĞRU DÜRÜST GÖREMEDİKLERİNDE MERMİLERDEN SIYRILMAK ÇOCUK OYUNCAĞI.",
["bm_grenade_sticky_grenade"] = "YAPIŞKAN EL BOMBASI",
["bm_grenade_sticky_grenade_desc"] = "DÜŞMANLARA VE YÜZEYLERE YAPIŞAN, FIRLATILABİLİR BİR PATLAYICI.",
["bm_grenade_tag_team"] = "GAZ DAĞITICI",
["bm_grenade_tag_team_desc"] = "VÜCUDUN DUYULARINI GEÇİCİ OLARAK GÜÇLENDİREN, İKİ MÜTTEFİKE İYİLEŞTİRME ETKİSİ SAĞLAYAN KÜÇÜK BİR GAZ DAĞITICI.",
["bm_grenade_xmas_snowball"] = "KARTOPU",
["bm_grenade_xmas_snowball_desc"] = "SUYA BATIR, DONDURUCUYA AT; İŞTE ÖLÜMCÜL BİR FIRLATMA SİLAHIN VAR. BASİT.",
["bm_hoxton_rising_desc"] = "HAYALET HİKÂYELERİ İŞTE BÖYLE ÇARPIK BİR YÜZDEN DOĞAR. PARÇALANMIŞ VE KASVETLİ, GÖLGELERDE BEKLERSİN. SONRA ÇIKIP YOLUNA GELENİN ÖDÜNÜ KOPARIRSIN. GERÇEK KORKU, BU DEHŞETE BAKINCA ÖĞRENİLİR. BU CANAVARI BESLEYEN O KORKUDUR; LEZİZ, SAF, DİRİ KORKU. DAHA FAZLASI İÇİN BİTMEYEN BİR SUSUZLUK DOĞURUR. BAKMA AMA GÖZLERİNİ KAPATMA.",
["bm_jar_head_desc"] = "BU, CHAINS’İN SİLAHLI BİR DARBEDEN SONRA ORTA AMERİKA’DA VIP KORUMALIĞI YAPARAK GEÇİRDİĞİ İKİ UZUN, SIKICI AYIN ANISINA SAKLADIĞI ESKİ BİR HATIRA. ONA PARALI ASKERLİĞİ BIRAKTIRAN ASKERÎ TEKDÜZELİĞİ HATIRLATIYOR.",
["bm_loadout_shotgun"] = "POMPALI TÜFEK",
["bm_loadout_sniper"] = "KESKİN NİŞANCI",
["bm_lucky_luciano_desc"] = "\"MODERN SUÇUN BABASI\" SAYILIR. NEDEN LUCKY LAKABINI ALDIĞI TAM BELLİ DEĞİL AMA 25 KEZ TUTUKLANIP HAPİSTE BİR GÜN BİLE GEÇİRMEMEYİ BAŞARDI. BAŞKA BİR MAFYAYA KATILMAYI REDDETTİĞİ İÇİN BOĞAZI KESİLDİĞİNDE DE HAYATTA KALDI. HER HÂLÜKÂRDA GERÇEK BİR İLHAM KAYNAĞI.",
["bm_madame_st_claire_desc"] = "BU GERÇEKTEN ÇETİN CEVİZ. ST. CLAİR’İN SUÇLU YANI, KARANLIK BİR GECEDE CEHENNEMİ YAŞARKEN DOĞDU. SONRA YASADIŞI DÜNYANIN DERİNLERİNE DALDI. AMA SİVİL HAKLAR VE POLİS YOLSUZLUĞU KONUSUNDA DA SESİNİ DUYURUYORDU. BİR BAKIMA ROBİN HOOD’UN MODERN, ÇARPIK BİR SÜRÜMÜ DENEBİLİR.",
