["bm_mclr_upsdell_red"] = "UPSDELL KIRMIZISI",
["bm_mclr_vivid_blue"] = "CANLI MAVİ",
["bm_mclr_vivid_orchid"] = "CANLI ORKİDE",
["bm_mclr_vivid_raspberry"] = "CANLI AHUDUDU",
["bm_mclr_vivid_sky_blue"] = "CANLI GÖKYÜZÜ MAVİSİ",
["bm_mclr_warm_yellow"] = "SICAK SARI",
["bm_mclr_white"] = "BEYAZ",
["bm_mclr_yellow"] = "SARI",
["bm_mega_clover_desc"] = "MEGA CLOVER MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_melee_aziz_desc"] = "DÜŞMANIN GELDİĞİNİ GÖRMEZKEN KAFASINA VURMAYI SPORTMENLİĞE AYKIRI BULUYORSAN, İNDİRMEDEN ÖNCE BU EL FENERİNİ RAHATSIZ EDİCİ BİÇİMDE DOĞRUDAN GÖZÜNE TUTMAYA NE DERSİN?",
["bm_melee_baseballbat_desc"] = "SAYI TURU VURUŞLARI YAPABİLECEĞİN BİR BEYZBOL SOPASI.",
["bm_melee_bat"] = "BEYZBOL SOPASI",
["bm_melee_baton_desc"] = "HER SOYGUNCUNUN VE KOLLUK GÖREVLİSİNİN KALABALIĞI DENETLEMEK, İTAAT ETMEYENLERİ DAĞITMAK İÇİN EN SEVDİĞİ SİLAH. TELESKOPİK COPUN SABİT COPA GÖRE PEK ÇOK AVANTAJI VAR. HAFİF VE ETKİLİ, DAHA ÇOK YÖNLÜ; OLASI SALDIRGANLARA DA DAHA KORKUTUCU GÖRÜNÜYOR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_becker_desc"] = "PALA, TROPİKAL ÜLKELERDE YAĞMUR ORMANI ÇALILIKLARINI VE İSYANLARI KESİP BİÇMEK İÇİN, BİR DE TARIMDA SIKÇA KULLANILAN BÜYÜK, SATIRA BENZER BİR BIÇAKTIR. İNSANLARIN PALALARI HİNDİSTANCEVİZİ VEYA KAFATASI AÇMAK, BAHÇE İŞİ YAPMAK VE BANKA SOYMAK GİBİ BAŞKA İŞLERDE KULLANDIĞINI GÖRMEK DE OLAĞANDIR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_brass_knuckles_desc"] = "MUŞTA TÜRÜ SİLAHLAR YÜZLERCE YILDIR DÜNYANIN HER YERİNDE KULLANILIYOR. MUŞTALAR, YUMRUĞUN KUVVETİNİ DAHA SERT VE KÜÇÜK BİR ALANA YÖNLENDİREREK YOĞUNLAŞTIRIR; DOKU HASARI OLASILIĞINI ARTIRIR. YETERİNCE SERT VURURSAN KEMİK DE KIRARSIN.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_chac_desc"] = "RİTMİ HİSSET.",
["bm_melee_cqc_desc"] = "BAŞLANGIÇTA TARIM ALETİ OLAN KUNAİ, DOĞUNUN GÖLGE SUİKASTÇILARININ ELİNDE SAVAŞA GİRDİ. HER AN HAZIR OLMASI İÇİN ELDE, AĞIZDA, KEMERDE VEYA PARMAĞA TAKILI TAŞINABİLİR.",
["bm_melee_cqc_info"] = "ZAMANLA HASAR VEREN VE DÜŞMANLARIN EYLEMİNİ KESİNTİYE UĞRATMA ŞANSI OLAN ZEHİRLİ UÇLU BIÇAK.",
["bm_melee_croupier_rake_desc"] = "TEK AMACI PARAYI KENDİNE ÇEKMEK OLAN BİR EŞYA MI? TAM SİZ SOYGUNCULARA GÖRE! ŞU BAŞ BELASI POLİSLERE KASANIN NEDEN HEP KAZANDIĞINI GÖSTER.",
["bm_melee_detector_desc"] = "BİR DAHA ANAHTARLARINI KAYBETMEYECEKSİN!",
["bm_melee_fear_desc"] = "ENDİŞELENME; İĞNELERDEN HOŞLANMADIĞINI SÖYLEDİĞİNDE SENİNLE İLGİLENEN GÖREVLİLER KIZMAYACAK VEYA KORKAK OLDUĞUNU DÜŞÜNMEYECEK.",
["bm_melee_fear_info"] = "ZAMANLA HASAR VEREN VE DÜŞMANLARIN EYLEMİNİ KESİNTİYE UĞRATMA ŞANSI OLAN ZEHİR DOLU ŞIRINGA.",
["bm_melee_fight_desc"] = "UZAK DENİZAŞIRI TOPRAKLARDA BULUNAN GİZLİ DÖVÜŞ TARZI",
["bm_melee_fists"] = "YUMRUKLAR",
["bm_melee_fists_desc"] = "BOKSÖR DEĞİLSİN AMA YİNE DE İYİ YUMRUK ATABİLİRSİN. BİRAZ GÜÇ, HIZ VE ZAMANLAMA YETER; HEMEN ETKİLİ BİR DARBE İNDİRİRSİN.$NL;$NL;DAHA FAZLA HASAR VERMEK İÇİN YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK YUMRUĞUNU HAZIRLAYABİLİRSİN.",
["bm_melee_gerber_desc"] = "BERGER COMBAT KNIFE, KATLANIR KLİPS UÇLU NAMLUSU OLAN POPÜLER BİR TAKTİK BIÇAKTIR. KÜÇÜK, HAFİF YAPISI VE YÜKSEK TEKNOLOJİLİ MALZEMELERİ ONU HIZLI VE TEHLİKELİ BİR ALET YAPAR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_hauteur_desc"] = "JAPON TANTO BIÇAKLARI, YANİ KISA KILIÇLARI, HANÇERE BENZEYEN TASARIMLARIYLA TANINIR.",
["bm_melee_hockey_desc"] = "BUZ ÜZERİNDE DİSKLE KULLANILMAK ÜZERE TASARLANMIŞ SAĞLAM BİR HOKEY SOPASI. AMA BUZ DIŞINDA DA ETKİLİ OLDUĞU KANITLANDI.",
["bm_melee_kabar_desc"] = "URSA KNIFE, GEÇMİŞİ 1942’YE DAYANAN, DAYANIKLI VE YIKILMAZ BİR DÖVÜŞ VE İŞ BIÇAĞIDIR. BOWİE NAMLU, TIRTIKLI KENAR, LAF KALABALIĞI YOK. BİR KLASİK.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_kampfmesser_desc"] = "KRIEGER BLADE, ALMAN ORDUSU’NUN STANDART BIÇAĞIDIR. SAĞLAM KAVRAYIŞI VE TANTO NAMLUSU ONU ÇATIŞMA İÇİN MÜKEMMEL BİR SEÇİM YAPAR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_meter_desc"] = "İKİ ELLE KULLANILAN BÜYÜK CETVELİMİZ, ÜRETTİĞİMİZ EN BÜYÜK CETVEL. AMA BOYUTUNA ALDANMA; BU HARİKA CETVELİN HANTAL VEYA KULLANIŞSIZ BİR YANI YOK.",
["bm_melee_microphone_desc"] = "MİKROFON MU DEDİN?",
["bm_melee_micstand_desc"] = "SAHNE KORKUSUNU SAHNE HÂKİMİYETİNE DÖNÜŞTÜR!",
["bm_melee_moneybundle_desc"] = "PARAYI BİR ŞERİTLE DEMETLEMEK, PARANIN KENDİSİ KADAR ESKİDİR. ZENGİNLER VE PEZEVENKLER DE ÇOK UZUN ZAMANDIR İNSANLARI PARAYLA DÖVÜYOR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_oldbaton_desc"] = "KLASİKLERİN ÜSTÜNE YOK!",
["bm_melee_ostry_desc"] = "YEL DEĞİRMENİ OLARAK DA BİLİNEN KAZAGURUMA, ETİ TEREYAĞI GİBİ KESEN HIZLI VE ÖLÜMCÜL BİR YAKIN DÖVÜŞ SİLAHIDIR.",
["bm_melee_rambo_desc"] = "TRAUTMAN KNIFE, AĞIR BİR BOWİE NAMLUSU OLAN HAYATTA KALMA BIÇAĞIDIR. UZUNLUĞU, TIRTIKLI SIRTI VE ORTALANMIŞ UCU DOĞADA DA YAKIN DÖVÜŞTE OLDUĞU KADAR İYİ İŞ GÖRÜR.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_shock_desc"] = "PATRON CUMARTESİ ÇALIŞMAMIZ GEREKECEĞİNİ SÖYLEYEREK PLANLARIMIZA ÇOMAK SOKTU.",
["bm_melee_shovel_desc"] = "K.L.A.S. KÜREK, ORDULAR TARAFINDAN PEK ÇOK AMAÇLA KULLANILIR. HAYATTA KALMA MERAKLILARININ, SERBEST DALIŞÇILARIN, KAMPÇILARIN, DOĞA YÜRÜYÜŞÇÜLERİNİN, BAHÇIVANLARIN VE SAVAŞ CANLANDIRMASI GRUPLARININ ELİNDE DE GÖRÜLEBİLİR. SİLAH OLARAK DA KULLANILABİLİR; KENARLARINI BİLE, ETİ DE KEMİĞİ DE KESİP GEÇERSİN. TABİİ DOĞRU KULLANIRSAN. SEN ÖYLE KULLANMIYORSUN.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_slot_lever_desc"] = "BİR HAFTA SÜREN, FAZLA İLERİ GİTMİŞ BİR VEGAS ÂLEMİNİN HÜZÜNLÜ (VE KOMİK) KALINTISI. KÖTÜ ŞANSIN VE KÖTÜ HAYAT KARARLARININ GÜCÜYLE POLİSLERİ PATAKLA.",
["bm_melee_switchblade_desc"] = "ELLİLERDE İKİ NEW YORK GENÇLİK ÇETESİNİN HESABINI GÖRMESİ İÇİN SIKÇA KULLANILIRDI. ŞARKIYA DA EŞLİK EDEBİLİRSİN.",
["bm_melee_sword_desc"] = "KESKİN, İSABETLİ VE GİZLENEBİLİRLİĞİ YÜKSEK PEN, HER ŞEYİN TÜKENDİĞİNDE VE BİR AORTU DELMEK İSTEDİĞİNDE EN İYİ DOSTUNDUR.",
["bm_melee_taser_desc"] = "İŞTE BEKLEDİĞİN BU. ŞU KENDİNİ BEĞENMİŞ TASER’LARDAN TATLI, ELEKTRİKLİ İNTİKAMINI AL. AL SANA YILDIRIM!",
["bm_melee_taser_info"] = "TEMASTA HEDEFLERE ELEKTRİK VERİP ONLARI DURDURAN AYGIT",
["bm_melee_tiger_desc"] = "BİRDEN ÇOK BIÇAĞIN OLABİLECEKKEN NEDEN TEK BİR TANEYLE YETİNESİN?",
["bm_melee_tomahawk_desc"] = "TARİH BOYUNCA ÇOK AMAÇLI BİR ALET OLARAK, İNSANLARA FIRLATMAK İÇİN VE ARA SIRA GÖĞÜS GÖĞÜSE ÇARPIŞMADA KULLANILDI. NEREDEYSE HER HAYDUDUN AZ ÇOK USTALAŞABİLECEĞİ BİR SİLAH. TOMAHAWK’IN HEM ALET HEM DE SİLAH OLARAK GERÇEK POTANSİYELİ ANCAK HAKKIYLA SOYGUN YAPARAK KEŞFEDİLEBİLİR. AMA DAHA ÇOK SİLAH OLARAK.$NL;$NL;YAKIN DÖVÜŞ DÜĞMESİNİ BASILI TUTARAK BU SİLAHIN DARBESİNİ GÜÇLENDİREBİLİR VE DAHA FAZLA HASAR VEREBİLİRSİN.",
["bm_melee_twins_desc"] = "OKİNAWALI KOLLUK GÖREVLİLERİNİN KULLANDIĞI SAİ HEM SALDIRI HEM SAVUNMA SİLAHIDIR. SOYGUNDA KARŞINA ÇIKANLARA HIZLI DARBELER İNDİRMEK İÇİN DE KUSURSUZ BİR ARAÇTIR.",
["bm_melee_weapon_desc"] = "SİLAHLI SOYGUNLARDA KURBANLARI SİLAHLA DÖVMEK, ONLARI VURMAKTAN VEYA BIÇAKLAMAKTAN GENELLİKLE DAHA YAYGINDIR. ÇOĞUNLUKLA TÜFEKLE DİPÇİK VURUR VEYA TABANCAYLA KABZA DARBESİ İNDİRİRSİN.$NL;$NL;BU EN HIZLI YAKIN DÖVÜŞ SALDIRISIDIR.",
["bm_melee_zeus_info"] = "TEMASTA HEDEFLERE ELEKTRİK VERİP ONLARI DURDURAN AYGIT",
