["bm_mod_equip_remove"] = "BU MODİFİKASYONU KUŞANMAK, KUŞANDIĞIN $mod; MODİFİKASYONUNU ÇIKARACAK!",
["bm_mod_incompatibilities"] = "BU MODİFİKASYON $quantifier; $category; İLE UYUMSUZ!",
["bm_mod_incompatibility_all"] = "TÜMÜ",
["bm_mod_incompatibility_most"] = "ÇOĞU",
["bm_mod_incompatibility_some"] = "BAZILARI",
["bm_mr_pickle_desc"] = "İNCE, SERT, YEŞİL BİR ÖLÜM MAKİNESİ. BAŞIN DERDE GİRİP BİR AN ÖNCE SIVIŞMAN GEREKTİĞİNDE TAKILACAK KUSURSUZ MASKE. SU GİBİ OL DOSTUM.",
["bm_msg_alex_desc"] = "KIZ VE ERKEK KARDEŞTEN OLUŞAN İKİLİNİN BİR YARISI ALEX. KUĞULAR GİBİ AMANSIZLAR. KUĞULARIN AKSİNE TESTERE VE HAFİF MAKİNELİ SİLAH KUŞANIYORLAR. KUĞULAR GİBİ BİRBİRLERİNE SIKI SIKIYA BAĞLILAR. KUĞULARIN AKSİNE KATLİAMA DÜŞKÜNLER.",
["bm_msk_achievement_milestone_postfix_WIN32"] = "$NL;$NL;BU MASKE BİR BAŞARIM DÖNÜM NOKTASI ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_achievement_postfix_WIN32"] = "$NL;$NL;BU MASKE BİR BAŞARIM ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_agatha_knight_desc"] = "TENOSİA’NIN KURAK ÇORAK TOPRAKLARINDAN ÇIKARILAN BU AGATHİAN KNİGHT MİĞFERİ, ONU KILIÇLARDAN VE OKLARDAN KORUYABİLİRDİ. AMA KİNG ALPHONSO KADAR HAYALPEREST BİR LİDERİN KANLI HIRSLARINDAN KORUYAMADI.",
["bm_msk_agatha_vanguard_veteran_desc"] = "YURDUNU VE KRALININ DÜZENİNİ HADDİNİ BİLMEZ MASONS’DAN GERİ ALMAYA ÇALIŞIRKEN GÜCE, DESTEĞE VE KORKUTUCU BİR ÇEHREYE İHTİYACIN OLUR. BU VANGUARD MİĞFERİ ÜÇÜNÜ DE SAĞLAR.",
["bm_msk_alex_desc"] = "KIZ VE ERKEK KARDEŞTEN OLUŞAN İKİLİNİN BİR YARISI ALEX. KUĞULAR GİBİ AMANSIZLAR. KUĞULARIN AKSİNE TESTERE VE HAFİF MAKİNELİ SİLAH KUŞANIYORLAR. KUĞULAR GİBİ BİRBİRLERİNE SIKI SIKIYA BAĞLILAR. KUĞULARIN AKSİNE KATLİAMA DÜŞKÜNLER.",
["bm_msk_alien_helmet_desc"] = "GRAY ALİENS, VARLIKLARI UFO, PARANORMAL OLAYLAR VE NEW AGE TOPLULUKLARINDA SAVUNULAN, TEN RENKLERİNDEN ADINI ALAN SÖZDE DÜNYA DIŞI VARLIKLARDIR.$NL;$NL;YOKSA GERÇEKTEN VARLAR MI?",
["bm_msk_alienware_desc"] = "DÜNYA DIŞI BİR VARLIK GÖRDÜĞÜNÜ SANAN BİR DELİNİN HAYALLERİNDEN ESİNLENDİ.$NL;$NL;AMA TUHAF; ÇÜNKÜ SAĞLAM MALZEMELERİ DÜNYA’NIN HİÇBİR YERİNDEN GELMİYOR.",
["bm_msk_almirs_beard_achievement"] = "AÇMAK İÇİN KAR FIRTINASININ BİNİCİLERİ BAŞARIMINI TAMAMLA!",
["bm_msk_almirs_beard_desc"] = "BAZILARI GERÇEK ERKEKLER TIRAŞ OLMAZ DER AMA DOĞRUSU GERÇEK ERKEKLER TIRAŞ OLAMAZ. SIRADAN JİLETLER, GÜR BİR ALMIR SAKALININ SIK, GÖRKEMLİ BİTKİ ÖRTÜSÜNDEN SEKİP GİDER.",
["bm_msk_ami_01_desc"] = "RADYOAKTİF SPREY BOYA ÇEKMİŞ GİBİ, GÜÇ SEVİYESİ BİR KADEME DAHA YÜKSELDİ; ARTIK PATLAMAK ÜZERE. SOYGUNA ÇIKTIĞINDA SEN GEÇERKEN ÇEVRENDEKİ HERKES SİPER ARAYACAK. ŞEHİRDEKİ BÜTÜN GEİGER SAYAÇLARI ÇILDIRMAK ÜZERE.",
["bm_msk_ami_02_desc"] = "İSTEDİĞİN O SOMUN EKMEĞİ DÜŞÜN. ŞİMDİ O AÇLIĞI BİN KATINA ÇIKAR. BU SADECE YEMEK EKSİKLİĞİ DEĞİL; RUHUNUN KENDİSİ DE KARNIN KADAR BOŞ KALANA DEK BESİNDEN YOKSUN. AÇLIK ÖLÜMÜN ÖTESİNDE SÜRSEYDİ BÖYLE BİR ÇEHREYE BÜRÜNÜRDÜ. AMA BÖYLE BİR ÇİLE, SOYGUN İÇİN GÜÇLÜ BİR İTİCİ GÜÇ OLABİLİR.",
["bm_msk_ami_03_desc"] = "ESKİ KRALLARIN BÖYLE BİR ESERİ OLSAYDI YENİLMEZ OLURLARDI. HANGİ DÜŞMAN İHTİŞAMINA BAKARKEN ÖNÜNDE EĞİLMEMEYE DAYANABİLİR? SUN TZU GİDİP LİMON EMSİN; BÖYLE BİR MASKEYLE SAVAŞTA SANATA KİMİN İHTİYACI VAR?",
["bm_msk_ami_04_desc"] = "BİR HAMLE, SONRA BİR HAMLE DAHA. RAKİBİN HAMLE YAPAR, SEN KARŞILIK VERİRSİN. ALTIN DAĞININ TEPESİNDE DURUYOR, GELİP MEYDAN OKUMASINI KABUL ETMEN İÇİN SANA KAFA TUTUYOR. BU MASKEYİ TAKARAK BOYUN EĞMEDİĞİNİ İLAN EDERSİN; OYUN SÜRER, REKABET BİTMEZ.",
["bm_msk_ami_05_desc"] = "İŞKENCECİ Mİ, İŞKENCE GÖREN Mİ? BELKİ İKİSİ DE. GÖZLERİNDEKİ KAYNAYAN PARILTI, KANUNUN RUHUNA DEHŞET ÜRPERTİLERİ SALIYOR. SENİ YAKALAMA GİRİŞİMLERİNİN HER BİRİNİ BOŞA ÇIKARIRKEN DAMARLARINDA KÖTÜCÜL BİR NEŞE AKIYOR. MAVİ ÜNİFORMALILARDAN USTALIKLA SIYRILIRKEN AĞITLARINI DİNLE.",
["bm_msk_ami_06_desc"] = "KALBİNE YANIP İŞLER, KAFATASINDAN ETİ SÖKER; TURUNCU ALEVLER, DAHA FAZLASINA DUYULAN DİNMEZ İHTİYACIN RENGİYLE TEZAT OLUŞTURUR. TATMİN OLANA KADAR KASAYA KAÇ KEZ DAHA DÖNECEKSİN? KAÇ SİLAH SENİ MUTLU EDER? HEPSİ! BELKİ.",
["bm_msk_amp_01_desc"] = "GELMİŞ GEÇMİŞ EN VAHŞİ VE ACIMASIZ KORSANLARDAN BİRİ. AYNI ZAMANDA EN AZ BİLİNENLERDEN. TAM DA SCHNEİDER’İN İSTEDİĞİ GİBİ. ONUN YERİNE SCHNEİDER’İN \"THE DEVİL\" LAKABI ÇOK DAHA YAYGINDI. KİMSENİN GERÇEK YÜZÜNÜ BİLMEMESİNİ DAHA KÂRLI BULUYORDU. AMA \"ŞEYTANIN\" YEDİ DENİZDE NASIL YELKEN AÇTIĞINA DAİR HİKÂYELER KARAYİP BARLARINDA DOLAŞIYORDU. BİRİ DENİZDE KAYBOLUNCA \"UFUKTA THE DEVİL’I GÖRMEK\" SIKÇA SÖYLENİRDİ. GERÇEKSE SCHNEİDER’İN ONLARI SONSUZA DEK SULU BİR MEZARA GÖMMESİYDİ.",
["bm_msk_amp_02_desc"] = "HER GEMİ HAYALET HİKÂYELERİ GETİRİR. GECE GEÇ VAKİTTE YORGUN GÖZCÜLERİN GÖRDÜĞÜ HUZURSUZ RUHLAR; KRAKEN’LERDEN DENİZKIZLARINA KADAR HER ŞEY. AMA KEELHAULED ALEX’İN HİKÂYESİ BELKİ DE EN KORKULANLARDAN BİRİDİR. ALEX, DENİZDEKİ UZUN BİR YOLCULUKTA YİYECEK ÇALIYORDU. YAKALANINCA GEMİNİN OMURGASININ ALTINDAN SÜRÜKLENMEYE MAHKÛM EDİLDİ. SUÇU AĞIR DEĞİLDİ AMA CEZASI AĞIRDI. ALEX GEMİNİN ALTINDAYKEN BAŞKA BİR GEMİ ATEŞ AÇTI VE ALEX AŞAĞIDA TERK EDİLİP UNUTULDU. ORTALIK YATIŞINCA CESEDİ DERİNLİKLERE ATILDI. AMA O ZAMANDAN BERİ KEELHAULED ALEX GECELERİ GEMİLERDE DOLAŞIR, KAPTANDAN SIRADAN TAYFAYA KADAR HERKESE GÖZLERİNİ DİKER. RUHUNUN İÇİNE BAKIP ONU YUTABİLDİĞİ SÖYLENİR.",
["bm_msk_amp_03_desc"] = "NİLAM, KORSANLARIN VE DENİZ YAĞMACILARININ ARASINDA BÜYÜDÜ. KONUŞMADAN ROMU TANIDI, YÜRÜMEDEN KILIÇ TUTTU. NİLAM’IN AİLESİ YOKTU; ONUN YERİNE KORSANLARIN GÖÇEBE YAŞAMINI KADERİ OLARAK BENİMSEDİ. KILICI ÇEVİKTİ, DÖVÜŞTE PEK AZ KİŞİ ONA DENK GELİRDİ. TEK İSTEDİĞİ, DİĞERLERİNİN GÖRDÜĞÜ SAYGIYDI AMA BU DÜNYA ERKEKLERİN ELİNDEYDİ. SONUNDA NİLAM’IN SABRI TAŞTI. ONA HAKSIZLIK EDENLER BOĞAZLARI KESİLEREK \"HÜKÜM GİYDİ\". ŞÖHRETİ KENDİSİNDEN ÖNCE GİDİYORDU; VERDİCT ADLI GEMİSİ LİMANA GİRERKEN, LİMANLAR YANINDA GETİRDİĞİ KIYIMDAN KORKARDI.",
["bm_msk_amp_04_desc"] = "JESSİCAH’NIN İKİ GÖZÜ OLSAYDI ASLA ÜNLÜ OLMAZDI. BİR GEMİ KAZASINDAN SONRA KÜÇÜK BİR ADACIĞA YÜZMEYİ BAŞARDI. ETRAFINDA BİR KÖPEKBALIĞI DOLAŞIYOR, GÖRÜNÜRDE YARDIM DA YOKTU; KAPANA KISILMIŞTI. ELİNDE SADECE KIRIK BİR BIÇAK VARDI. KIYIYA GÜVENLE YÜZEBİLMEK İÇİN TEK SEÇENEĞİ KÖPEKBALIĞINI ÖLDÜRMEKTİ. AMA ONU GAFİL AVLAMAK İÇİN BİR YEME İHTİYACI VARDI. PARMAĞINI KAYBETMEK YÜZMEYİ ZORLAŞTIRIRDI; O DA GÖZLERİNDEN BİRİNİ OYUP KANLI PARÇAYI SUYA ATTI. SONRA DALDI.",
["bm_msk_ancient_desc"] = "BAZILARININ EVRENDEKİ EN GELİŞMİŞ VARLIKLAR OLARAK TANIMLADIĞI GÜÇLÜ BİR UZAYLI IRKI. CROSSBREED İLE TEMAS KURAN FARKLI IRKLAR ONLARA FARKLI ADLAR VERİR.$NL;$NL;GÜÇLÜ, İNCE YAPILI VE ZEKİ CROSSBREED, KARŞILAŞTIĞI HER UZAYLI IRKININ DNA’SINDAKİ EN İYİ ÖZELLİKLERİ ALIR VE HEP DOĞRU YÖNDE EVRİLDİĞİNDEN EMİN OLUR.",
["bm_msk_ancient_desc_WIN32"] = "BAZILARININ EVRENDEKİ EN GELİŞMİŞ VARLIKLAR OLARAK TANIMLADIĞI GÜÇLÜ BİR UZAYLI IRKI. CROSSBREED İLE TEMAS KURAN FARKLI IRKLAR ONLARA FARKLI ADLAR VERİR.$NL;$NL;GÜÇLÜ, İNCE YAPILI VE ZEKİ CROSSBREED, KARŞILAŞTIĞI HER UZAYLI IRKININ DNA’SINDAKİ EN İYİ ÖZELLİKLERİ ALIR VE HEP DOĞRU YÖNDE EVRİLDİĞİNDEN EMİN OLUR.$NL;$NL;BU MASKE BİR HUMBLE BUNDLE E3 MASKESİDİR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_andromeda_desc"] = "GELECEK GELDİ. BU ÖZEL AĞIZLIĞIN GELECEĞİN ASKERLERİ İÇİN GELİŞTİRİLDİĞİ DÜŞÜNÜLÜYOR. YALNIZCA GAZ MASKESİ OLMAKLA KALMIYOR, TAKAN KİŞİYE SU ALTINDA NEFES ALMA YETENEĞİ DE VERİYOR. NE YAZIK Kİ BU BOZUK GİBİ AMA HÂLÂ HAVALI GÖRÜNÜYOR.",
["bm_msk_anonymous_desc"] = "MASKEYİ TAK, ANONİM OL VE DİLEDİĞİNİ YAP.$NL;$NL;İNANDIĞIN İÇİN YAP, SANA SÖYLENDİĞİ İÇİN YAP YA DA SIRF EĞLENCESİNE YAP.$NL;$NL;NORMAL TOPLUMUN İZİN VERMEDİĞİ HER ŞEYİ YAP. BANKA SOYMAK GİBİ.",
["bm_msk_ant_01_desc"] = "INTERCEPTOR BX-99 MODELİ, \"DÜZENİ SAĞLAMAK\" İÇİN ÜRETİLDİ. YORUMA ÇOK AÇIK BİR GÖREV. SOKAKLARDA DOLAŞIR, SİVİLLERİN GÜVENDE, HER ŞEYİN \"YOLUNDA\" OLDUĞUNDAN EMİN OLURDU. BİR MONTAJ FABRİKASININ YAKININDA OLAY ÇIKINCA BU INTERCEPTOR İŞİ FAZLA İLERİ GÖTÜRDÜ. BAZI SİVİLLER YARALANDI, BAZILARI YOK EDİLDİ, HAVA MERMİLERLE DOLDU. INTERCEPTOR, MONTAJ FABRİKASININ İŞLEYİŞİNİ AKSATMAMAK İÇİN MUTLAK GEREKLİ GÖRDÜĞÜ ŞEYİ YAPTI. 151010130807 SERİ NUMARALI INTERCEPTOR BX-99 DAHA SONRA SÖKÜLDÜ.",
["bm_msk_ant_02_desc"] = "ROBOT SAVAŞLARIYLA DALGA GEÇMEK KOLAY. ÖLÜ ŞEYLERLE SAVAŞAN BAŞKA ÖLÜ ŞEYLER. AMA YAPAY ZEKÂ GELİŞTİKÇE İŞLER CİDDİLEŞTİ. VİZOR GİBİ ASKERLER, ÇOKTAN ÖLMÜŞ İNSANLARIN DÜZENLEDİĞİ KARGAŞADA KİLİT ROL OYNADI. DÜĞMEYE BASAN AMA SONUÇLARINI YAŞAMAYAN İNSANLAR. ROBOTLAR ROBOTLARA KARŞI DÖNERKEN VİZOR GİBİ ASKERLER YÜKSELDİ; KALBİ ATANLAR İSE ANIYA DÖNÜŞTÜ.",
["bm_msk_ant_03_desc"] = "HER SAVAŞIN HAİNİ VARDIR. MOTH DA ONLARDAN BİRİYDİ. NE PAHASINA OLURSA OLSUN BİLGİ ELDE ETMEK İÇİN YAPILMIŞ BİR NÖBETÇİ ROBOT. AMA HİYERARŞİ VE GÜÇ SIKÇA ARZULANIR. SAVAŞLAR YOZLAŞMA DOĞURUR; MOTH MANTIĞINI İZLEYİP TARAF DEĞİŞTİRDİ VE MİLYONLARCA ROBOTUN BAĞLANTISININ KESİLMESİNE NEDEN OLDU. BİR TARAFIN ALKIŞLAYIP DİĞERİNİN NEFRET ETTİĞİ MOTH, SAVAŞIN GİDİŞİNİ DEĞİŞTİREN PİYONLARDAN BİRİ OLDU.",
["bm_msk_ant_04_desc"] = "DOME, KARŞI TARAFIN PLANLAYIP BAŞLATTIĞI BÜYÜK BİR TERTİBİN MERKEZİNDEYDİ. ONARMAK, YENİDEN BİRLEŞTİRMEK VE DÜZENLEMEK İÇİN YAPILMIŞ BASİT BİR ROBOT OLAN DOME, DÜŞMANIN YIKTIĞI BİR DEVLET BİNASINI YENİDEN KURMAKLA GÖREVLİYDİ. COMMANDER WASP’IN ARABASI ENKAZIN YANINDAN GEÇERKEN YAKINLARDA ONU ÖLDÜRMEK İÇİN GİZLİ BİR SALDIRI HAZIRLANIYORDU. DOME SALDIRIYI GÖRDÜ, KENDİNİ ARABANIN ÖNÜNE ATARAK ARACIN PATLAMADAN UZAKLAŞMASINI SAĞLADI VE COMMANDER’I KORUMAK İÇİN KENDİNİ FEDA ETTİ. WASP HAYATTA KALDI, DOME KALMADI.",
["bm_msk_ant_05_desc"] = "HER SAVAŞIN CELLATLARA İHTİYACI VARDIR. SIRADAN BİR ASKER DEĞİL; TEHDİTKÂR TAVRIYLA CAN ALABİLEN BİRİ. \"SİSTEM\" İÇİN ÇALIŞAN, EMİRLERE KÖRÜ KÖRÜNE UYAN BİRİ. SKULL BUNLARDAN BİRİYDİ. BIKMADAN ROBOT ÜSTÜNE ROBOTUN, SAVAŞ SUÇLULARININ VE \"DAVA\" İÇİN \"TEHLİKELİ\" SAYILAN DİĞER HERKESİN BAĞLANTISINI KESEN BİRİ.",
["bm_msk_ant_06_desc"] = "BİR ROBOTUN OLABİLECEĞİ KADAR ÖLÜMCÜL TASARLANDI. GREAT PURGE’DEN TEK BAŞINA DRONE SORUMLUYDU. TÜM ZİHİNLERE VE TARİHÎ VERİ SUNUCULARINA SONSUZA DEK KAZINDI. DRONE, GÖZDEN ÇIKARILABİLİR BİR ERDEN BEKLENENİN ÖTESİNE GEÇECEK BECERİLERE SAHİPTİ; SONUNDA PAHA BİÇİLEMEZ OLDU. GREAT PURGE SAVAŞIN YÖNÜNÜ DEĞİŞTİRDİ: UYUYAN HÜCRELER ORTAYA ÇIKTI, ROBOTLARIN BAĞLANTISI KESİLDİ, HİVE MİND BİNLERCE ZETTABAYT KAYBETTİ. DRONE, MİNG Jİ MEMORİAL PARK’TA BAKILIP HAYRANLIK DUYULAN BİR HEYKELE DÖNÜŞTÜ. ",
["bm_msk_ant_07_desc"] = "COMMANDER WASP İNANILMAZ TEKNİK KAPASİTEYE SAHİPTİ. GÜCÜ VE ZEKÂSI KARŞI TARAFI AÇIK ARA GERİDE BIRAKIYORDU. DÜŞMAN KUVVETLERİNİ ZEKÂSIYLA ALT EDECEK DEVRELERE SAHİP BİR PROTOTİPTİ. AMA DENENMEMİŞ BİR PROTOTİP. ACELEYE GELMİŞ. FAZLA DENEYSEL. DELİLİK DEVRE KARTLARINA DA VURUR AMA BİZ ONA \"HATA\" DERİZ. BİR PARANOYA NÖBETİNDE KENDİ ASKERLERİNİ ÖLDÜREN COMMANDER WASP, SAVAŞ SUÇLUSUNA DÖNÜŞTÜ.",
["bm_msk_ant_08_desc"] = "RAPTOR BİR AVCI PİLOTUYDU. UÇURDUĞU HER UÇAĞIN MERKEZİNE BAĞLANIP KARARLILIKLA YÖN VERİRDİ. MESELE BİRİKMİŞ BİLGİYDİ. BÜTÜN PİLOTLARA AYNI YAZILIM YÜKLENSE DE YAPAY ZEKÂ ÖĞRENİR. RAPTOR DA BİR ŞEKİLDE BİLGİSİNİ KORUYACAK KADAR UZUN YAŞAMAYI BAŞARDI. DÜŞMAN BÖLGESİNE GEÇİNCE YAKALANIP HACKLENEBİLECEKLERİ İÇİN AVCI PİLOTLARINA HİVE MİND YASAKTI. AMA RAPTOR, DÜŞMAN ÜSLERİNİ TEREDDÜTSÜZ YOK ETMEKTE EN İYİ OLMAYI ÖĞRENDİ.",
["bm_msk_anubis_desc"] = "MISIR’IN ÇAKAL BAŞLI AHİRET TANRISI ANUBİS, MEZARLARI DOLDURMAKTAN ÇOK KORUMAYA ÇALIŞIRDI.",
["bm_msk_arch_nemesis_desc"] = "SÖZLÜKTE NEMESİS (BAŞ DÜŞMAN)$NL;$NL;İSİM [BAŞ DÜŞ-MAN]$NL;$NL;1. KİŞİNİN ÜSTESİNDEN GELEMEDİĞİ, BAŞARAMADIĞI ŞEY VB.: \"ÖĞLE YEMEĞİNDEKİ O ÇİN BÜFESİ BENİM BAŞ DÜŞMANIM ÇIKTI.\"$NL;2. KİŞİNİN YENEMEDİĞİ RAKİP.$NL;3. KLASİK MİTOLOJİDE, İLAHİ İNTİKAM TANRIÇASI.$NL;4. İNTİKAM VEYA CEZA GETİREN KİŞİ, ETKEN YA DA EYLEM.$NL;$NL;HOXTON’A GÖRE: \"O SİKTİĞİMİN BULLDOZER’I. BENİM BAŞ BELASI DÜŞMANIM O. İĞRENÇ HERİF!\"",
["bm_msk_area51_desc"] = "PENROSE DESENLİ, HIZLA SOĞUTULMUŞ METAL ALAŞIMLARDAN DÖVÜLEN BU MİĞFER, ÇOK GİZLİ BİR KAZA ALANINDAN ÇIKARILAN ENKAZLA YAPILDI. HÜKÜMET VARLIĞINDAN HABERDAR OLDUĞUNU İNKÂR ETMEYİ SÜRDÜRÜYOR.",
["bm_msk_aviator_desc"] = "HERKES İYİ BİR GÜNEŞ GÖZLÜĞÜNÜ SEVER.$NL;$NL;AMA YALNIZCA EN KÜSTAH, EN ÇOK ARANAN, POLİSİ TAKMAYAN BELALI HERİFLER ONU TAKIP BANKA SOYACAK KADAR ÇILGINDIR.$NL;$NL;İŞTE O SENSİN.$NL;$NL;BU MASKE, KÖTÜ ŞÖHRET AĞACI ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN. ANCAK DESEN, RENK VEYA MALZEME İLE BUNLARI BİRLEŞTİRMEK İÇİN ÖDEDİĞİN ÖZELLEŞTİRME ÜCRETİ KAYBOLUR.",
["bm_msk_baba_yaga_desc"] = "BAZEN KÖTÜCÜL, HER ZAMAN GİZEMLİ. THE BABA YAGA, SLAV MİTLERİNİN KARANLIK ORMANLARINDA DOLAŞIR. BİR HAVANDA UÇAR, HAVANELİ KULLANIR VE DEV TAVUK BACAKLARI ÜZERİNDE YÜRÜYEN BİR KULÜBEDE YAŞAR.",
["bm_msk_baby_angry_desc"] = "HIRRRRRRR HIRR HIRR HIR HIR HIRRR IIH, IIH, IIIIIIIIIIIH! HIRR! HIR.$NL;$NL;HIRRR HIR HIRRR HIRR HIRRRRRRRRRRRR, IIH, IH, IH, IH, HIRR.",
["bm_msk_baby_cry_desc"] = "IIIIH, IIIH, IH, IIIIIIIIIIIIIIIIIH, IH, IIIIIIIIH, IIIIIIH!$NL;$NL;IIIIIIIIIIIIIIIIIH, IH, IIIIIIIIH, IIIIIIH, IIIIH, IIIH, IH. IH. IIIIIIIIIIIIIIIIIIIIIIIIIIIIIH!",
["bm_msk_babyrhino_desc"] = "KİM YAVRU GERGEDAN BAŞI TAKMAK İSTEMEZ Kİ? SEVİMLİ DEĞİL Mİ? TAKINCA KENDİNİ BİRAZ APTAL HİSSEDİYORSUN, BELKİ DE GÖRÜNÜŞÜNDEN.$NL;$NL;TAKARKEN MASKEDEN GÖRMENİN BİRAZ ZOR OLDUĞUNDAN ENDİŞELENİYORSUN. DOMUZ KAFALI DOSTLARINLA UZAKLARA GİTMEDİĞİN SÜRECE SORUN OLMAZ.",
["bm_msk_baitface_desc"] = "THE FUNNYMAN İNSANLARI GÜLDÜRMEYİ BİLİR. THE FUNNYMAN BAZEN FAZLA İLERİ GİDİP BİR İKİ DARBE YİYEBİLİR. AMA DİKKAT ET; BAŞKALARININ KAHKAHASINI YÖNETEBİLEN BİRİ, SON GÜLEN OLMAYI DA BİLİR.",
["bm_msk_balaclava_desc"] = "SİLAHLAR DEĞİŞEBİLİR, İDEOLOJİLER KAYABİLİR, AKSANLAR FARKLILAŞABİLİR AMA KAR MASKESİ ON YILLARDIR SİLAHLI SOYGUNCUYLA TERÖRİSTİN VAZGEÇİLMEZİDİR. ÇAKMAKTAŞI GİBİ SERT GÖZLERİNLE ZALİM, ÇARPIK AĞZIN DIŞINDA HER YERİNİ KAPATIR; HAVA SOĞUKKEN SICAK DA TUTAR.",
["bm_msk_bandcap_dark_desc"] = "AMARİLLO’DA BİR BENZİN İSTASYONUNU SOYARKEN BU ŞAPKA, KASİYERE PARANIN MEMLEKETTE KALACAĞINI ANLATIR.",
["bm_msk_bandit_desc"] = "GENİŞ KENARLI ŞAPKA, ÇELİK BAKIŞ VE AĞZA ÇEKİLMİŞ FULAR. ÖYLE İKONİK, KLASİK VE ETKİLİ BİR BİRLEŞİM Kİ HER YERDE GANGSTERLERİN VE SOYGUNCULARIN VAZGEÇİLMEZİ OLMAYI SÜRDÜRÜYOR.",
["bm_msk_banshee_desc"] = "BAZI RUHLAR VAROLUŞUN KIYISINDA OYALANIP MOBİLYALARI HAREKET ETTİRMEKLE, GECELERİ İNLEMEKLE YETİNİR. BAZILARIYSA DAHA SOMUT BİR ETKİ İSTER. D.C. POLİSİ DAHA GEÇENLERDE ŞEHİRDEKİ BÜYÜK BANKALARDA, SANAT MÜZELERİNDE VE KUYUMCULARDA HAYALET VAKALARININ KESKİN BİÇİMDE ARTTIĞINI BİLDİRDİ. TANIKLAR DEĞERLİ EŞYALARIN KENDİ KENDİNE KAPIDAN SÜZÜLÜP ÇIKTIĞINI SÖYLÜYOR. SON BİR VURGUN İÇİN DÖNEN, ÇOKTAN ÖLMÜŞ SOYGUNCULARIN HAYALETLERİ OLMALI.",
["bm_msk_bear_desc"] = "RUSYA’DAN MERHABA.$NL;$NL;BENCE DÜNYANIN EN İYİ OYUNU OLACAK.$NL;$NL;SADECE BİR AYI.$NL;$NL;AZ ÖNCE BURADA BİR BOŞLUK VARDI.$NL;$NL;TEŞEKKÜRLER$NL;$NL;- VASİLİY",
["bm_msk_biglips_desc"] = "BU MASKEYİ TAKIP BİRİNE DUDAK GÖSTER.$NL;$NL;İNSANLARI ETKİLEYEN ŞEY, MASKENİN AĞZINI ÇEVRELEYEN İKİ ETLİ KIVRIM; GÖRDÜĞÜN EN BÜYÜK DUDAKLAR.$NL;$NL;\"AĞZINI AÇ VE AAA DE\" DİYE TALİMAT VERDİ BANKA SOYGUNCUSU.",
["bm_msk_biker_classic_desc"] = "BU ESKİ USUL MOTOSİKLET KASKI, DÜNYANIN HER YANINDAKİ MOTORCULARIN DEĞER VERDİĞİ BİR MİRASIN PARÇASI. TARZDAN ÇOK NOSTALJİYLE İLGİLİ. BU KASK SENİ MOTORCULUĞUN ALTIN ÇAĞI OLAN 1940’LARA GÖTÜRÜYOR.",
["bm_msk_biker_desc"] = "HEYECAN PEŞİNDE KOŞAN, RİSK ALAN, ANI YAŞAYAN BİR SOYGUNCUYSAN EN AZINDAN BİRAZ KORUNMAN ÖNEMLİDİR. SATIR SALLAYAN BİR MANYAKSAN DA ÖYLE.",
["bm_msk_biker_helmet_red_led_desc"] = "BU GÖZ ALICI KASK SANA AKICI, AERODİNAMİK BİR GÖRÜNÜM VERİR. TASARIMCISININ ONU YAPARKEN SON SES VAPORWAVE DİNLEDİĞİNE ŞÜPHE YOK.",
["bm_msk_biker_helmet_yellow_led_desc"] = "BU NEON TARZI BELALI KASK, DALIP HER VURUŞUNU ETKİLİ KILMAN VE MALLARLA ÇIKMAN İÇİN SANA İLHAM VERECEK.",
["bm_msk_bloodysnarl_desc"] = "VAMPİRLERDEN İYİ SOYGUNCU OLUR MU, HENÜZ BELLİ DEĞİL. HİPNOZ, YARASAYA DÖNÜŞMEK; HEPSİ BÜYÜK AVANTAJLAR. AMA DAVET EDİLMEDEN BİNAYA GİREMİYORLAR. BU DA İZİNSİZ GİRME İŞİNİ ELİYOR. BİR DE YANSIMALARI YOKSA GÜVENLİK KAMERALARINDA GÖRÜNÜRLER Mİ? VAMPİR DOSTLARIMIZA SORMAMIZ GEREKECEK.",
["bm_msk_bny_01_desc"] = "BU ÇEKİCİ PARÇA SENİ ŞEHRİN DİLİNE DÜŞÜRECEK. \"TASER’LARI GÖNDERİN!\", \"POLİS! ELLERİNİZ HAVADA DIŞARI ÇIKIN!\" VEYA \"BU ADAMLAR KİM, ESKİ ASKER Mİ?!\" GİBİ ŞEYLER DUYMAN GARANTİ.",
["bm_msk_bny_02_desc"] = "GÖRÜNÜMÜNE HAFİF BİR GİZEM KATAN BULANIK YEŞİL. FBI, KENDİ YEŞİL ÜNİFORMALI EKİPLERİNE DUYDUĞUN YAKINLIĞI TAKDİR EDECEKTİR. BU, ÜZERİNİZE AÇIKÇA ATEŞ ETMELERİNİ ENGELLEMEYECEK GERÇİ!",
["bm_msk_bny_03_desc"] = "ÇOĞU SOYGUNCU GECEYE KARIŞABİLMEK İÇİN BU SIKI, GİZLEYİCİ BAŞLIĞI SEÇER. NE YAZIK Kİ ONCA EKİPMANI TAŞIRKEN KENDİNİ GİZLEMENE PEK FAYDASI OLMAYACAK.",
["bm_msk_bny_04_desc"] = "SÖZDE \"ÜÇ MİLYON DOLARLIK ŞAPKA\" YA DÜŞMANLARININ KANINA BULANMIŞ YA DA YALNIZCA KIRMIZI YÜNDEN YAPILMIŞ. HER SOYGUNDAN SONRA YIKA YETER!",
["bm_msk_bobblehead_dozer_desc"] = "\"SENPAİ BENİ FARK ETTİ!!! :3\"$NL;$NL;NORMALDE KORKUTUCU OLAN BULLDOZER YÜZ PLAKASININ KOMİK BİR ÇEŞİDİNİ HAZIRLAYAN TOPLULUK ÜYESİ FAR2CLOSE’A ÇOK TEŞEKKÜRLER.$NL;$NL;BU MASKE YALNIZCA ÇEVRİM İÇİ OVERKILL ÜRÜN MAĞAZASINDAN SATIN ALINAN PAYDAY 2 DOZER BOBBLEHEAD İLE GELEN KODLA ALINABİLİR.",
["bm_msk_bodhi_begins_desc"] = "İKONİK BODHI MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN GÖRÜNÜŞÜNÜ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME FIRSATIN.",
["bm_msk_bodhi_desc"] = "MASKELER; TANRILARA, İLAHİ OLANA VE BENLİĞİN TANRISALLAŞMASININ PEŞİNDEKİ İNSANLARA İLİŞKİN RUHANİ GELENEKLERDE HEP KULLANILDI. BODHI’NİN MASKESİ ARKASINDAKİ ADAMI YANSITIR. GÜÇLÜ, KURNAZ, KARARLI VE KENDİNE HÂKİM.",
["bm_msk_bonnie_begins_desc"] = "İKONİK BONNIE MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN GÖRÜNÜŞÜNÜ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME FIRSATIN.",
["bm_msk_bonnie_desc"] = "İNSANLIĞA İSKOÇYA KADAR KATKI SUNMUŞ PEK AZ ULUS VAR. BİLİMDEN SANATA, MUTFAĞA HER ALANDA BU KUTSANMIŞ DİYARIN İNSANLARI ÖZGÜRCE VE CÖMERTÇE VERİR. BONNIE, BU MASKEYLE EĞİLİMİ TERSİNE ÇEVİRMEYE KARARLI.",
["bm_msk_boombox_desc"] = "BROŞÜRE GÖRE ALESSO’NUN BOOM BOX’INDA \"HAVANI SÖNDÜRECEK PİL YOK, DANGALAKLARIN RİTMİNİ DUYMASINI ÖNLEYEN SES YALITIMI VAR, POLİSLERİN YÜZÜNE VURMASINI ENGELLEYEN TAM YÜZ ZIRHI VAR.\"",
["bm_msk_borsuk_desc"] = "DÜNYA ÇAPINDA SOYGUNCU OLMAK, SİLAHI ELİNE ALMAKTAN FAZLASINI İSTER. EĞİTİM, KONDİSYON VE NORMALİN ÇOK ÖTESİNE GEÇMEYE ADANMIŞ BİR ODAK GEREKİR. BÖYLE SOYGUNCULAR NEREDEYSE MUTANTTIR; AZGIN SAVAŞIN İÇİNE DALIP HEP MUZAFFER ÇIKARLAR.",
["bm_msk_boss_desc"] = "TAKIMIN VARSA BURUN KÖPRÜNDEN SALLANACAK UYUMLU GÖZ KORUMASI DA LAZIM, DEĞİL Mİ? CLOWNS İLE SAİNTS’İN BİRLEŞEN HAVALILIĞI KOZMİK BİR ÇELİŞKİ YARATIP BÜTÜN EVRENİ İÇE ÇÖKERTEBİLİR. (YALNIZ ORTALIĞI ALDSTONE’A TEMİZLETME, TAMAM MI?)",
["bm_msk_boss_gold_desc"] = "SOM ALTINDAN MASKE TAKMAYA NE DENİR? İDDİALI BİR GÖSTERİ DENİR, İŞTE O KADAR.",
["bm_msk_boss_silver_desc"] = "AYNA GİBİ PARLAK, GÜMÜŞ GİBİ DE AĞIR OLAN BU MASKE BÜTÜN DİKKATLERİ ÜZERİNE ÇEKECEK.",
["bm_msk_brainiack_desc"] = "BU, KAFASINDA ÇOK ŞEY OLAN BİRİNİN MASKESİ.$NL;$NL;BU MASKEYİ TAKMAK, SUÇLAR VE NASIL İŞLENDİKLERİ HAKKINDA DAHA FAZLA ÖĞRENMEYE YÖNELİK AŞIRI, NEREDEYSE PATLAYICI BİR ARZU UYANDIRIR.",
["bm_msk_brutal_desc"] = "BU MİĞFER MOTOSİKLET ÇETESİNİN EN TEPESİNDEKİ ADAMA AYRILMIŞTIR. KARDEŞLERİNDEN SAYGI VE OTORİTE İSTER. SAVAŞ VAKTİ GELDİĞİNDE GURURLA TAKAR, EN ÖNDE SÜRERSİN.",
["bm_msk_buha_desc"] = "MUHTEMELEN GÖRDÜĞÜN EN ÖFKELİ PALYAÇO MASKELERİNDEN BİRİ.$NL;$NL;WOLF’UN MASKESİNİ NEREDEYSE UTANDIRIYOR.$NL;$NL;NEREDEYSE.",
["bm_msk_bullet_desc"] = "GÜÇLÜ BİR ATEŞLİ SİLAHLA YÜZÜNDEN VURULMAKTAN MI ENDİŞELİSİN?$NL;$NL;BİR BULLDOZER, CLOAKER VE SHIELD’IN AYNI ANDA SENİ EZMESİNDEN Mİ KORKUYORSUN?$NL;$NL;BU MASKEYİ TAKMAK SANA YARDIM ETMEZ AMA YERE ŞIK BİR ŞEKİLDE DÜŞERSİN. THE BULLET, ŞU ANDA YAKININIZDAKİ KARABORSALARDA!",
["bm_msk_bullskull_desc"] = "ISSIZ KANYONLARDA, DÜŞÜNCELERİNDEN BAŞKA YOLDAŞIN OLMADAN SENDELEYEREK İLERLERKEN EN SON GÖRMEK İSTEYECEĞİN ŞEY, SENDEN ÖNCE GEÇENLERİN KURUMUŞ KEMİKLERİDİR. BİR ANDA O DÜŞÜNCELER ÇIĞLIĞA DÖNÜŞÜR.",
["bm_msk_buluc_desc"] = "BAŞINA EN AKIL ALMAZ DERECEDE İĞRENÇ SURATI TAKAN KAZANIR.",
["bm_msk_bush_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETTİ.$NL;$NL;KELİMELERİN USTASI OLDUĞUNA ŞÜPHE YOK.$NL;$NL;43. BAŞKAN, TARİHİN EN SEVİLMEYEN BAŞKANLARINDAN BİRİYDİ. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_msk_butcher_desc"] = "DOĞUDAN GELEN DELİ KASAP HAKKINDA PEK ÇOK SÖYLENTİ VAR. BİRİNE GÖRE, DOMUZ KESMEKTEN O KADAR ZEVK ALAN BİR ADAMMIŞ Kİ ZAMANLA ONLARA BENZEMEYE BAŞLAMIŞ.$NL;$NL;CEHENNEM KADAR SICAK BİR KASAPHANEDE ÇALIŞIRKEN DERİSİ KABARCIKLAR VE KESİKLERLE BOZULMUŞ. İNSANLAR İÇERİDEN ÇIĞLIKLAR GELDİĞİNİ ANLATIYOR... HEM DE SADECE DOMUZ ÇIĞLIKLARI DEĞİL.",
["bm_msk_cantus_desc"] = "İSTER OTOBÜSTE OL İSTER YÖNETİM KURULU ODASINDA; ALESSO KULAKLARINI İLAHİ MELODİLERLE DOLDURURKEN DÜNYAYA UYGUN BİR YÜZ GÖSTERMEK ÖNEMLİDİR. KARŞINIZDA CANTUS: MÜZİĞİN VE ŞARKININ MELEĞİ. RUHUN KANATLANSIN!",
["bm_msk_card_jack_desc"] = "MASKEYE DÖNÜŞMÜŞ BİR KLASİK. STANDART 52 KARTLIK DESTE, GÜNÜMÜZDE EN ÇOK OYNANAN İSKAMBİL DESTESİDİR. ACEMİ DE OLSAN PROFESYONEL DE OLSAN BU YÜZÜ BÜYÜK OLASILIKLA TANIRSIN. TAM BİR POKER SURATI MASKESİ.",
["bm_msk_card_joker_desc"] = "MASKEYE DÖNÜŞMÜŞ BİR KLASİK. STANDART 52 KARTLIK DESTE, GÜNÜMÜZDE EN ÇOK OYNANAN İSKAMBİL DESTESİDİR. ACEMİ DE OLSAN PROFESYONEL DE OLSAN BU YÜZÜ BÜYÜK OLASILIKLA TANIRSIN. TAM BİR POKER SURATI MASKESİ.",
["bm_msk_card_king_desc"] = "MASKEYE DÖNÜŞMÜŞ BİR KLASİK. STANDART 52 KARTLIK DESTE, GÜNÜMÜZDE EN ÇOK OYNANAN İSKAMBİL DESTESİDİR. ACEMİ DE OLSAN PROFESYONEL DE OLSAN BU YÜZÜ BÜYÜK OLASILIKLA TANIRSIN. TAM BİR POKER SURATI MASKESİ.",
["bm_msk_card_queen_desc"] = "MASKEYE DÖNÜŞMÜŞ BİR KLASİK. STANDART 52 KARTLIK DESTE, GÜNÜMÜZDE EN ÇOK OYNANAN İSKAMBİL DESTESİDİR. ACEMİ DE OLSAN PROFESYONEL DE OLSAN BU YÜZÜ BÜYÜK OLASILIKLA TANIRSIN. TAM BİR POKER SURATI MASKESİ.",
["bm_msk_carnotaurus_desc"] = "ALFRED THE CARNOTAURUS, YAŞAYIP ORTALIKTA DOLAŞIRKEN ÇOK HIZLI BİR DİNOZORDU. KENDİNE ÖZGÜ BOYNUZLARI VE KASLI BOYNU ONU DİĞER DİNOZORLARDAN AYIRIYORDU. BÜYÜK BAŞI VE DARBE EMEN BOYNUZLARI SAYESİNDE, TARİH ÖNCESİNİN EN BÜYÜK ALETİNİN KİMDE OLDUĞUNU GÖSTERMEK İÇİN DİĞER DİNOZORLARA KAFA ATMAKTA ÖZELLİKLE USTAYDI.",
