["bm_msk_cctp_vpr_desc"] = "TEHDİT ALTINDA KALDIĞINDA SÜZÜLÜP KAÇ YA DA ÖLDÜRMEK İÇİN ISIR.",
["bm_msk_chains_clean_desc"] = "BU, İKONİK CHAINS MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_chains_desc"] = "CHAINS’İN MASKESİ.",
["bm_msk_chains_glow_desc"] = "MEGA CHAINS MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_champion_dallas_desc"] = "BU, CHAMP MASKESİ. DALLAS’IN KÖTÜ BİR GÜNÜNDEN ESİNLENDİ. NE KADAR KÖTÜ MÜ? PROFESYONEL BİR BOKSÖRÜN KARŞISINDA ON ÜÇ RAUNT YUMRUK YEDİĞİNİ DÜŞÜN. ŞİŞMİŞ KAŞ, KIRIK BURUN, PATLAMIŞ DUDAK, MORARMIŞ GÖZ, EZİKLER, BEYİN SARSINTISI, ÇIKIK ÇENE; NE ARARSAN BU MASKEDE VAR. EVET, DALLAS İÇİN GERÇEKTEN KÖTÜ BİR GÜN.",
["bm_msk_character_locked"] = "KARAKTERİN MASKESİ",
["bm_msk_character_locked_desc"] = "BU MASKE YUVASINI KUŞANDIĞINDA TERCİH ETTİĞİN KARAKTERİN MASKESİNİ TAKARSIN.",
["bm_msk_cheat_error"] = "HİLELİ MASKE!",
["bm_msk_chef_hat_desc"] = "İSTER YOL KENARINDAKİ LOKANTADA KÖFTE ÇEVİREN BİR AŞÇI OL, İSTER MASASI 1000 $ OLAN BİR MEKÂNDA ZEHİRLİ BALIK DOĞRAYAN BİR İTAMAE; BU ŞAPKA TEK BİR ŞEY SÖYLER: ŞEF SENSİN.",
["bm_msk_chico_begins_desc"] = "BU, İKONİK SCARFACE MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_chico_desc"] = "SCARFACE, ABD’YE İKİ BOŞ EL VE KÖTÜ BİR TAVIRDAN BAŞKA BİR ŞEYLE GELMEDİ. KALBİNDEKİ KARANLIĞA ANCAK SUÇ DEHASININ PARLAKLIĞI DENK DÜŞÜYORDU. MASKESİ, İZ BIRAKMAYA BAŞLARKEN ARDINDA BIRAKTIĞI KAN İZİYLE BİRLİKTE BU HİKÂYEYİ ANLATIYOR.",
["bm_msk_chrodome_desc"] = "KASKINI BU KADAR PARLAK, BU KADAR LEKESİZ TUTMANIN BİR SEBEBİ VAR. PATLATTIĞIN ARABALARDAKİ BOMBALARI BÖYLE ÇOK DAHA GÜZEL YANSITIYOR.",
["bm_msk_churchill_desc"] = "SİYASETÇİ, ÖDÜL SAHİBİ, PEK ÇOK MADALYANIN SAHİBİ VE AMERİKA BİRLEŞİK DEVLETLERİ’NİN İLK FAHRİ VATANDAŞI. BAZILARI KUSURLU BİR KARAKTERİ OLDUĞUNU SÖYLEYİP ŞÖYLE DERDİ: \"İNSANLAR BİR ADAMA AYNI ANDA BU ÖLÇÜDE HAYRANLIK VE NEFRET DUYMAMIŞTI; BÖYLESİ ZIT UÇLAR AYNI İNSANDA HİÇ BİRLEŞMEMİŞTİ.\"",
["bm_msk_clinton_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETTİ.$NL;$NL;KADINLARIN GÖZDESİ OLDUĞUNA ŞÜPHE YOK.$NL;$NL;42. BAŞKAN, TARİHİN EN BARIŞÇIL BAŞKANLARINDAN BİRİYDİ. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_msk_cloth_commander_desc"] = "COMMANDER CRIME, OVERKILL COMİCS’İN ÇİZGİ ROMANLARINDA GÖRÜNEN AMERİKALI KURGUSAL BİR SÜPER KÖTÜ VE SUÇ AĞI C.R.I.M.E.’IN YÜCE LİDERİDİR.$NL;$NL;KARAKTERİ, ARTIK DÜNYACA ÜNLÜ YAZAR, EDİTÖR, SANATÇI VE PROFESYONEL BADMİNTON OYUNCUSU MAX ELMBERG SJÖHOLM YARATTI.$NL;$NL;COMMANDER CRIME İLK KEZ THE AMAZİNG CAREER CRİMİNALS: THE PAYDAY GANG GETS A C.R.I.M.E. OFFER THEY CAN'T REFUSE! ADLI ESERDE GÖRÜNDÜ.",
["bm_msk_clown_56_desc"] = "BU MASKENİN KORKUNÇ BİR GÖRÜNÜMÜ, KEMİKLİ BİR YÜZ YAPISI VE KURUMUŞ DERİSİ VAR.$NL;$NL;İNSANA KÂBUS GÖRDÜREN TÜRDEN BİR MASKE.",
["bm_msk_clowncry_desc"] = "AĞLAYAN BİR PALYAÇODAN DAHA ACIKLI BİR ŞEY VAR MI?$NL;$NL;BELKİ DE KORKUNÇ MASKELİ BİR SUÇLUNUN BAĞIRIŞLARIYLA YERE YATAN, AĞLAYAN SİVİLLER.$NL;$NL;YA DA KASASI BOŞ BİR BANKA MÜDÜRÜ.",
["bm_msk_cmo_01_desc"] = "İYİ BİR TAKTİK OYUNU, BÜYÜK SOYGUNDAN ÖNCE HAZIRLANMANIN EN İYİ YOLUDUR. DALLAS STRATEJİK DÜŞÜNCESİNİ, ZAFER İÇİN BİRLİK VE KAYNAK YÖNETMEK GEREKEN ZOR, HESAPLI BİR OYUNLA HAREKETE GEÇİRMEYİ TERCİH EDER.",
["bm_msk_cmo_02_desc"] = "YOĞUN SUÇ FAALİYETLERİNDEN SONRA ZİHNİ ÇALIŞTIRAN MANTIK BULMACALARI ÇÖZMEK, GEVŞEMEK İÇİN HARİKA BİR YOLDUR. HOXTON, VERİLEN İPUÇLARIYLA BİR SORUNU KAVRAYIP ADIM ADIM ÇÖZEBİLDİĞİ OYUNLARI SEVER.",
["bm_msk_cmo_03_desc"] = "ŞİDDET DOLU OYUNLAR WOLF’U SOYGUN HAVASINA SOKAR. KAN, VAHŞET VE KATLİAM NE KADAR FAZLAYSA O KADAR İYİ. TEPKİNİ VE HIZINI SINAYAN OYUNLARI TERCİH EDER. NEREDEYSE SONSUZ DÜŞMAN SÜRÜSÜNE KARŞI HAYATTA KALMAK İÇİN HER SANİYENİN ÖNEMLİ OLDUĞU OYUNLARI.",
["bm_msk_cmo_04_desc"] = "OYUNCULAR ARASINDA YOĞUN DURUMLARI CANLANDIRAN DÖVÜŞ VE NİŞANCI OYUNLARI, İŞLER ARASINDA BECERİLERİNİ KESKİN TUTMAK İÇİN HARİKADIR. CHAINS, DURUMSAL FARKINDALIĞI GELİŞTİREN VE BECERİKLİ OYUNU ÇATIŞMADA ÜSTÜNLÜKLE ÖDÜLLENDİREN OYUNLARI SEVER.",
["bm_msk_cmt_01_desc"] = "BU ETKİLEYİCİ BOYNUZLARLA HER SOYGUNU SENDELEYE SENDELEYE AŞABİLEN EFSANEVİ THOMOOSE GİBİ, AVKEN AVCIYA DÖNÜŞ.",
["bm_msk_cmt_02_desc"] = "BU MASKEYİ TAK, BANKA KASALARINI ÜFLEYEREK YIK VE BÜTÜN KÜÇÜK DOMUZLARIN ÖDÜNÜ KOPAR.",
["bm_msk_cmt_03_desc"] = "ASLA BİR KEDİYLE AVININ, BİR SOYGUNCUYLA GANİMETİNİN ARASINA GİRME!",
["bm_msk_cmt_04_desc"] = "BU GÖRKEMLİ YÜZ ÖRTÜSÜNÜ TAKIP KUDRETLİ BİR KÜKREMEYLE KÜRESEL ISINMAYA KARŞI SAVAŞ.",
["bm_msk_combusto_desc"] = "BU PALYAÇO ESKİDEN BİR PİROTEKNİK USTASIYDI; KİMSENİN AŞAMADIĞI BİR ATEŞ ÜFLEME GÖSTERİSİ VARDI. PEK BİLİNMEYEN ATEŞ ÜFLEYEN PALYAÇOLAR CAMİASINDAKİ RAKİPLERİ BAŞARISINDAN HOŞNUT DEĞİLDİ... KOKTEYLİNE BİR ŞEY KATTILAR.$NL;$NL;YÜZÜNDE ÜÇÜNCÜ DERECE YANIKLAR, GÖZLERİNDE KÖTÜCÜL BİR BAKIŞLA ATEŞE ATEŞLE KARŞILIK VERİP DİĞER PALYAÇOLARI YAKTI. AMA ORADA DURMADI; İÇİNDEKİ ALEVLİ NEFRET FAZLA PARLAKTI. ŞİMDİ DÜNYAYI ATEŞE VERMEK İSTİYOR.",
["bm_msk_concert_female_desc"] = "ALESSO KONSERİNİN COŞKUSUYLA KAYNAYAN GİRDABINA İNERKEN EN İYİ YÜZÜNÜ TAKSAN İYİ OLUR. THE FEMALE CONCERT GOER İFADESİZ VE KOPUKTUR; ÇÜNKÜ MÜZİKTEN BAŞKA HİÇBİR ŞEY ÖNEMLİ DEĞİLDİR.",
["bm_msk_concert_male_desc"] = "BATİK TİŞÖRTLER 70’LERDE KALDI. ÇAKMAK KALDIRMA MODASI 80’LERDE BİTTİ. DÜDÜKLER VE IŞIKLI ÇUBUKLAR 90’LARDA GERİDE BIRAKILDI; 00’LERDEN İSE NE KADAR AZ BAHSETSEK O KADAR İYİ. GÜNÜMÜZ KONSER MÜDAVİMİ İSE MASKEYİ TERCİH EDİYOR.",
["bm_msk_conquest_desc"] = "MAHŞERİN İLK ATLISININ KİMLİĞİ VE TAM OLARAK NEYİ TEMSİL ETTİĞİ BUGÜN BİLE HARARETLE TARTIŞILIYOR. KİMİLERİ ONA FETİH DER, KİMİLERİ CHRİST’IN KENDİSİ OLDUĞUNU SÖYLER, KİMİLERİYSE ANTİCHRİST OLDUĞUNU İDDİA EDER.",
["bm_msk_corey_desc"] = "SAVANIN EN LEZZETLİ ÖĞLE YEMEĞİYSEN HAYATTA KALMAK İÇİN HIZLI, ÇEVİK VE KURNAZ OLMALISIN. COREY BUNLARIN HEPSİ. ZEBRALAR AYRICA BARIŞÇIL, UYSAL VE OTOBURDUR. COREY BUNLARIN HİÇBİRİ.",
["bm_msk_crazy_lion_desc"] = "ASLAN BAŞI ŞEKLİNDE KORKUNÇ BİR MASKE.$NL;$NL;BU MASKE HAKKINDA PEK AZ ŞEY BİLİNİYOR. ASLANLARA HASTALIKLI BİR HAYRANLIK BESLEYEN ÇILGIN BİR BALKAN BİLİM İNSANININ YAPTIĞI SÖYLENİYOR. BU MASKENİN GÜZELLİĞİNİ YALNIZCA O GÖREBİLİYORDU.$NL;$NL;MASKEYİ SANA İYİLİĞİNİ İSTEYEN BİRİ VERDİ.",
["bm_msk_croupier_hat_desc"] = "GÖZ ALICI NEON 80’LER GÖRÜNÜMÜNE HAVA KAT! BU NANE YEŞİLİ BAŞLIKLAR, YOĞUN IŞIK KAYNAKLARININ GÖZLERİ YORMASINI ÖNLEMEK İÇİN 19. YÜZYILDAN BERİ KULLANILIYOR. KOKAİN ÇEKMİŞ KUMARBAZLAR VE GONZO GAZETECİLER KRUPİYE ŞAPKASINI HERKESİN İLGİ ODAĞINA TAŞIDI. SAHİL PARTİLERİ, PLAJDA GÜZELLERİ TAVLAMAK, YAKINDAKİ GOLF KULÜBÜNÜN 18. DELİĞİNDE SÖZLEŞME İMZALAMAK VE GENEL OLARAK SEKSENLİK BİRİ GİBİ GÖRÜNMEK İÇİN DE İDEALLER.",
["bm_msk_crowgoblin_desc"] = "ÇOK UZUN SÜRE CROW GOBLIN’İN GERÇEK KİMLİĞİNİ KİMSE BİLMEDİ. YİRMİ YIL SONRA ÖĞRENDİLER AMA TATMİN OLMAYINCA O KİŞİNİN SAHTEKÂR FALAN OLDUĞUNU SÖYLEDİLER. GERÇEK CROW GOBLIN BAŞKASIYDI.$NL;$NL;GERİSİYLE SENİ SIKMAK İSTEMEM AMA MASKE HOŞ GÖRÜNÜYOR, DEĞİL Mİ? MOR BİR ŞAPKASI VAR; BELKİ DE KAPÜŞON, BİLMİYORUM. HAVALI BİR SIRITIŞI, YÜZÜ BOYUNCA DİKİLMİŞ BİRKAÇ İPİ VAR. YİNE DE MASKENİN ARKASINDA KİMİN SAKLANDIĞINI MERAK EDİYORUM.",
["bm_msk_cthulhu_desc"] = "KORKUNÇ GÖRÜNÜMLÜ BİR MASKE; DEHŞETİN TA KENDİSİ.$NL;$NL;KÖTÜCÜL YARATIKLARIN PEK ÇOK ADI OLDUĞU SÖYLENİR. BU YARATIĞIN TULU, CLULU, CLOOLOO, CTHULU, CTHULLU, C'THULHU, CİGHULU, CATHULU, C'THLU VE DAHA NİCE ADLA BİLİNMESİ BUNDAN OLSA GEREK.$NL;$NL;KISMEN İNSAN, KISMEN AHTAPOT, KISMEN EJDERHA; İNSANLIĞIN BİLDİĞİ EN BÜYÜK KÖTÜLÜKLERDEN BİRİ.",
["bm_msk_cursed_crown_desc"] = "ADI EFSANELERDE KAYBOLDU. BİR KRAL DA OLABİLİR, KUDRETLİ BİR BÜYÜCÜ DE. AMA EN BÜYÜKLERİ BİLE DİAMOND’IN KARŞISINDA YIKILIR.",
["bm_msk_daft_desc"] = "GERÇEKTEN KOPUK VE DUYGUSUZ OLANLARA ANDROİD MASKESİNİ SUNUYORUZ. HAFİF ALAŞIMLAR, KROM KAPLAMA VE ÇOK HAVALI LED IŞIKLAR BU MASKEYİ HEM BANKA İŞİNE HEM DANS PİSTİNE HAZIR KILIYOR. NE YAZIK Kİ ALTI MİLYON DİLİ AKICI KONUŞMANI SAĞLAMIYOR.",
["bm_msk_dallas_clean_desc"] = "BU, İKONİK DALLAS MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_dallas_desc"] = "HERKESİN KORKTUĞU MASKE.",
["bm_msk_dallas_glow_desc"] = "MEGA DALLAS MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_damned_desc"] = "KORİDORDA İLERLERKEN BU KORKUTUCU AMA BİRAZ DA YAVAŞ ADAMI GÖRÜYORSUN. UĞURSUZCA HAVADA SÜZÜLÜYOR. TEHDİT Mİ, YOKSA SADECE BİRAZ DOLANIYOR MU, ANLAMAK ZOR. DERKEN BİR PATLAMA SESSİZLİĞİ BOZUYOR VE SEN ARTIK YOKSUN. O YÜZDEN FLOATING GUY’LA BİR DAHAKİ KARŞILAŞMANDA HAZIRLIKLI GEL, ONU HAFİFE ALMA.",
["bm_msk_daredev_desc"] = "KUSURSUZ BİR AN. HAVADA ASILISIN; MOTOSİKLET RAMPASI ARKANDA, GRAND CANYON’IN KARŞI KIYISI HER SANİYE YAKLAŞIYOR. YERE SAĞLAM MI İNECEKSİN, YOKSA ÖLÜMÜNE Mİ DÜŞECEKSİN? BU SORU AKLINDAN BİLE GEÇMİYOR. ŞU ANDA, BELKİ HAYATINDA İLK KEZ... GERÇEKTEN YAŞIYORSUN.",
["bm_msk_dawg_desc"] = "NE MASKE. ÇOK GİZLENME. PEK SOYGUNCU.",
["bm_msk_dawn_of_the_dead_desc"] = "YAŞAYAN ÖLÜ, ÖLMÜŞ OLMASINA RAĞMEN BİR ŞEKİLDE HÂLÂ YAŞIYORMUŞ GİBİ DAVRANAN BİR VARLIKTIR.$NL;$NL;GİZEMLİ YOLLARLA YARATILMIŞTIR; ZOMBİ DE OLABİLİR, VAMPİR DE.$NL;$NL;BANKA SOYACAKSAN BUNU YAPARKEN NEDEN İNSANLARIN ÖDÜNÜ DE KOPARMAYASIN?",
["bm_msk_day_of_the_dead_desc"] = "MEKSİKA’DAKİ ÖLÜLER GÜNÜ FESTİVALİYLE BAĞLANTILI BİR İSKELET MASKESİ.$NL;$NL;KÖKENİ AZTEK TASVİRLERİNE KADAR GÖTÜRÜLSE DE KİMSE TAM EMİN DEĞİL.$NL;$NL;CALACA’YI TAKMAK, ETRAFINDAKİ ÖLÜMLERDE NEŞE BULMAKTIR. BAŞKALARININ ÖLÜMÜ SEVİNÇLİ BİR OLAY OLMALI!",
["bm_msk_dbd_00_desc"] = "KABARCIKLARLA KAPLI BU YARATIK, GERÇEK DEHŞETİN VÜCUT BULMUŞ HÂLİ. ÇOCUKLUK KORKULARININ HEPSİ AKIL ALMAZ, KORKUNÇ BİR ŞEYİN İÇİNE DÖKÜLMÜŞ. ASIL SORU, ARTIK MERMİYE İHTİYACIN OLUP OLMAYACAĞI.",
["bm_msk_dbd_01_desc"] = "AYIN PARLAK OLDUĞU KASVETLİ GECELERDE THE CLAWER’IN SUYUN DERİNLİKLERİNDEN ÇIKIŞINA TANIK OLABİLİRSİN. TAZE ET İSTER, AÇLIĞI DİNENE KADAR DURMAZ. THE CLAWER, KAMP ATEŞİNDE GENÇLERİN ANLATTIĞI ŞEHİR EFSANELERİNDEN BİRİDİR; TAM DA THE CLAWER SALDIRMADAN ÖNCE. SONRA DERİNLERE DÖNER. MİDESİ YENİDEN GURULDAYANA KADAR UYKUYA YATAR.",
["bm_msk_dbd_02_desc"] = "FEEDER ÇENESİNİ TEK BİR AMAÇ İÇİN YERİNDEN ÇIKARDI: BÜTÜN BİR İNSAN KALBİNİ YUTABİLMEK. BU YÜZDEN DİŞLERİYLE DİLİ İŞE YARAMIYOR; ÇİĞNEMEK ÖNEMLİ DEĞİL. GECE DOLAŞIRKEN ONU AYAKTA TUTACAK GÜÇLÜ KALPLERİ OLAN GENÇLER ARIYOR. O YÜZDEN GÖĞSÜ YARILMIŞ BİR CESET GÖRÜRSEN KAÇ.",
["bm_msk_dbd_03_desc"] = "KARANLIK ORMAN, YAŞIN NE OLURSA OLSUN HERKESİ KORKUTUR. İÇİNDEKİLERDEN, GÖLGELERDE PUSUDA BEKLEYENLERDEN KORKARSIN. AMA AĞAÇLARIN KENDİSİNİ PEK DÜŞÜNMEZSİN. DENDRON’I HİÇ DÜŞÜNMEZSİN. DÜŞÜNDÜĞÜNDEYSE ÇOK GEÇTİR. DENDRON ACIMADAN SALDIRIR. O YÜZDEN AĞAÇLARIN ARKASINDAKİNDEN DEĞİL, AĞAÇLARDAN KORK.",
["bm_msk_dbd_04_desc"] = "ZIRDELİ KATİLLERİN BİLE PARAYA İHTİYACI VAR. GERÇEK BU. O YÜZDEN BAZEN GENÇLERİ BİÇMEYE ARA VERİP KANLI PALAYI ASMAK ZORUNDASIN. AMA ÖLDÜRMENİN PEK ÇOK YOLU VAR, BİR HOBİ DE ÇOK ÖNEMLİ. UNUTMA, POLİSLER DE KANAR.",
["bm_msk_de_gaulle_desc"] = "CONSTABLE, 1940-1969 ARASINDAKİ DÖNEMİN BÜYÜK BÖLÜMÜNDE FRANSA’NIN BASKIN ASKERÎ VE SİYASİ LİDERİYDİ. HÜKÜMETİNİN 1940’TA ALMAN İŞGALCİLERLE YAPTIĞI ATEŞKESİ KABUL ETMEYEREK LONDRA’DA ÜS KURDU. KENDİSİNİ FRANSA’NIN VÜCUT BULMUŞ HÂLİ İLAN EDİP ÖZGÜR FRANSA HAREKETİNİ BAŞLATTI. SAVAŞ SIRASINDA ÖZELLİKLE AFRİKA’DAKİ DENİZAŞIRI SÖMÜRGELERİ BİRLEŞTİRDİ, DİRENİŞİ YURT DIŞINDAN ÖRGÜTLEDİ VE İNGİLİZLERLE AMERİKALILARDAN TAM TANINMA ALMAK İÇİN MÜCADELE ETTİ.",
["bm_msk_death_rider_desc"] = "MAHŞERİN DÖRDÜNCÜ VE SON ATLISI ÖLÜM’ÜN TA KENDİSİDİR. ÖLÜM NEREYE GİDERSE GİTSİN, HADES DE ÇENELERİNİ ARDINA KADAR AÇMIŞ, ÖLÜM’ÜN KATLETTİĞİ KURBANLARIN RUHLARINI YUTMAYA HAZIR HÂLDE PEŞİNDEN GELİRDİ.",
["bm_msk_deltaforce_desc"] = "ALAYLA ALPHA FORCE DİYE ANILAN 4TH DOMESTİC OPERATİON GROUP-FORCE ENFORCERS-ALPHA (4TH DOGE-A), ABD ORDUSU’NUN JOİNT COMMON OPERATİONS COMMAND BÜNYESİNDEKİ BİR BİRLİĞİDİR. İTİBARLARI PEK İYİ DEĞİL; GİDEREK DAHA AZ SAYGI DUYULAN BİR KUVVETE DÖNÜŞTÜLER.$NL;$NL;MUHTEMELEN ÜYELERİNDEN BİRİ SENDEN KAÇARKEN BU MİĞFERİ DÜŞÜRDÜ.",
["bm_msk_demon_desc"] = "UÇURUMDAN GELEN BİR YARATIK.$NL;$NL;ASLAN GÖVDELİ, AYI AYAKLI VE LEOPAR AĞIZLI.$NL;$NL;BU YARATIK VEYA MASKEYİ KİMİN TASARLADIĞI HAKKINDA BAŞKA PEK BİR ŞEY BİLİNMİYOR.",
["bm_msk_demonictender_desc"] = "İBLİS BAŞI ŞEKLİNDE KORKUNÇ BİR MASKE.$NL;$NL;ADI DIŞINDA HAKKINDA PEK BİR ŞEY BİLİNMİYOR: KENNETH.$NL;$NL;ŞİMDİ BU İNTİKAMCI RUH, İNSANLIĞA BİR KEZ DAHA MUSALLAT OLMAK İÇİN DÜNYAYA DÖNDÜ.",
["bm_msk_destroyer_desc"] = "SAVAŞÇI RUHU KENDİLİĞİNDEN ORTAYA ÇIKMAZ. DOĞUŞTAN GELEN BİR ŞEY DEĞİLDİR. ÇELİK GİBİ ATEŞTE DÖVÜLÜR. SAVAŞIN OCAĞINDA ÇEKİÇLENİR; SU VERİLİR, PARLATILIR, BİLENİR. BU MASKE, SAVAŞÇI RUHUN DOĞUŞUNU KUTLAR: OCAKTA DOĞAN ÇELİĞİN KANATLANIŞINI.",
["bm_msk_devilhorn_desc"] = "ALDATICI PEK ÇOK AD TAŞIDI, PEK ÇOK ŞEKLE GİRDİ. ZAMANIN BAŞINDAN BERİ GÖLGELERDEN FISILDAYIP RUHLARIMIZI YOZLAŞTIRDI, BİZİ ANLATILAMAZ EYLEMLERE SÜRÜKLEDİ. PARMAĞINI KIPIRDATMADAN YIKIM GETİREBİLİR... AMA BU BİRAZ UZAKTAN İŞ YAPMAK OLUYOR, DEĞİL Mİ? BAZEN İHTİYAR SATAN, DÜNYA’DA KOCAMAN BİR İBLİS OLARAK BELİRİP KOŞTURMAK VE BİR ŞEYLER ÇALMAK İSTER. ÇOK MU ŞEY İSTİYOR?",
["bm_msk_devourer_desc"] = "DENİZLERİN ALTINDA HÜKÜM SÜREN GREAT OLD ONES’DAN BÜYÜK ÖLÇÜDE ESİNLENİLMİŞ BU MASKE, ELİ KANLI BİR TARİKATA YAPILAN BASKINDA BULUNDUKTAN SONRA TUTULDUĞU POLİS DEPOSUNDAN ÇIKARILDI. O CANAVARCA GÖRÜNTÜSÜ, KARANLIKTA HANGİ VARLIKLARIN PUSUYA YATTIĞINI DÜŞÜNDÜRÜYOR.",
["bm_msk_dgm_desc"] = "PAYDAY’İN TEK BİR GÜNDE EN ÇOK OYNANAN İŞBİRLİĞİ OYUNU OLDUĞU 10 HAZİRAN 2017’Yİ ANMAK İÇİN. SAATTE YAKLAŞIK 221 BİN SOYGUNCU BİRLİKTE, ŞIK BİR ŞEKİLDE BANKA SOYUYORDU. BÖYLECE TÜM ZAMANLARIN BİR GÜNDE EN ÇOK OYNANAN OYUNLARI ARASINDA İLK 5’E GİRDİK. PAYDAY TARİHE ALTIN HARFLERLE ADINI YAZDIRIYOR. DALLAS MEMNUN.",
["bm_msk_dillinger_death_mask_desc"] = "JOHN HERBERT DİLLİNGER ÜNLÜ BİR AMERİKALI BANKA SOYGUNCUSUYDU.$NL;$NL;ÇETESİ İKİ DÜZİNE BANKA, HATTA DÖRT POLİS KARAKOLU SOYDU.$NL;$NL;DİLLİNGER İKİ KEZ HAPİSTEN KAÇTI VE BÜYÜK BUHRAN DÖNEMİ ABD’SİNİN EN BELALI HERİFLERİNDEN BİRİ OLARAK TANINDI.",
["bm_msk_divided_desc"] = "THE TRICKSTER DEMON, KAOS YARATIP ORTALIĞI KARIŞTIRARAK BESLENEN MUZİP BİR VARLIKTIR. PEK KORKUTUCU GÖRÜNMEYEBİLİR AMA O SIRITIŞA ALDANMA; ONUN \"EĞLENCE\" ANLAYIŞI SENİNKİYLE BENİMKİNDEN ÇOK FARKLI. BU KONUDA BANA GÜVEN.",
["bm_msk_dnm_desc"] = "İNSAN KAFATASI TUHAF BİR ŞEY. HEM SADE HEM GÜZEL. İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA İNSAN BEYNİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR.$NL;$NL;BÜTÜN SOYGUNLARI NORMAL ZORLUKTA BİTİRDİN Mİ? SEN NESİN, GANGSTER FALAN MI? BELKİ DE BU MASKE SANA YAKIŞIR.",
["bm_msk_doctor_desc"] = "GENELLİKLE HASTANE VE AMBULANSLARLA İLİŞKİLENDİRİLEN, AĞIZLA BURNU KAPATAN BİR MASKE. HAPŞIRMA VEYA ÖKSÜRMEYLE SAÇILAN BAKTERİ DOLU TÜKÜRÜK VE MUKUSU TUTARAK TAKAN KİŞİNİN HAVADAN BULAŞAN VİRÜSLERİ YAYMASINI ÖNLER. HEM DOKTORLAR HEM DE HASTALAR TAKAR; O YÜZDEN KENDİNE SORMALISIN: HASTA OLAN BEN MİYİM, SAĞLIKLI OLAN MI? HASTALIK MIYIM, ÇARE Mİ?$NL;$NL;HER DURUMDA ATEŞ MEVSİMİ GELDİ VE TEK REÇETE ÖLÜ BULLDOZER’LAR.",
["bm_msk_dodhat_desc"] = "HAYATIN, \"EFSANE\" DENEN DUVAR HALISINA TİTİZLİKLE DOKUNMUŞ KARMAŞIK HİKÂYELERDEN VE ANLATI İPLERİNDEN OLUŞUYOR. SEN GİTTİKTEN ÇOK SONRA TAKLİTÇİLERİN AĞA YAKALANMIŞ SİNEKLER GİBİ MİRASINA TAKILACAK. GÖLGENDEN KAÇMAYA ÇALIŞACAKLAR VE GÖLGEN HEPSİNİ YUTACAK.",
["bm_msk_dragan_begins_desc"] = "BU, DRAGAN’IN İKONİK MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_dragan_desc"] = "DRAGAN’INKİ GİBİ BİR GEÇMİŞE SAHİP BİRİNİN SUÇ DÜNYASINDA BÜYÜKLÜK PEŞİNDE OLMASI ŞAŞIRTICI DEĞİL.$NL;$NL;MASKESİ ONUN PEK ÇOK ÖZELLİĞİNİ YANSITIYOR. İLK EKİBİN BAZI MASKELERİNE AÇIKÇA BENZEYEN YANLARI, SIZIP UYUM SAĞLAYABİLME BECERİSİNİ ANLATIYOR. DİĞER AYRINTILARSA DİNMEYEN ACIMASIZLIĞINI GÖSTERİYOR.$NL;$NL;ALNINDAKİ HIRVAT DAMALARI HEM KENDİSİNE HEM DE DÜŞMANLARINA ONUN SIRADAN BİR BATILI SOKAK SERSERİSİ OLMADIĞINI HATIRLATIYOR.",
["bm_msk_dripper_desc"] = "THE DRIPPER, BÜYÜK BİR SIVI KÜTLESİNİN ZERRECİKLERE AYRILMASIYLA YAPILMIŞ. PÜRÜZSÜZ YÜZEYİ KORUNURKEN BİR ŞEKİLDE SERT BİR MALZEMEYE DÖNÜŞMÜŞ.$NL;$NL;ONA BAKAN HERKES BAŞKA ŞEYLER GÖRÜYOR.$NL;$NL;SEN NE GÖRÜYORSUN?",
["bm_msk_eagle_desc"] = "CHUCK THE EAGLE DOĞRU, İYİ VE DÜRÜST OLAN HER ŞEYİ TEMSİL EDER.$NL;$NL;ÜNLÜ BİR DÖVÜŞ SANATLARI USTASI, ALASKA DAĞLARINDA KARATE YAPARKEN BU DEV KARTALI BULDU.$NL;$NL;SAATLERCE DÖVÜŞTÜLER AMA SONUNDA DÖVÜŞ SANATLARI USTASI KAZANDI. BAŞINI ALIP MASKE YAPTI VE ONA KENDİ ADINI VERDİ.",
["bm_msk_ecp_female_begins_desc"] = "BU, İKONİK HİLA MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_ecp_female_desc"] = "BU MASKE SANKİ MUZİP BİR KÖTÜLÜK YAYIYOR. ONA BAKAN ÇOĞU KİŞİNİN İÇİNE ANINDA BİR HUZURSUZLUK ÇÖKÜYOR; BANKA SOYARKEN DE TAM BÖYLE BİR ŞEYE İHTİYACIN VAR!",
["bm_msk_ecp_male_begins_desc"] = "BU, ETHAN’IN MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_ecp_male_desc"] = "BU MASKE, ONU TAKAN ADAMIN TAM TERSİNE GÜÇ VE KABA KUVVET SAÇIYOR. PALYAÇOYA ÖZGÜ HÜZÜN İLE GÖNÜLSÜZ ÖFKEYİ EŞİT ÖLÇÜDE TAŞIYARAK, BİRAZ İSTEMEYE İSTEMEYE SOYGUNCULUĞU SEÇMİŞ BİRİNİN RUH HÂLİNİ KUSURSUZCA YANSITIYOR.",
["bm_msk_eggian_desc"] = "XENOGOGS’DA BU YARATIKLAR, O SAHNEDE TROY TEMPLETON’IN KIÇINI PARÇALAYARAK ÇIKTIKLARINDA KORKUNUN TA KENDİSİYDİ.",
["bm_msk_eighthgrin_desc"] = "YIL DÖNÜMLERİ ÖZELDİR; BAZILARI DAHA DA ÖZEL. KAOS VE SOYGUN TANRILARI (YANİ PAYDAY GANG) GÖRKEMLİ BİR SAYGI GÖSTERİSİNDEN AZINI İSTEMEZ. BU YÜZDEN SADAKATİNİ GÖSTEREBİLECEĞİN BU ALEVLİ PALYAÇO ÇEHRESİNİ SUNUYORUZ.",
["bm_msk_elegantteeth_desc"] = "BAŞKALARININ EKTİĞİNİ BİÇER, YALNIZCA İSTEDİĞİNİ ALIRSIN. ASİL AMA SADE VE VAHŞİ BU MASKE İHTİYAÇLARINI KARŞILAR.",
["bm_msk_elfhat_desc"] = "KİMYA DİPLOMASI OLAN BİR SOSYOPAT GREEN ELF, KUZEY KUTBU’NUN ZEHİRLER VE SİNİR TOKSİNLERİ UZMANIDIR.",
["bm_msk_elfhat_red_desc"] = "SANTA’NIN NOEL MİLİSİ’NDE BİR ASKER OLAN RED ELF, DÜŞMANLARININ KANINDA YIKANMAYI SEVER. SEN SEVMEZ MİYDİN?",
["bm_msk_elfhat_violet_desc"] = "PURPLE ELF ASLINDA ÇOK RAHAT BİR ADAMDIR. EVET, İNSAN KURBAN EDİYOR DA OLABİLİR ETMİYOR DA, BİR ÖLÜ DİRİLTİCİSİDİR AMA ONUN DIŞINDA ÇOK İYİDİR.",
["bm_msk_elfhat_yellow_desc"] = "NEŞELİ MİZACININ ARDINDA YELLOW ELF, BU DÜNYADAKİ YARAMAZLARI YAKIP BİTİRENE KADAR DİNLENMEYECEK ÖFKELİ BİR KUNDAKÇIDIR.",
["bm_msk_eng_01_desc"] = "SONSUZ MÜHİMMATLI BLASPHEMY KILICIYLA THE BULLET, BÜTÜN YÜREĞİYLE SAVAŞIRKEN TAM GÜCÜNÜ AÇIĞA ÇIKARIR.",
["bm_msk_eng_02_desc"] = "THE ROBOT, KİLLBOT ORDUSUNUN ONURLU BİR ÜYESİYDİ. EFENDİSİ EMP-R0R, İNSAN DİRENİŞİNİN LİDERİNİ ÖLDÜRMESİNİ EMRETTİĞİNDE PROTOKOLE UYMADI VE İNSANLIĞI YOK EDEMEDİ.",
["bm_msk_eng_03_desc"] = "HEP \"2 NUMARA\" DİYE ANILAN THE CULTIST, YOLUNA ÇIKAN HERKESE MEYDAN OKUR. DART GUN KUŞANMIŞ BU RAKİBİ HAFİFE ALMAMAK GEREKİR!",
["bm_msk_eng_04_desc"] = "THE MARINE, BİR DENEYİN TERS GİDİP TESİSE BOYUTLARARASI DEHŞET SALDIĞI SIRADA PRİMERDYNE R&D’DE GÖREVLİ BİR MUHAFIZDI. KİMİLERİ HERKESİ ÖLÜME TERK ETTİĞİNİ SÖYLERKEN KİMİLERİ DE ONU HERKESİ KURTARAN BİR KAHRAMAN OLARAK ALKIŞLIYOR!",
["bm_msk_evil_desc"] = "BOB ROBERTSON BİR MOR MADDE FABRİKASINDA ÇALIŞIYORDU. MOR MADDE FABRİKASI ESKİYDİ, ONARILMASI GEREKİYORDU. BOB BUNU AMİRLERİNE SÖYLEDİ AMA ONU DİNLEMEDİLER. BOB DA DOĞRU DÜRÜST ÇALIŞMAYIP İŞLETİM SİSTEMİNDE HAZIR GELEN OYUNLARI OYNAMAYI SÜRDÜRDÜ. BİR GÜN ERKENDEN ÇIKARKEN MOR MADDE DOLU BİR TANKTA ÇATLAKLAR OLUŞMAYA BAŞLADI. TAM YANINDAN GEÇERKEN TANK PATLADI VE BOB MOR MADDEYE BULANDI.$NL;$NL;HASTANEDEN ÇIKTIĞINDA ARTIK BİR SÜPER KÖTÜYDÜ. O GÜNDEN BERİ YÜZÜ MOR.",
["bm_msk_fable_cat_desc"] = "BİR KEDİ KADAR ÇEVİK, ONUN KADAR DA ŞANSLI OLARAK HER SOYGUNA CESARET EDER, HER SAVUNMAYI AŞARSIN. İŞLER SARPA SARDIĞINDA HEP SIYRILIR, DÖRT AYAK ÜSTÜNE DÜŞERSİN. DOKUZ CANINI HARCAMANIN DAHA İYİ BİR YOLU YOK; SEN SOĞUKKANLI BİR KATİLSİN, HERKES DE BİLİYOR.",
["bm_msk_fable_fox_desc"] = "THE FOX: YIRTICILARIN EN KURNAZI, EN SİNSİSİ. HİÇBİR KİLİT SENİ DIŞARIDA TUTAMAZ, HİÇBİR SAVUNMA PLANI ZEKÂNA VE HİLELERİNE DAYANAMAZ. İSTEDİĞİNİ ALIRSIN; HERKES BUNU KİMİN YAPTIĞINI, HATTA GERÇEKTEN OLUP OLMADIĞINI DÜŞÜNÜP DURUR.",
["bm_msk_fable_hare_desc"] = "MART TAVŞANI GİBİ DELİ. O ÇILGIN SARI GÖZLERİNE BAKARKEN PARAYI HEMEN VERSELER İYİ OLUR. SONRA PARAYI AL, KAÇ. BİR TAVŞANI KİMSE GEÇEMEZ.",
["bm_msk_fable_mouse_desc"] = "FARE KADAR SESSİZCE GİRİP ÇIKARSIN, KİMSE FARKINA VARMAZ. SENİ GÖRSELER BİLE BÖYLE KÜÇÜK BİR YARATIKTAN BÖYLE BİR KÖTÜLÜĞÜ KİM BEKLER? AMA EVET, BUNU YAPABİLİRSİN; HEPSİNİ.",
["bm_msk_falcon_desc"] = "HAYAT YALNIZCA HIZ VE KOŞMAKTAN İBARET DEĞİL! HIZLI BİR KAZAYLA GEÇİM KAYNAĞI YOK OLUNCA NEW RUSH CİTY’NİN GERÇEKTEN HAK ETTİĞİ KAHRAMANA DÖNÜŞTÜ. FALCON, SPEEDRUNNER’I İNDİRİP ŞEHRİ GERİ ALMAYA ANT İÇİYOR. ÇILDIRMIŞ DÜNYADAKİ TEK AKLI BAŞINDA KİŞİ FALCON MI, YOKSA TAVUK KOSTÜMLÜ BİR ADAM MI?",
["bm_msk_famine_desc"] = "KIYAMETİN ÜÇÜNCÜ ATLISI KITLIĞIN VÜCUT BULMUŞ HÂLİDİR. ÖYLE GÜÇLÜDÜR Kİ ONU GÖRENLERİ AÇLIKTAN ÖLÜME SÜRÜKLER.",
["bm_msk_fancy_goat_desc"] = "PENGUEN, HAYVANLAR ÂLEMİNİN EN HAVALI SOYGUNCUSUDUR. HER ŞEYİ BİLEN TAVIRLARLA DOLAŞIR, ACELE ETMEZ; İSTEDİĞİNİ İSTEDİĞİ ZAMAN ALIR, KİMSEYİ UMURSAMAZ. BU MASKEYİ TAKIP PATRONUN KİM OLDUĞUNU HERKESE GÖSTER.",
["bm_msk_fatboy_desc"] = "BU DOLGUN YANAKLI, PEMBE, SAĞLIKLI YÜZ; AMERİKA’DAKİ SİNEMA LOBİLERİNDE BULUNAN KIZARMIŞ HAMURLA ŞEKERİN O HARİKA, SİHİRLİ SİMYASINI TEMSİL EDİYOR.",
["bm_msk_fdm_desc"] = "FÖTR ŞAPKA, MODANIN VE ZARAFETİN ZİRVESİ. ÇOCUKLARLA YETİŞKİN ERKEKLERİ AYIRAN ÇİZGİ. BU KLASİK BAŞLIĞI HAK ETTİĞİ GURUR VE KARARLILIKLA TAŞI. ÇAĞLAR BOYUNCA FÖTR TAKMIŞ MİLYONLARCA BEYEFENDİNİN VE GANGSTERİN MİRASINI, GELENEĞİNİ HİSSET.",
["bm_msk_female_ecp_desc"] = "BU MASKE SANKİ MUZİP BİR KÖTÜLÜK YAYIYOR. ONA BAKAN ÇOĞU KİŞİNİN İÇİNE ANINDA BİR HUZURSUZLUK ÇÖKÜYOR; BANKA SOYARKEN DE TAM BÖYLE BİR ŞEYE İHTİYACIN VAR!",
["bm_msk_finger_desc"] = "THE GRIEFER, ÇOK ESKİ ÇAĞLARDA BU DÜNYADA YAŞADIĞI BİLİNEN EFSANEVİ BİR YARATIKTIR. KÖYLERDE VE KASABALARDA SIRADAN İNSANLARIN PEŞİNE DÜŞÜP ONLARI BİLEREK RAHATSIZ EDER, BEKLENMEDİK YOLLARLA AVLARDI. THE GRIEFER BU YAPTIKLARINDAN ZEVK ALIYORDU. KRALIN ADAMLARI SONUNDA ONU BULUP YOK EDENE KADAR HUZURU TEHDİT ETTİ.",
["bm_msk_firedemon_desc"] = "EFSANEVİ GRAUG’UN BAŞI. KARARMIŞ DEMİR ZIRHA BAĞLI, ATEŞTEN VE TÜTEN KARANLIKTAN YAPILMIŞ DEV BİR VARLIK. İNSAN BİÇİMLİ AMA BOYNUZLU, YÜZÜ DE ACIMASIZ BİR İBLİS GİBİ. BEDENİ CEHENNEM’DEN DE SICAK BİR FIRIN HARARETİYLE YANIYOR. EN İYİ ŞARKILARIN HEPSİNİ BİLİYOR.",
["bm_msk_firemask_desc"] = "EKİP, POLİS TEŞKİLATINA PEK SAYGI GÖSTERMİYOR OLABİLİR AMA ARKALARINDA BIRAKTIKLARI YANAN ENKAZLARI TEMİZLEYEN KADINLARA VE ERKEKLERE BÜYÜK SAYGI DUYUYOR. BU MASKE ONLARIN ÇABALARINA BİR SAYGI DURUŞU.",
["bm_msk_flapcapban_desc"] = "BİR ANDA, APTALLARI TAŞIYARAK PARA KAZANMAKTAN BIKTIĞINA KARAR VERİYORSUN. ŞEHRİN SAKİN BİR YERİNDESİN; ARKA KOLTUĞUNDA ZENGİN BİR PİSLİK OTURUYOR. CEBİNDE RAHAT BİN DOLAR NAKİT VARDIR. SENİ DURDURACAK KİMSE YOK. TORPİDO GÖZÜNDE SAKLI BİR 9 MM OLDUĞUNU HATIRLIYORSUN. BİR ARA SOKAĞA GİR VE TAKSİ ÜCRETİNİ TAHSİL ET.",
["bm_msk_flm_desc"] = "BİN BİRİNCİ GECEDE IŞIK YOKTU. AMA GEREĞİ DE YOKTU; EFSANELER, HER ŞEYİ GÖRMESİNİ SAĞLAYAN BİR ÇEHRE TAKMIŞ DİK BAŞLI BİR HAYDUTTAN SÖZ EDER.$NL;$NL;ATEŞ MODU DÜĞMESİNİ BASILI TUTARAK GECE GÖRÜŞÜ MODUNU ETKİNLEŞTİR.",
["bm_msk_foxfurhat_desc"] = "DOĞAYLA BAĞINI KOPARMAMAK ÖNEMLİ; O ZAMAN NEDEN BİR PARÇASINI YANINDA TAŞIMAYASIN? GERÇEKTEN TİLKİ AVLAMIYOR OLABİLİRSİN AMA GANİMET PEŞİNDE OLDUĞUN KESİN.",
["bm_msk_frank_desc"] = "FRANK BİR CANAVAR AMA SANILANIN AKSİNE HASSAS, DUYGUSAL BİR YARATIK. TEK AMACI HAYATINI BAŞKA BİR CANAVARLA PAYLAŞMAK.$NL;$NL;AMA \"DOĞDUĞU\" ANDAN İTİBAREN, KENDİ YARATICISININ BİLE ONUN YANINDA DURMAYA KATLANAMADIĞINI FARK ETTİ. BUNU ANLAYINCA FRANK BANKA SOYGUNCUSU OLMAYA KARAR VERDİ. SON.",
["bm_msk_franklin_desc"] = "DÜNYACA ÜNLÜ BİR HEZÂRFEN, YAZAR, MATBAACI, SİYASET KURAMCISI, POSTA MÜDÜRÜ, BİLİM İNSANI, MUCİT, YURTTAŞ HAKLARI SAVUNUCUSU, DEVLET ADAMI, DİPLOMAT VE KURUCU BABA.$NL;$NL;\"İLK AMERİKALI\" UNVANINA SAHİP VE 100 $ BANKNOTUN ÜZERİNDEKİ YÜZ.$NL;$NL;SUÇLULAR ARASINDA HÂLÂ SON DERECE POPÜLER.",
["bm_msk_funguy_desc"] = "SANA BİR FIKRA ANLATTIĞINDA GÜL. KATILA KATILA GÜL, UZUN UZUN GÜL, CİĞERLERİNDE HAVA KALMAYANA KADAR GÜL, SONRA GÜLMEYE DEVAM ET. ÇÜNKÜ DURURSAN SİNİRLENİR. SİNİRLENİNCE ACIKIR. ACIKINCA DA... EH, FIKRANIN SONUNU TAHMİN EDEBİLİRSİN.",
["bm_msk_gagball_desc"] = "YÜZÜNE BİR AĞIZ TOPU TAKIP İTAATKÂR TARAFINA BİR YÜRÜYÜŞ YAP.$NL;$NL;İNSANLAR BUNLARI PEK ÇOK NEDENLE TAKAR; BİRİ DE BAĞLAMA İÇEREN ROL OYUNLARIDIR. AMA HER ZAMAN ÖYLE OLMASI GEREKMEZ; BELLİ Kİ AĞIZ TOPLARI BANKA SOYGUNLARINDA DA KULLANILABİLİYOR.",
["bm_msk_gage_blade_desc"] = "THE GAGE BLADE, GAGE’İN EN SEVDİĞİ BALİSTİK YÜZ MASKELERİNDEN BİRİDİR. KAFAN PATLAMADAN ÖNCE YÜZÜNÜ BİR İKİ 9 MM MERMİDEN KORUR.$NL;$NL;BU MASKE OLMASA GAGE BUGÜN OLDUĞU HARİKA İNSAN OLAMAZDI.",
["bm_msk_galax_desc"] = "MİLHOUSE ANDERSON TEHLİKELİ KİMYASAL ATIKLARLA UĞRAŞTIĞI BİR KİMYA TESİSİNDE ÇALIŞIYORDU. ARKADAŞLARI, ŞAKA OLSUN DİYE ONU TEHLİKELİ KİMYASAL ATIKLARIN TUTULDUĞU ODAYA KİLİTLEMENİN İYİ FİKİR OLDUĞUNU DÜŞÜNDÜ. BİLMEDİKLERİ ŞEY, TEHLİKELİ KİMYASAL ATIKLARIN TEHLİKELİ OLDUĞUYDU. SAATLERCE KİLİTLİ KALAN MİLHOUSE, YÜKSEK DÜZEYDE RADYASYONA VE BAŞKA KÖTÜ ŞEYLERE MARUZ KALDI.$NL;$NL;SONUNDA ÇIKARDIKLARINDA BİR SÜPER KÖTÜYE DÖNÜŞMÜŞTÜ. O GÜNDEN BERİ ÇOK ÖFKELİ.",
["bm_msk_gasmask_desc"] = "GAZ MASKESİ ESKİ ÇAĞLARIN SAVAŞLARINA AİT GÖRÜNEBİLİR AMA GAZIN HÂLÂ KULLANILABİLDİĞİ ŞEHİR SAVAŞ ALANINDA HAYATİ BİR EKİPMANDIR. AYRICA HAVALI, HIRILTILI BİR NEFES SESİ VERİR.",
["bm_msk_gcm_desc"] = "DÖRT YIL OLDU. DÖRT YIL SIKI ÇALIŞMA, PİŞİRİLEN METAMFETAMİN, ATILAN KURŞUNLAR VE TAŞINAN GANİMET. AMA DAHA YENİ BAŞLIYORUZ. BİRAZ NOSTALJİ DE HİSSEDİYORUZ. WASHINGTON’A GELİP BURADAKİ İLK SOYGUNUMUZU YAPALI DÖRT YIL OLDU; ARTIK PROFESYONELİZ. BİRİNİN DOĞUM GÜNÜYSE ONA HEDİYE ALMALISIN. BU YÜZDEN CHAINS’İN MASKESİNİ SICAK, GÖZ KAMAŞTIRAN 24 AYAR ALTINLA KAPLADIK. İYİ Kİ DOĞDUN PAYDAY 2!",
["bm_msk_gentgla_brown_desc"] = "THE AGENCY DAHA YUMUŞAK BİR DOKUNUŞ İSTEDİĞİNDE AGENT BROWN’I GÖNDERİR. SORGUDAN ÖNCE SİGARA İKRAM EDEN TÜRDEN BİR ADAM. İNSAN İLİŞKİLERİ HARİKA, MİZAHI KUVVETLİ. SENİ ÖYLE GÜLDÜRÜR Kİ TABANCASINI KARNINA DAYAYANA KADAR FARK ETMEZSİN.",
["bm_msk_gentgla_dark_desc"] = "HARİKA, AGENT BLACK GELİYOR. BU ADAM TAM BİR MANYAK. ELEKTROTLA İŞKENCE, PİYANO TELİYLE BOĞMA; HEPSİ ONUN İŞİ. THE AGENCY ONU ANCAK CESET SAYISI ARTIK ÖNEMİNİ YİTİRDİĞİNDE SALAR. YİNE DE YAŞLILARA KARŞI İNANILMAZ TATLIDIR. İNSANLAR KARMAŞIK GALİBA.",
["bm_msk_ggac_desc"] = "İŞTE HARBİNGER GELDİ! İNSANLAR YALNIZCA BİR KISMINI GÖRSELER BİLE BİR İNSAN KAFATASINI ÇOĞU ZAMAN TANIYABİLİRLER. HATTA BEYİNDE BUNUN İÇİN ÖZEL BİR BÖLGE BİLE VAR. BU KESİNLİKLE İNSAN KAFATASI DEĞİL; BİR KATLİAM İBLİSİNE AİT.$NL;$NL;GÖĞE BAKIN; CENNETTEN ATEŞ YAĞIYOR, ARDINDAN ERİMİŞ ALTIN GELİYOR. TOPRAK, SOYGUNCU OLARAK BÜYÜKLÜĞÜNÜ AYDINLATAN, PARILDAYAN, MUHTEŞEM BİR METAL ÖRTÜYLE KAPLANIYOR. ÇITA HER YÜKSELDİĞİNDE MEYDAN OKUMAYI KABUL EDİYORSUN; YİNE ÖYLE YAPTIN. OVERKILL OFİSİNDE BİR TAHT YAPILIYOR. BÖYLECE ÖNÜNE NE ATARSAK ATALIM YENİLMEYEN O İLAHİ BECERİLERİNİN ÖNÜNDE EĞİLİP TAPINABİLECEĞİZ.",
["bm_msk_ghm_desc"] = "İŞTE GELDİK; HESAPLAŞMA ZAMANI. SOYGUNCU AİLEMİZ, SINIRINI HENÜZ GÖRMEDİĞİMİZ BİR GÜCE KARŞI. TEK BİR ŞEY BİLİYORUM: YA BURADAN BİRLİKTE ÇIKACAĞIZ YA DA DENERKEN ÖLECEĞİZ. BİZ PALYAÇOLARIZ, HIRSIZLIĞIN LANET TANRILARIYIZ VE KENDİ KURALLARIMIZLA OYNARIZ. O YÜZDEN SIRADA NE OLURSA OLSUN ALTIN BİR İHTİŞAMLA PARLAMAYA HAZIRIZ.",
["bm_msk_ghost_desc"] = "BU GHOST MASKESİ GELECEKTEN GELMİŞ GİBİ GÖRÜNÜYOR; BELKİ DE GERÇEKTEN ÖYLEDİR.$NL;$NL;KARBON FİBER VE GENETİK MÜHENDİSLİĞİYLE ÜRETİLMİŞ ÖRÜMCEK İPEĞİNDEN YAPILMIŞ TAM BAŞ KORUMASI. SENİ ÜST DÜZEY BİR MOTO GP SÜRÜCÜSÜ BİLE SANABİLİRLER.$NL;$NL;YAPACAKLARI SON HATA OLUR.$NL;$NL;BU MASKE, KÖTÜ ŞÖHRET AĞACI ÖDÜLÜDÜR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN. ANCAK DESEN, RENK VEYA MALZEME İLE BUNLARI BİRLEŞTİRMEK İÇİN ÖDEDİĞİN ÖZELLEŞTİRME ÜCRETİ KAYBOLUR.",
["bm_msk_ghx_desc"] = "İLK KEZ MASKE TAKTIĞIM ANI HATIRLIYORUM. GERÇEKTEN YEDİ YIL ÖNCE MİYDİ? BİR ŞEYİ UZUN SÜRE YAPTIĞINDA ENİNDE SONUNDA BİR YOL AYRIMINA GELİRSİN. BU İŞTE YA BİR SİLAHIN NAMLUSUNA YA DA TATLI HAYATA BAKIYORSUNDUR. HERKES SEÇİMİNİ YAPMALI. HERKES BU SEÇİM UĞRUNA NEYİ RİSKE ATACAĞINA KARAR VERMELİ. PAYDAY İÇİN BU HEP YA HEP YA HİÇ OLDU!",
["bm_msk_gladiator_helmet_desc"] = "GLADYATÖRLER, ANTİK ROMA’DA TEK GÖREVİ HALKA KORKUNÇ ŞİDDET GÖSTERİLERİYLE EĞLENCE SUNMAK OLAN ACIMASIZ BİR SINIFTI. YÜKSEK SORGUÇLU BU MİĞFER TARZI BALIĞA BENZER. KILIÇ VE KULE KALKANIYLA DÖVÜŞEN AĞIR GLADYATÖR SINIFI MURMİLLO TARAFINDAN TAKILIRDI. ROMA ATEŞ TANRISI VULCAN’I SİMGELER, GÜCÜ VE ONURU TEMSİL EDERLER.",
["bm_msk_goat_desc"] = "DOLPH THE GOAT DOĞAL GÜCÜ VE TAŞI TEMSİL EDER.$NL;$NL;İSVEÇ’İN EN KUZEYİNDEKİ BİR DAĞ MAĞARASINDA BİR GRUP MACERACI TARAFINDAN BULUNDU.$NL;$NL;EFSANEYE GÖRE GÖK GÜRÜLTÜSÜ TANRISI THOR’UN, İKİ KEÇİNİN ÇEKTİĞİ BİR ARABASI VARDI. AMA BU MASKENİN O EFSANEYLE MUHTEMELEN İLGİSİ YOK. ÖYLE OLSA ÇILGINLIK OLURDU.",
["bm_msk_goat_goat_desc"] = "KEÇİ HAYVANLAR ÂLEMİNDE PEK SAYGI GÖRMEZ. DİĞER HAYVANLAR SIK SIK ONUNLA DALGA GEÇER AMA BU TAM DA İŞİNE YARAR. BU APTAL MASKEYİ TAKMAK SANA DA AYNI AVANTAJI SAĞLAYABİLİR; POLİSLER SENİ HAFİFE ALIR.",
["bm_msk_goggles_desc"] = "SIZMA GÖREVLERİNDE ÖZEL EĞİTİMLİ AJANLAR KULLANAN TEK DEVLET AMERİKAN HÜKÜMETİ DEĞİL. JAPONYA’NIN ANBU ADINDA KENDİ BİRLİĞİ VAR. BU MASKE YALNIZCA BİR PROTOTİP OLSA DA ONLARIN KULLANDIĞINA ÇOK BENZİYOR.$NL;$NL;ATEŞ MODU DÜĞMESİNİ BASILI TUTARAK GECE GÖRÜŞÜ MODUNU ETKİNLEŞTİR.",
["bm_msk_grant_desc"] = "ASKER, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETTİ.$NL;$NL;BİR KORUYUCU VE SAVAŞÇI; HEM DE BÜYÜK BİR KORUYUCU VE SAVAŞÇI.$NL;$NL;18. BAŞKAN, TARİHİN EN SEVİLMEYEN BAŞKANLARINDAN BİRİYDİ. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_msk_greedy_the_elf_desc"] = "NOEL BABA’NIN ELFLERİNİN İŞİ ZOR. SAĞLIK VEYA DİŞ SİGORTASI YOK; MRS. CLAUS’UN KIRBACINA KATLANIYORLAR. AMA EN AZINDAN ŞU MÜTHİŞ ŞAPKALARI VAR. ",
["bm_msk_greek_tragedy_desc"] = "BİR YUNAN TRAGEDYASININ BÜTÜN BÖLÜMLERİNİ SİMGELEYEN MASKE.$NL;$NL;ESKİ YUNAN’DA MASKELER, TÖRENLERDE VE KUTLAMALARDA TANRILARA TAPINMAK İÇİN KULLANILIRDI.$NL;$NL;BU MASKE HER SOYGUNU ÖZETLER: BİRİNİN ALARMI ÇALDIRMASINA DUYULAN ÖFKE, KASAYI AÇMANIN SEVİNCİ VE YAKALANMANIN TRAJEDİSİ.",
["bm_msk_grendel_desc"] = "GENETİK MUTASYON EVRİMİMİZİN ANAHTARIDIR. TABİİ EVRİMİMİZİN YEŞİL, PULLU, KATİL VE RADYASYONLU TÜRDEN OLDUĞUNU VARSAYARSAK.",
["bm_msk_grin_desc"] = "BİR ZAMANLAR BİR ADAMLA KARDEŞİ VARMIŞ. BİRLİKTE BAŞARILI BİR ŞİRKETİN SAHİBİYMİŞLER. BİR GÜN, GEÇİCİ OLARAK YALNIZCA TEK MÜŞTERİLERİ KALMIŞ. MÜŞTERİ KORKUYA KAPILIP AYRILMAK İSTEMİŞ. AMA DOĞRUDAN AYRILIP SÖZLEŞMEYİ BOZDUĞU İÇİN CEZA ÖDEMEK YERİNE, ADAMLA KARDEŞİNİN ŞİRKETİNİ AÇ BIRAKARAK ÖLDÜRMÜŞ.$NL;$NL;ADAMLA KARDEŞİ HER ŞEYİNİ KAYBETMİŞ. BU MASKENİN, ADAMIN AKLINI KAÇIRDIĞI GÜN YÜZÜNDE BELİREN İFADENİN TA KENDİSİ OLDUĞU SÖYLENİR.",
["bm_msk_grizel_clean_desc"] = "BU, CLOVER’IN İKONİK MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_groucho_desc"] = "KUSURSUZ KILIK DEĞİŞTİRMEK; SAÇINI BOYAMAK, İRİSLERİNİ DEĞİŞTİRMEK, PARMAK İZLERİNİ YAKMAK DEMEK DEĞİLDİR. BAZEN AÇIKÇA TUHAF GÖRÜNMEK İNSANLARI BAKIŞLARINI KAÇIRACAK, SENİ UMURSAMAYACAK KADAR RAHATSIZ EDER.",
["bm_msk_grv_01_desc"] = "YARIM SOKAK, YARIM SOKAK$NL;YARIM SOKAK İLERİ$NL;FIRST WORLD BANK’E$NL;YÜRÜDÜ DÖRT SOYGUNCU$NL;İLERİ PAYDAY GANG$NL;ALTINA HÜCUM, DEDİLER$NL;FIRST WORLD BANK’E$NL;YÜRÜDÜ DÖRT SOYGUNCU",
["bm_msk_grv_02_desc"] = "HER ŞEY HER ZAMAN GÖRÜNDÜĞÜ GİBİ DEĞİLDİR. MASKENİN ARKASINDA BİR YÜZ VAR, DOĞRU. PEKİ YÜZÜN ARKASINDA NE VAR? BELKİ BAŞKA BİR YÜZ. GERÇEK KİŞİNİN NEREDE OLDUĞUNU NASIL BİLİRSİN? ÖZE, İÇİNDEKİ BENLİĞE ULAŞMADAN ÖNCE KAÇ KATMAN KALDIRMAK GEREKİR?",
["bm_msk_grv_03_desc"] = "ŞAN İÇİN İNCE İŞLENMİŞ ARMASIYLA BU GÖSTERİŞLİ BAŞLIK ETKİLEYİCİ OLACAK. GÜZEL NAKIŞLARINI HERKESİ KISKANDIRACAK ŞEKİLDE GURURLA SERGİLE. AMA ALÇAK KAPILARA DİKKAT.",
["bm_msk_grv_04_desc"] = "RED MACHINE’İ KİMSE DURDURAMAZ! HIZLI, BUZ GİBİ VE ACIMASIZDIR. SERİ HAREKETLER, YILDIRIM GİBİ DARBELER VE KUSURSUZ TAKTİKLERLE RAKİBİNİ REZİL EDER; ÇARESİZLİK İÇİNDE AĞLAMAYA BIRAKIR. TIPKI PAYDAY GANG GİBİ.",
["bm_msk_gumbo_desc"] = "YUTAN PALYAÇO OLARAK BİLİNEN ADAM HAKKINDA PEK AZ ŞEY BİLİNİYOR. AMA UZUN SÜRE İNSANLAR KIRMIZI GÖZLERİNİN KIYAFETİNİN PARÇASI OLDUĞUNU SANDI. ELBETTE YANILIYORLARDI. ARTIK İNSANLAR, EN TECRÜBELİ BELALILARI BİLE KORKUDAN TİTRETEN KÖTÜCÜL KAHKAHALI, KIRMIZI GÖZLÜ PALYAÇODAN KORKUYOR.$NL;$NL;SÖYLENTİYE GÖRE SOKAK ARALARINDA ŞEYTANİ BİR SURETTE BİR ŞEY... YA DA BİRİNİ ARIYOR. TEK BİLİNEN, İNSANLARIN SONUNDA ÖLDÜĞÜ; MÜMKÜN SANDIĞINDAN ÇOK DAHA ÖLÜ OLDUĞU...",
["bm_msk_gwm_desc"] = "BEŞ YIL OLDU MU BİLE? VAY BE. BU HAYATTA BU KADAR UZUN SÜRE DAYANAN PEK OLMAZ. SON BİR YIL ZORDU. HEM DE ÇOK ZOR. AİLEYİ EN SAVUNMASIZ YERİMİZDEN VURDULAR, POLİS HER GÜN BİRAZ DAHA YAKLAŞIYOR VE NEREDEYSE BOYUMUZU AŞAN İŞLERE BULAŞTIK. ÇOĞU SOYGUNCU BU DURUMDA YA ÖLÜR YA DA ÖMRÜNÜN SONUNA KADAR HAPSİ BOYLARDI. AMA BİZ SIRADAN ÜÇKÂĞITÇILAR DEĞİLİZ. BİZ PAYDAY’İZ. İŞİ HER ZAMAN HAKKIYLA YAPARIZ. ALTINI DA HER ZAMAN ALIRIZ.",
["bm_msk_hatgla_dark_desc"] = "BU BENİM BEREM. ONA BENZEYEN ÇOK BERE VAR AMA BU BENİM. BEREM EN İYİ DOSTUMDUR. HAYATIMDIR. HAYATIMA HÂKİM OLMAM GEREKTİĞİ GİBİ BEREME DE HÂKİM OLMALIYIM.",
["bm_msk_hatgla_green_desc"] = "BERE TAKAN İNSANLARIN HİÇBİR ZAMAN BERESİZ OLMADIĞINI FARK ETTİN Mİ? ON YILDIR BÖYLE BİR BERE TAKAN BİRİNİ TANIYORUM; KAFASININ TEPESİNİ HİÇ GÖRMEDİM. BİR KEZ BİLE.",
["bm_msk_heat_desc"] = "KLASİK BİR HOKEY MASKESİ.$NL;$NL;BİR ADAM BİR KERESİNDE BANA ŞÖYLE DEMİŞTİ...$NL;$NL;\"TEHLİKENİN KÖŞEDE OLDUĞUNU HİSSEDERSEN 30 SANİYEDE BIRAKIP GİDEMEYECEĞİN HİÇBİR ŞEYE BAĞLANMA.\"",
["bm_msk_hectors_helmet_desc"] = "PAYDAY GANG’İ GAMMAZLARSAN BİR MİSİLLEME BEKLEMELİSİN. EKİP, PARMAK SALLAYIP SERTÇE AZARLAMAKLA YETİNMEZ. MERMİ BEKLEYEBİLİRSİN; HEM DE BOLCA. BU BARET, ESKİ USUL ÇEVİK KUVVET TEKNOLOJİSİ: ÖNÜ GÜÇLENDİRİLMİŞ CAMLI AĞIR DEMİR. DELİP GEÇMEYE ÇALIŞANA BOL ŞANS.",
["bm_msk_hockey_desc"] = "HOKEY MASKESİ, HOKEY KALECİLERİNİN BAŞLARINI YARALANMADAN KORUMAK İÇİN TAKTIĞI MASKEDİR.$NL;$NL;AYNI ZAMANDA YALNIZCA YÜKSEK KALİTELİ MALZEMELERLE ELDE YAPILMIŞ İKONİK SOYGUNCU MASKESİDİR. SENİ PAKLARDAN DEĞİL, ORTALIKTA İŞİNİ YAPARKEN TANINMAKTAN KORUR.$NL;$NL;HANİ ŞU ÇOK İYİ YAPTIĞIN İŞTEN. ÇALMAKTAN.",
["bm_msk_hockeynermark_desc"] = "GERÇEK BİR SOYGUNCU VE SAVAŞÇI. İŞİNİ BİLMEK. ASLA VAZGEÇMEMEK. İŞİ BİTİRMEK.$NL;SENİ SELAMLIYORUZ!",
["bm_msk_hog_desc"] = "YENİ MESAJINIZ VAR! *BİP*$NL;$NL;SELAMLAR, BEN OVERKILL’DEN ALMIR. SİPARİŞ ETTİĞİNİZ MASKE ŞİMDİYE KADAR TESLİM EDİLMİŞ OLMALI...$NL;$NL;İÇİNDE BİR TALİMAT LİSTESİ VAR...$NL;$NL;DİKKATLE OKUDUĞUNUZDAN EMİN OLUN!$NL;$NL;BAŞKALARINA ZARAR VERMEKTEN HOŞLANIR MISINIZ? ÖYLEYSE BU MASKE SİZİN İÇİN.",
["bm_msk_homburg_desc"] = "ASLA AİLEYE KARŞI TARAF TUTMA.",
["bm_msk_homburg_grey_desc"] = "UNUTMA: SEVDİKLERİNE HEP ZAMAN AYIR AMA İŞİN HAKKINDA SORU SORMALARINA İZİN VERME.",
["bm_msk_horned_king_desc"] = "VİKİNGLER OLARAK BİLİNEN CERMEN KÖKENLİ İSKANDİNAV DENİZCİLER, 8. YÜZYIL SONLARINDAN 11. YÜZYIL SONLARINA KADAR YAŞAMIŞ AMANSIZ SAVAŞÇILARDI. KUDRETLİ BALTALARI VE BOYNUZLU MİĞFERLERİYLE SAVAŞIN ORTASINDA GURURLA DİMDİK DURURLARDI. BU ESKİ SAVAŞÇILARIN RUHUNU YAKALAMAK İSTİYORSAN BU MASKE İŞİNİ GÖRÜR.",
["bm_msk_horse_desc"] = "DON JUAN KAPILARI VURARAK AÇMAYI SEVER.$NL;$NL;TAK TAK. KİM O? DON JUAN. HAZIRLAN.$NL;$NL;USTA İPUCU: HOTLINE MIAMI’DE BU MASKEYİ KULLANIRKEN DUVAR DİBİNDEKİ YERDE ÖLDÜRMELERDEN 2200 PUAN KAZANIRSIN.",
["bm_msk_hothead_desc"] = "KORKUNÇ BİR YANARDAĞIN ÖFKESİYLE SALDIRGAN HOTHEAD, ALEV GİBİ HIZIYLA GECEYİ AYDINLATIR! ÇILGIN ALEVİNİ NE TUTUŞTURUR? ÖFKELİ BOĞA NEDEN KAÇAR? SORACAK KADAR YAKLAŞABİLEN PEK AZ KİŞİ OLDU; TUTARLI YANIT ALABİLENLER DAHA DA AZ!",
["bm_msk_hoxton_clean_desc"] = "BU, İKONİK HOXTON MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_hoxton_desc"] = "HOXTON’IN MASKESİ.",
["bm_msk_hoxton_glow_desc"] = "MEGA HOXTON MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_hunter_desc"] = "KEVİN İÇİN OMURGAYI SÖKÜP GÖKYÜZÜNE MEYDAN OKUYARAK HAYKIRMAK ASLA YETMEZDİ. HER SEFERİNDE KAFATASINI DA SİKERDİ.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_icedeer_desc"] = "O GEYİKLİ ÇİZGİ FİLMİ HATIRLIYOR MUSUN? HANİ ANNESİNİ ÖLDÜRDÜKLERİ? EVET, YOK; BUNU TAKARKEN KİMSE SANA VEYA EKİBİNE BULAŞMAYACAK. AKSİNE, SEN ONLARI AVLIYOR OLACAKSIN.",
["bm_msk_iceskull_desc"] = "MERMİLER UÇUŞURKEN SOĞUKKANLI KALMAK HİÇ BU KADAR KORKUNÇ GÖRÜNMEMİŞTİ. BU, KARŞINA ÇIKAN HERKESİN ÖDÜNÜ KOPARACAK. BELKİ SİLAHINDAN BİLE DAHA ÇOK.",
["bm_msk_in31_cyberpunk_max_desc"] = "BU YÜZ KORUMASINI TAKAN SOYGUNCUDAN KUSURSUZ BİR SAAT MEKANİZMASI GİBİ DİJİTAL HASSASİYET AKAR. KARŞISINA DİKİLDİĞİNDE HER DÜŞMAN AZ DA OLSA ÜRPERİR.",
["bm_msk_in32_goldenbrute_desc"] = "ALTININ VARSA ONU NE YAPACAĞIN HEP BİR SORUDUR. KASAYA KOYABİLİR, NAKDE ÇEVİREBİLİR VEYA KENDİNİ DAHA BELALI GÖSTERMEK İÇİN KULLANABİLİRSİN. ELBETTE SONUNCUSUNUN PEK ÇOK YOLU VAR. BİRİSİ BU PARILDAYAN YÜZÜ DÖVMENİN DE ONLARDAN BİRİ OLDUĞUNA KARAR VERMİŞ. İYİ SEÇİM Mİ? KARAR SENİN.",
["bm_msk_in32_ingoldnito_desc"] = "UYDURUK DİNLER VE KADİM SİLAHLAR, İYİ BİR HAFİF MAKİNELİ SİLAHLA VEYA HİÇ BOZULMAYAN BİR KAÇIŞ MİNİBÜSÜYLE BOY ÖLÇÜŞMEYEBİLİR. AMA NESİLLER BOYU AKTARILAN TEKNİKLERLE BİR ZANAATKÂRIN İNCE İNCE İŞLEDİĞİ BÖYLE BİR MASKE, BİR BULLDOZER İNDİRİRKEN KENDİNİ GERÇEKTEN HARİKA HİSSETMENİ SAĞLAR. ARADA BİR DÜZENLENEN O TUHAF MASKELİ BALO İÇİN DE UYGUNDUR.",
["bm_msk_in33_overkillpunk_desc"] = "HEPİMİZ ZAMAN ZAMAN BİRAZ DELİREBİLİRİZ. AMA BU MASKE, İPLERİ TAMAMEN KOPARDIĞIN ANLAR İÇİN. ZATEN SOYGUNCULUKTA BU SEVİYEYE GELMEK İÇİN AKLINI RESMEN KAÇIRMIŞ OLMALISIN!",
["bm_msk_infamy_hood_desc"] = "DÜNYANIN KARANLIK KÖŞELERİNDE SOYGUNCULARDAN DAHA ESKİ, DAHA İĞRENÇ ŞEYLER VAR. BİRİ DE KAMUL. ÇOKTAN ÖLMÜŞ BİR ADAMIN BURADA KALMIŞ RUHU MU, GÖLGELER DİYARINDAN GEÇMİŞ BİR ŞEY Mİ, BİLMİYORUZ. TEK BİLDİĞİMİZ, BU YÜZE BAKIP DA ANLATACAK KADAR YAŞAYANIN PEK AZ OLDUĞU.",
["bm_msk_infamy_lurker_desc"] = "DİŞLER KORKUTUCUDUR. BÜYÜK DİŞLER DAHA KORKUTUCUDUR. KARANLIKTA PUSUDA BEKLERKEN BİRDEN GICIRDAYAN DEVASA, SİVRİ, KÖPEKDİŞİ GİBİ DİŞLER İSE İNSANIN ALTINA ETMESİNE YETER. BÜTÜN BUNLARI DÜŞÜNÜNCE SİVİLLERİ HİZAYA SOKMAK İÇİN DAHA İYİ BİR MASKE AKLINA GELİYOR MU?",
["bm_msk_instinct_desc"] = "BU MASKE, UZAK BİR YERDEN GELEN GİZEMLİ BİR SAVAŞÇIYA AİTTİ. SEZGİLERİYLE YOL BULUP DÜNYADAKİ KÖTÜCÜL GÜÇLERİ AVLAYARAK DİYARLARI DOLAŞIRDI. ZİNDANLARA GİRİP KARŞILAŞTIĞI BİNLERCE KÖTÜ VARLIĞI ÖLDÜRDÜ. SONUNDA GELECEK NESLİN YOLUNU SÜRDÜRECEĞİNİ BİLEREK HUZUR BULDU.",
["bm_msk_invader_desc"] = "İNANMAK İST... CIZ! GÜÇ SENİN... CIZ! UZUN YAŞA VE... CIZ! NEDEN HEPİMİZ GEÇİNİP GİDEMİYORUZ? ÇÜNKÜ CIZ! İŞTE O YÜZDEN.",
["bm_msk_irondoom_desc"] = "DOCTOR CRIME, OVERKILL COMİCS’İN ÇİZGİ ROMANLARINDA YER ALAN AMERİKALI KURGUSAL BİR SÜPER KÖTÜDÜR.$NL;$NL;KARAKTERİ YAZAR VE EDİTÖR DAVİD GOLDFARB YARATTI, SANATÇI MAX ELMBERG SJÖHOLM TASARLADI.$NL;$NL;İLK KEZ THE AMAZİNG CAREER CRİMİNALS: THE PAYDAY GANG MEETS DOCTOR CRIME! ADLI ESERDE GÖRÜNDÜ.",
["bm_msk_ja21_biden_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETMEYİ AMAÇLIYOR.$NL;$NL;KESKİN GÖRÜŞLERİ OLAN BİR ADAM OLDUĞUNA ŞÜPHE YOK.$NL;$NL;BAZILARINA GÖRE 46. BAŞKAN KAOSA DÜZEN GETİRECEK; BAZILARIYSA TAM TERSİNİ DÜŞÜNÜYOR. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.$NL;$NL;KONSEPT: ROGER MATA.",
["bm_msk_jake_desc"] = "İYİ YILAN DİYE BİR ŞEY YOKTUR AMA ÖLÜMCÜL YILANLAR ARASINDA BİLE KOBRA BAŞLI BAŞINA BELADIR. AÇILMIŞ BOYNUNU GÖRÜRSEN BU BİR TEHDİTTİR; KAÇ. UZUN DİŞLERİ FİL DERİSİNİ DELEBİLİR; KAÇ. ZEHRİNİN TEK DAMLASI BİR BULLDOZER’I DEVİREBİLİR; YANİ... KISACASI BUNU GÖRDÜĞÜNDE KAÇ. ÇÜNKÜ TÜKÜRÜYORLAR DA.",
["bm_msk_jaw_desc"] = "CAM ÇENENİ METAL BİR ÇENEYLE KORU.$NL;$NL;BUNDAN SONRA ÇENENLE ÇİĞNEYECEĞİN TEK ŞEY KOLLUK GÖREVLİLERİ OLACAK, DEĞİL Mİ?",
["bm_msk_jesterskulls_desc"] = "BUNU TAK; PAYDAY GANG EKİBİNİ İNDİREBİLECEĞİNİ SANAN HER KOLLUK GÖREVLİSİNİN YÜZÜNE O KÜÇÜK ALTIN KAFATASLARINI ŞINGIRDAT. SONRA BURUNLARININ DİBİNDEN GANİMET ÇANTALARIYLA KAÇARKEN ÖLÜLERİ UYANDIRACAK KADAR YÜKSEK BİR KAHKAHA PATLAT. HADİ, İSTEDİĞİNİ BİLİYORSUN. ",
["bm_msk_jfr_01_desc"] = "STERLİNG’İN BEREYLE ARMAYI ZORLU EĞİTİM VE SAVAŞLA KAZANDIĞINI DÜŞÜNMEK HOŞ OLURDU. AMA GERÇEK ŞU Kİ SUBAYLAR KULÜBÜ’NDE BİRKAÇ GENÇ KISRAĞI NE KADAR ETKİLEDİKLERİNİ GÖRDÜ. DIŞARI ÇIKMA DAVETİ, BİRKAÇ BEL ALTI YUMRUK VE BAYILAN BİR ALBAYIN ARDINDAN STERLİNG’İN KENDİNE AİT KIRMIZI BİR BERESİ OLDU. BİR DE BİRKAÇ KISRAĞI. ŞAHANE!",
["bm_msk_jfr_02_desc"] = "BU ŞAPKA NORMAL, STANDART BİR M43 ARAZİ ŞAPKASI GİBİ GÖRÜNEBİLİR. WOLFGANG KADAR KENDİNİ BEĞENMİŞ BİR ADAM İÇİN BÖYLESİNE MÜTEVAZI BİR BAŞLIĞIN TUHAF BİR SEÇİM OLDUĞUNU DA DÜŞÜNEBİLİRSİN. AMA BU ŞAPKANIN ONUN İÇİN ÖZEL BİR ANLAMI VAR. WOLFGANG’IN GERÇEKTEN SEVEBİLDİĞİNE ŞAŞIRABİLİRSİN. İÇİNE, UĞRUNA SAVAŞTIĞI SEVGİLİSİNİN FOTOĞRAFI İLİŞTİRİLMİŞ.",
["bm_msk_jfr_03_desc"] = "KURGAN GAZ MASKESİNİ SAVAŞ DUMANINI DIŞARIDA TUTMAK İÇİN TAKMIYOR. ÖFKE ALEVLERİNİ İÇERİDE TUTMAK İÇİN TAKIYOR. KENDİ TARAFININ İHANETİNE UĞRAYAN KURGAN, ZIRHLI ALEV ASKERLERİNİN PUSUSUNDAN ZOR KURTULDU. MASKENİN İÇİNDE YALNIZCA KENDİ YANMIŞ ETİNİN KOKUSU VAR; KİMSEYE GÜVENMEMESİNİ SÜREKLİ HATIRLATIYOR.",
["bm_msk_jfr_04_desc"] = "RİVET AMERİKALIDIR; AMERİKALILAR GELENEĞE DEĞER VERİR. BAŞKANLIK MAKAMINDAN ÜLKENİN EN AŞAĞILIK PİSLİĞİNE KADAR GELENEK ÖNEMLİDİR. O YÜZDEN BİR APTALIN SURATINA SİLAH DAYAYIP \"SÖKÜL\" DİYECEKSEN TARİHİNİ İYİ BİLSEN İYİ OLUR. JESSE JAMES GİBİ, BİLLY THE KİD GİBİ, BANDANA TAKARSIN.",
["bm_msk_jig_01_desc"] = "UZAYDA GÜVENİLİR BİR YOLDAŞA İHTİYACIN VAR. UZAK GEZEGENLERDEKİ DEV CANAVARLARDAN UZAYIN KENDİSİNE KADAR HER ŞEY ÖLÜMCÜLKEN BİR MÜTTEFİK GEREKİR. YALNIZCA KİRALIK BİR SİLAH DEĞİL. SENİN HAYATTA KALMANI, BAŞKALARININSA KALMAMASINI SAĞLAYAN BİR DOST VE ASKER. GARRETH EKİBİNDE DİYE SEVİN. SÜRÜYE ÇOBANLIK ETMENE YARDIM EDİYOR DİYE SEVİN.",
["bm_msk_jig_02_desc"] = "\"ŞU BAŞ BELASI GENÇLER CANLARI NE İSTERSE YAPARAK ORTALIKTA DOLAŞABİLECEKLERİNİ SANIYOR. ANLAMIYORLAR MI? BENİM VAR OLMAMIN BİR NEDENİ VAR. BANA İTAAT EDİLMELİ; HÜKMÜME DE SÖZÜME DE. DÜNYADAN KAÇIP SADECE ÖZGÜR HİSSETMEK Mİ? O NASIL BİR HAYAT ÖYLE? ŞU SARI KUŞ İCATLARININ ÜZERİNDE GEZİNİYORLAR. NE İMPARATORLUĞA SAYGI VAR NE DE İMPARATORA. REZALET!\"",
["bm_msk_jimmy_desc"] = "JIMMY’NİN İKİNCİ MASKE DENEMESİ ÇOK DAHA İYİ SONUÇ VERDİ; ÇÜNKÜ GAGE’DEN YARDIM ALDI. MASKEDE KOKAİN ÇEKMİŞ GRİM REAPER’IN TA KENDİSİ TASVİR EDİLİYOR. JIMMY’NİN HEM ÇILGIN HEM ÖLÜMCÜL YANINI YANSITIYOR, DÜŞMANLARINA KORKU SALMAYI AMAÇLIYOR.",
["bm_msk_jimmy_duct_desc"] = "JIMMY, KENDİNE ÖZGÜ MASKESİNİ YAPMADAN ÖNCE PEK FAZLA MASKE YAPMAMIŞTI; BELLİ DE OLUYOR. MASKE TASARIMI ÖZGÜR RUHUNU, GÖRÜNÜŞ VE PLANLAMA GİBİ ŞEYLERİ UMURSAMAYIŞINI YANSITIYOR. JIMMY İÇİN İYİ YETERİNCE İYİDİR; AYRINTILARA TAKILMAZ, HEP İLERLEMEK İSTER.",
["bm_msk_jiro_begins_desc"] = "BU, JIRO’NUN İKONİK MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_jiro_desc"] = "JAPONYA GELENEKLER DİYARIDIR. SAVAŞÇILAR DİYARI. JIRO’NUN MASKESİ BUNU YANSITIR. MASKE, JIRO’NUN GELENEKSEL JAPONYA’YA SEVGİSİNİ ANLATIRKEN DİŞLERİNİ AÇIĞA ÇIKARAN HIRLAYIŞ SARSILMAZ KARARLILIĞINI TEMSİL EDER.",
["bm_msk_joy_begins_desc"] = "GÖSTERİŞİN VE IŞILTININ DA BİR BAŞLANGICI OLMALI. BAZEN BU BAŞLANGIÇ, TERTEMİZ, SOĞUK VE HAREKETE HAZIR, GÜÇLÜ BİR BEYAZ TEMELDİR.",
["bm_msk_joy_desc"] = "DİSKOYU ŞIK BİR DÖNÜŞLE YENİDEN CANLANDIR. DÜŞMANLARIN O GÖZ KAMAŞTIRICI SURATINA BAKARKEN AKILLARI ALLAK BULLAK OLSUN.",
["bm_msk_jw_shades_desc"] = "BU GÖZLÜK, JOHN’UN ÖLDÜRMEK İÇİN TUTULDUĞU BİR MESLEKTAŞINA AİTTİ.$NL;$NL;HERHANGİ BİR GECE GİBİ BAŞLADI. AMA O GECE, O GÜN İŞ PEŞİNDE DOLAŞAN BAŞKA BİR KİRALIK KATİLİ ÖLDÜRMESİ İÇİN SÖZLEŞME ALDI. JOHN ONUN BEŞ YERE UĞRAYACAĞINI VE HEPSİNE AYNI TAKSİYLE GİTTİĞİNİ BİLİYORDU.$NL;$NL;SONUNDA İŞİ KENDİSİ YAPMASINA BİLE GEREK KALMADI; BULDUĞUNDA ADAM ÇOKTAN ÖLMÜŞTÜ.",
["bm_msk_kage_desc"] = "KAGE MASKESİNİN LANETLİ OLDUĞU SÖYLENİRDİ. OSAKA’DAKİ BİR KABUKİ TİYATROSUNDAN GELİYORDU; OYUNCU ONU TAKARKEN SAHNEDE ÖLÜP YERE YIĞILMIŞTI. SON SÖZLERİ \"HAYIR, ONLARI ÖLDÜRMEYECEĞİM, ÖLDÜRMEYECEĞİM\" OLMUŞTU. EFSANEYE GÖRE KAGE MASKESİNİN KANA SUSAMIŞLIĞI GİDERİLMEZSE ONU TAKANI ÖLDÜRÜR.",
["bm_msk_kangee_desc"] = "BEYAZ ADAMIN AYAK BASTIĞI BATI, GİZEMLİ BİR DİYARDI. KENDİLERİNİ, TOPRAKLARINI VE MİTOLOJİLERİNİ BU KUTSAL OYMALARLA İŞARETLEYEN SAVAŞÇI UYGARLIKLARIN YAŞADIĞI BİR DİYAR.",
["bm_msk_kawaii_desc"] = "SEVİMLİ, TATLI, ŞİRİN, HAVALI, GÖZDE, ÇEKİCİ, ZARARSIZ, MASUM, KAYGISIZ.$NL;$NL;BUNLAR KRİMİNOLOJİDE PEK KULLANILAN SÖZCÜKLER DEĞİL.$NL;$NL;SENİN SAYENDE ARTIK ÖYLELER.",
["bm_msk_king_of_jesters_desc"] = "PARLAK RENKLİ GİYSİLER VE ALACALI, TUHAF ŞAPKALAR GİYEN SOYTARILARIN BU TOPRAKLARDA HEP YERİ OLDU.$NL;$NL;İSTER TAHTA BACAKLARLA YÜRÜSÜN, İSTER ATEŞLE GÖSTERİ YAPSIN, İSTER ŞAKA ANLATSIN; TEK AMAÇLARI KALPLERİMİZE NEŞE YAYMAKTIR.$NL;$NL;AMA ŞİMDİ PARLAMA SIRASI SENDE. NEDEN MASKEYİ TAKIP BİRAZ NEŞE YAYMAYASIN?$NL;$NL;SİLAHINI ÇIKAR, MİSAFİRLERİNİ SOY VE HEPSİNİN BÜYÜK BİR OYUN OLDUĞUNU SÖYLE.",
["bm_msk_krampus_achievement"] = "AÇMAK İÇİN SANTA’NIN NOEL’İNİ İPTAL ETMEK BAŞARIMINI TAMAMLA!",
["bm_msk_krampus_desc"] = "BU YIL YARAMAZ MIYDIN? O ZAMAN KRAMPUS’UN ZİYARETİNİ BEKLEYEBİLİRSİN. YA DA BAIN’DEN TELEFON.",
["bm_msk_kwm_desc"] = "EFSANEVİ MACERACIMIZ [MANY GUN] CLOVERAPTOR’A SAYGIYLA; GİZEMLERİN ÇÖZÜCÜSÜ, THE MEGA DEATH’İ GETİREN! BANKACI OLMA HAYALİNİ BIRAKIP KADERİYLE YÜZLEŞTİ VE COP WİZARD İLE YARDAKÇILARI LAW ELEMENTALS’I YENDİ. BUNU KENDİ İRADESİYLE Mİ YOKSA BASKICI CRİME DAD’İN İRADESİYLE Mİ BAŞARDI, KİM BİLİR; AMA HİZMETİNE SONSUZA DEK MİNNETTAR KALACAĞIZ.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_lady_butcher_desc"] = "THE BUTCHER’A ÇEVRESİNDEKİLER HER \"CADI\", \"FAHİŞE\" VEYA \"BANSHEE\" DEDİĞİNDE BİR DOLAR ALSAYDIN, BÜTÜN HIRVATİSTAN’I SATIN ALACAK KADAR PARAN OLURDU. ETRAFINDAKİ ALAYCI ERKEKLER ONUN KADIN OLMASINDAN YAKINIYOR; SUÇ DÜNYASINDAKİ BAŞ DÖNDÜRÜCÜ YÜKSELİŞİNİ GÖRDÜKÇE KENDİLERİNİ TEHDİT ALTINDA VE HUZURSUZ HİSSEDİYORDU. BALKANLAR’IN, HERHANGİ BİR YÖNDEN FARKLI İNSANLARA HOŞGÖRÜSÜYLE TANINMADIĞINI UNUTMA. HAYATININ HER GÜNÜNÜ EN ACIMASIZ SUÇLULARDAN BAZILARIYLA ÇALIŞARAK GEÇİRİRKEN NE KADAR AÇIK BİR ERKEK ŞOVENİZMİ VE KADIN DÜŞMANLIĞIYLA UĞRAŞTIĞINI ANCAK HAYAL EDEBİLİRSİN. BU MASKE, HEM RAKİPLERİNİN HEM DE ORTAKLARININ ONU NASIL GÖRDÜĞÜNÜ GÖSTERİYOR. İNSANLARI KORKUTUYOR. KORKMALILAR DA.",
["bm_msk_lastlaugh_desc"] = "BU KABUĞUN ALTINDA DELİLİK Mİ VAR? TAKAN KİŞİYİ Mİ TEMSİL EDİYOR, YOKSA SOYGUNCULARIN KANUNA DUYDUĞU KÜÇÜMSEMENİN BİR YANSIMASI MI?",
["bm_msk_lcv_desc"] = "MODERN, DİNAMİK, KALABALIKLARI COŞTURAN BİR ŞEY. ZARİF, AKICI, TEPEDEN TIRNAĞA ŞIK. HEM LE CASTLE VANIA’NIN MÜZİĞİ HEM DE MASKESİ.",
["bm_msk_leshy_desc"] = "AVIN TANRISI, YABANIN RUHU. GEÇMİŞTEN GELEN BU İLKEL MASKEYİ TAKIP SOYGUNU KASIP KAVUR.",
["bm_msk_lincoln_desc"] = "AVUKAT, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETMEYİ AMAÇLIYORDU.$NL;$NL;AKADEMİSYENLER VE HALK TARAFINDAN SÜREKLİ TÜM ZAMANLARIN EN BÜYÜK ABD BAŞKANLARINDAN BİRİ SAYILIR.$NL;$NL;16. BAŞKAN, TARİHİN EN SEVİLEN BAŞKANLARINDAN BİRİDİR. SUÇLULAR ARASINDA HÂLÂ BÜYÜK SAYGI GÖRÜR.",
["bm_msk_lone_desc"] = "İSTER KATİL BİR KANUN KAÇAĞI OL İSTER YALNIZ, DALGIN BİR KORUCU; BAZEN KİMLİĞİNİ SAKLAMAN GEREKİR. YÜZÜNÜN ÜÇTE BİRİNİ KAPATAN İNCE SİYAH BİR GÖZ MASKESİNDEN DAHA İYİ NE OLABİLİR?",
["bm_msk_lycanwulf_desc"] = "\"LYCANWULF, LYCANWULF!\" DİYE BAĞIRDI KORKMUŞ KÖYLÜLER, LYCANWULF DENEN BU UCUBEYİ GÖRDÜKLERİNDE. ZAVALLI İNSANLAR ARTIK CANAVARIN ESİRİYDİ; DUVARI, TAVANI VEYA ANAHTARI OLMAYAN, TEK KAÇIŞIN ÖLÜM OLDUĞU BİR HAPİSHANEDE.",
["bm_msk_mad_mask_desc"] = "SON DERECE POPÜLER ZERO 68 ANİMESİNDEN ESİNLENEN BU MASKE, DİZİNİN SİBORG NİNJA KAHRAMANININ MİĞFERİ ÖRNEK ALINARAK YAPILDI.",
["bm_msk_male_ecp_desc"] = "BU MASKE, ONU TAKAN ADAMIN TAM TERSİNE GÜÇ VE KABA KUVVET SAÇIYOR. PALYAÇOYA ÖZGÜ HÜZÜN İLE GÖNÜLSÜZ ÖFKEYİ EŞİT ÖLÇÜDE TAŞIYARAK, BİRAZ İSTEMEYE İSTEMEYE SOYGUNCULUĞU SEÇMİŞ BİRİNİN RUH HÂLİNİ KUSURSUZCA YANSITIYOR.",
["bm_msk_mandril_desc"] = "MANDRİL MAYMUNU JOHN. MANDRİLLER BABUNLARA, DAHA DA YAKIN OLARAK DRİL MAYMUNLARINA AKRABADIR. BANKA SOYGUNUNDA KULLANILAN MATKAP DEĞİL, MAYMUN OLAN DRİL, SENİ ŞAPŞAL! JOHN, \"TANIMLANAMAYAN MAYMUN ÇIĞLIĞI\" GİBİ ALAYCI TEK CÜMLELİK LAFLARIYLA TANINAN BİR MAYMUNDUR.",
["bm_msk_mantis_desc"] = "BU SEVİMLİ KÜÇÜK DOSTLARIN YAYGIN ADI \"PEYGAMBERDEVESİ\". NEDEN Mİ? ÖN BACAKLARINI DUA EDER GİBİ KATLADIKLARI DURUŞLARINDAN GELİYOR. AMA DOĞALARI YÜZÜNDEN AVCI TARAFLARI DAHA ÇOK ÖNE ÇIKAR.$NL;$NL;KISACASI YAKALAYIP YİYEBİLDİKLERİ HER ŞEYİ YERLER.",
["bm_msk_mason_knight_veteran_desc"] = "MASONS’IN KNİGHT VETERANS ÜYELERİNİN MİĞFERİ, BU GÜÇLÜ VE YENİ TÜREMİŞ TARİKATIN SİMGESİYDİ. KÖYLÜLER ONU GÖRÜNCE MALRİC’İN YENİ DÜZENİNİN YAKINDA OLDUĞUNU BİLİRDİ.",
["bm_msk_mason_vanguard_veteran_desc"] = "BU MİĞFER GÖSTERİŞLİ BİR MEZAR HÖYÜĞÜNDEN ÇIKARILDI. BU DA SAHİBİNİN MASON ORDUSUNDA SAYGIN OLDUĞUNU GÖSTERİYOR. BU BÜYÜK SAVAŞÇILAR MALRİC’İN SEÇKİN BİRLİKLERİ GİBİ GÖRÜNÜYOR; BELKİ BAŞARISIZ TENOSİAN SEFERİNDE ONUNLA HİZMET ETTİLER.",
["bm_msk_maui_desc"] = "GENÇLİĞİNDE PASİFİK’İN \"ATEŞ ÇEMBERİ\"Nİ GEZEN BODHI ŞU GERÇEĞİ KAVRADI: KENDİNİ ONURLANDIRMAK, MİTLERİ ONURLANDIRMAKTIR. AKLINDA KALAN MİTLERDEN BİRİ MAUİ’NİNKİYDİ. MAUİ DE BODHI GİBİ İNSANLIĞIN YILMAZ SAVUNUCUSU, BİR DÜZENBAZ VE MACERACIYDI.",
["bm_msk_maw_01_desc"] = "BU MASKE ANTİK TAŞTAN YAPILMIŞ. ÖNCEKİ SAHİPLERİNİN HER BİRİNDEN KALMA OYMALAR VE MUAZZAM GÜÇ YAYAN BİR SİMGE TAŞIYOR. KENARINDAKİ YAZININ DA SÖYLEDİĞİ GİBİ, ONU TAKANA KARŞI GELENLER İÇİN SONUN BAŞLANGICIDIR.",
["bm_msk_max_begins_desc"] = "BU, İKONİK SANGRES MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_max_desc"] = "KAFATASI, SANGRES’İN KARİYERİ BOYUNCA SADIK YOLDAŞI OLAN DEATH. ALTIN DİŞ, ÖDENEN SİKKE. ÖLDÜRME SAYACI TETİKÇİLİK GEÇMİŞİNİ, KAN KIRMIZISI YAKUT İSE ABD’DE PEŞİNDE OLDUĞU YENİ SERVETİ TEMSİL EDER. SANGRES’İN ADI HAYATINDAKİ NİCE KANLI OLAYI ANLATIR; O KIRMIZI KAN MASKESİNDE DE BULUNUR.",
["bm_msk_mdm_desc"] = "DEATH BİR SON OLABİLİR AMA BİR BAŞLANGIÇ, KENDİNİ AŞMA VE ARINMA DA OLABİLİR. MEGA DEATH İSE DEATH’İN MİLYON KATI GÜCE SAHİPTİR.",
["bm_msk_medusa_desc"] = "ÇİRKİN BİR ÇEHRE, SAÇ YERİNE YILANLAR, TAŞA ÇEVİREN BİR BAKIŞ VE ERKEKLERE DUYULAN NEFRET. GÖZLERİ HÂLÂ İNSANI ÜRPERTİYOR... AMA BU SADECE BİR MASKE, DEĞİL Mİ?",
["bm_msk_mega_alien_desc"] = "THE WATCHERS, DÜNYA GEZEGENİNDE CASUSLUK YAPAN BİR DÜNYA DIŞI TÜRDÜR. ZİHİNLERİYLE İLETİŞİM KURAR; BÜYÜK GÖZLERİYLE İNSANLIĞI İZLEYİP HAKKINDA BİLGİ TOPLAR VE PAYLAŞIRLAR. BÖYLECE YAKLAŞAN İSTİLAYA HAZIRLANIRLAR.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mega_blade_desc"] = "ORİJİNAL GAGE BLADE, GAGE’İN EN SEVDİĞİ BALİSTİK YÜZ MASKELERİNDEN BİRİDİR. MEGA GAGE BLADE İLE GÖZDE BALİSTİK MASKESİNİ GELİŞTİRMEYE KARAR VERDİ. ÖNCEDEN YALNIZCA İŞLEVSELDİ; ŞİMDİ ŞIK DA.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mega_doctor_desc"] = "THE AMAZİNG CAREER CRİMİNALS’IN 34. SAYISINDA DOCTOR CRIME’IN ÖLDÜĞÜNÜ SANMIŞTIK AMA KORKMAYIN; DOCTOR GERİ DÖNDÜ! YENİ GÜÇ ZIRHI VE ŞIK YENİ MASKESİYLE, HABERSİZ KAHRAMANLARIMIZDAN İNTİKAM ALMAYA HAZIR.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mega_grin_desc"] = "THE GRIN BİR ZAMANLAR YENİLGİYİ KABUL ETMEK ZORUNDA KALAN BİR ADAMIN ÇÖKÜŞÜNÜ TEMSİL EDEN YÜZDÜ. AMA DEVİR DEĞİŞTİ; AYNI ADAM ŞİMDİ HER ZAMANKİNDEN GÜÇLÜ DÖNDÜ. TAZELENMİŞ, KARARLI BİR AMANSIZLIK VE KURNAZLIKLA DÜNYAYA MEYDAN OKUMAYA HAZIR. MASKE HÂLÂ BİR DELİNİN YÜZÜNÜ TEMSİL EDİYOR AMA KAZANAN BİR DELİNİN.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mega_mark_desc"] = "BU MASKE, ÇOK UZAK BİR DOĞU DİYARINDA İNSANLARA VE DİĞER HAYVANLARA DEHŞET SAÇTIĞI BİLİNEN EFSANEVİ BİR AYIDAN ESİNLENDİ. HİKÂYESİ SUÇ DÜNYASINDA ÇOK POPÜLERDİR. O AMANSIZ YARATIĞA BENZETİLMEK, YALNIZCA EN BÜYÜK VE EN ACIMASIZ SUÇLULARA LAYIK BÜYÜK BİR ONUR SAYILIR.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mega_sydney_desc"] = "MEGA SYDNEY MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_megacthulhu_desc"] = "BİR YERLERDE, OKYANUSUN KARANLIK DERİNLİKLERİNDE EFENDİMİZ VE KURTARICIMIZ CTHULHU YAŞAR. BİZİ DEV GAZABINDAN ESİRGEYEN VE ZİHİN DENETLEYEN ŞEFKATİYLE KUTSAYAN O’NA ÖVGÜLER OLSUN. KALAMAR YEMEYİN, YOKSA SONSUZ LANET SİZİN OLUR.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_megaskulldia_desc"] = "BLERRİE! GÖRÜNÜŞE GÖRE O MASKEYİ YAPMAK İÇİN KULLANDIĞIM ELMASLARA BİR TÜR MİSTİK ENERJİ İŞLEMİŞ! GELECEĞE DAİR GÖRÜNTÜLER FALAN GÖRÜYOR MUSUN? BELKİ TANRISAL YENİ GÜÇLER? HAYIR MI? SADECE YANAN GÖZLER Mİ? EH, YİNE DE HAVALI GÖRÜNÜYOR!",
["bm_msk_metalhead_desc"] = "METALHEAD’İN KÖKENİ BELİRSİZ.$NL;$NL;MASKEDEN ÇOK MİĞFERE BENZİYOR. DIŞARI UZANAN DİKENLERİ VAR; SÜSLENİP PÜSLENMİŞ, DEMİRDEN BİR GAZ MASKESİNİ ANDIRIYOR. AMA TAKANI GAZDAN VEYA YAKIN DÖVÜŞ SİLAHLARINDAN KORUYUP KORUMADIĞI BELİRSİZ.$NL;$NL;YİNE DE ÇOK HAVALI GÖRÜNÜYOR.$NL;$NL;BU MASKE BİR POETRY JAM MASKESİDİR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
["bm_msk_mmh_desc"] = "ARİSTOTLE, PLATO, CONFUCİUS, MİCHELANGELO, DAVİNCİ, NEWTON, GALİLEO... TARİHE SONSUZA DEK KAZINMIŞ SANATÇILAR VE DÜŞÜNÜRLER. O TARİHİN BİR YERİNDE BİR SOYGUNCUNUN YERİ DE HAZIR. ÖZLERİ BURADA BİR ARADA; BİRLEŞİMLERİ ÖYLE MUHTEŞEM Kİ MASKENİN YÜZEYİ ONLARI ZAR ZOR İÇİNDE TUTUYOR.",
["bm_msk_mmj_desc"] = "KLASİK EKİPMAN HARİKA OLABİLİR. 200 BEYGİRLİK ÇELİK ATA BİNEN KAHRAMAN BİR HEYECAN AVCISININ ZİHNİYETİ, İLK BAKIŞTA BELLİ OLMASA DA BİR SOYGUNCUYLA PEK ÇOK ORTAK NOKTA TAŞIR. ÖZEL YAPIM BİR BAŞLIĞIN ESTETİK DEĞERİ BUNLARDAN YALNIZCA BİRİDİR!",
["bm_msk_monkeybiss_desc"] = "HAYATI O KADAR DA CİDDİYE ALMAYAN BİRİ TAKAR.$NL;$NL;ÇÜNKÜ BU BİR MAYMUN MASKESİ.",
["bm_msk_moon_desc"] = "EFSANELER, AY’I DÜNYA’YA ÇARPTIRMAYA ÇALIŞACAK KADAR KÖTÜCÜL BİR VARLIKTAN SÖZ EDER. DÖRT MASKELİ SAVAŞÇI TARAFINDAN YENİLSE DE VARLIK KAÇIP... BİR ŞEYE YERLEŞMİŞ. UMARIZ BİR DAHA DÖNMEZ AMA UNUTMA: BAZEN İNSAN MASKEYİ TAKAR, BAZEN DE MASKE İNSANI.",
["bm_msk_mp2_01_desc"] = "SEVGİLİ FLUFFEDUP’IMIZ KAYIP. 95 YAŞINDA, AİLEMİZİN BİR PARÇASI. FLUFFEDUP MUTLU BİR UFAKLIK; KESİNLİKLE KENDİNİ BİRKAÇ KEZ BLENDERE VEYA ÇATIDAN AŞAĞI ATMAYA ÇALIŞMADI. ONU SONSUZA KADAR TUTMAK, HİÇ BIRAKMAMAK İSTİYORUZ. BU YÜZDEN BİZE, YAŞAYIP SEVDİĞİ VE KESİNLİKLE NEFRET ETMEDİĞİ EVİMİZE DÖNMESİ ÇOK ÖNEMLİ!",
["bm_msk_mp2_02_desc"] = "STOİBS BİRAZ TELAŞLI VE \"HIZLI\". GEÇEN SALI GECESİ KAÇTI, ONU GERİ ALIRSAK SEVİNİRİZ. İYİ SOY KÜTÜĞÜ OLAN BİR ÇİNÇİLLA BULMAKTA ZORLANDIK. O YÜZDEN YENİSİYLE BAŞTAN BAŞLAMAK, SEMİZ VE KÖRPE OLSUN DİYE MISIRLA BESLEMEK SIKICI OLACAK. BULURSANIZ STOİBS’İN TADINI ÇIKARACAĞIMIZ AKŞAM YEMEĞİNE SİZİ DE ÇAĞIRIRIZ!",
["bm_msk_mp2_03_desc"] = "BYRNE GİTTİ. O BİZİM KOALAMIZ, \"EV HAYVANIMIZ\". AMA GERİ İSTEMİYORUZ. SIKICI VE BUNALTICI; TEK YAPTIĞI OKALİPTÜS YAPRAĞI YEMEK. HEM DE BÜTÜN GÜN. ONA DOKUNMANDAN, HATTA ONUNLA KONUŞMANDAN BİLE HOŞLANMIYOR. ARTIK GİTTİ VE ÖYLE KALSIN İSTİYORUZ. BULURSANIZ (SEVİMSİZ BİR EV HAYVANINA BENZİYOR) SİZDE KALABİLİR, NE YAPARSANIZ YAPIN. BUNU SIKINTIDAN PATLAMAMAK İÇİN BİR UYARI SAYIN.",
["bm_msk_mp2_04_desc"] = "TEMPY BİZİM EVCİL ASLANIMIZ. 2 HAFTADIR KAYIP, ONU ÖZLÜYORUZ. TEMPY HER TÜRLÜ SEVİLMEYE BAYILIR; YETER Kİ BİZ SEVELİM. TEMPY’Yİ GÖRÜRSENİZ HİÇBİR ŞEKİLDE YAKLAŞMAYIN. LÜTFEN NEREDE GÖRDÜĞÜNÜZÜ BİZE SÖYLEYİN. YAKININA GELİRSENİZ SİZİ PARÇALAR. BUNUN DIŞINDA ÇOK TATLIDIR, GÜNEŞTE UYUMAYI SEVER. BİR DE ÇOCUKLARI GÖRMESİNE İZİN VERMEYİN... SONU İYİ BİTMİYOR.",
["bm_msk_mr_sinister_desc"] = "ÜRKÜTÜCÜ BİÇİMDE KÖTÜCÜL VE HAİN OLAN BU MASKENİN, TAKAN KİŞİYİ GİZEMLİ ŞEKİLLERDE DEĞİŞTİRDİĞİ SÖYLENİR.$NL;$NL;YETERİNCE UZUN SÜRE TAKILDIĞINDA KİŞİNİN YÜREĞİNİ KARARTTIĞI, ONU KARANLIK İŞLERE DUYDUĞU ARZUYLA DOLDURDUĞU ANLATILIR.",
["bm_msk_mrm_desc"] = "MEGA RUST MASKESİ, ORİJİNAL MASKENİN GELİŞMİŞ BİR SÜRÜMÜDÜR. KENDİNİ AŞMAYI VE ARINMAYI SİMGELER.$NL;$NL;DESTEĞİN İÇİN TEŞEKKÜRLER.$NL;$NL;OVERKILL SENİ SELAMLIYOR!",
["bm_msk_mrs_claus_achievement"] = "AÇMAK İÇİN VLAD'IN KÜÇÜK YARDIMCILARI BAŞARIMINI TAMAMLA!",
["bm_msk_mrs_claus_desc"] = "SANTA ARALIK GÖKLERİNDE UÇARKEN BİRİNİN EVDE KALIP ELFLERİ HİZAYA SOKMASI GEREKİR. BUNU CLAUS HANESİNİN KIRBAÇ ŞAKLATAN, PURO TÜTTÜREN KOMUTANINDAN DAHA İYİ KİMSE YAPAMAZ.",
["bm_msk_msk_grizel_desc"] = "CLOVER’IN MASKESİ, CLOVER’IN HEM EN ÇOK KORKTUĞU HEM DE EN ÇOK NEFRET ETTİĞİ ŞEYİ TEMSİL EDİYOR: NORMAL YÜZÜN OLARAK MASKE TAKMAK. AMELİYATLA KÜÇÜLTÜLMÜŞ BURUN, BOTOKSLU DUDAKLAR, HER ŞEYİ YUTAN KİBİR VE KENDİNE HAYRANLIK İFADESİ; HEPSİ KORKUNUN VE ZAYIFLIĞIN, KORKUNÇ BİR PARODİYE DÖNÜŞTÜRÜLMÜŞ SİMGELERİ.",
["bm_msk_mts_trol_desc"] = "BAZILARI SENDEN ZATEN ESKİ ÇAĞLARIN TROLÜ VEYA DEVİ GİBİ KORKUYOR OLABİLİR. ÖYLEYSE KALELERİNİN KASASINI BOŞALTIRKEN NEDEN O ROLE DE BÜRÜNMEYESİN?",
["bm_msk_mummy_desc"] = "DERİSİ VE ORGANLARI KORUNMUŞ BİR MUMYANIN YÜZÜ. AŞIRI SOĞUĞA (BUZ MUMYALARI!), DÜŞÜK NEME, HAVASIZLIĞA VEYA KİMYASALLARA KASITLI YA DA TESADÜFİ MARUZ KALMA BUNA YOL AÇMIŞ OLABİLİR.$NL;$NL;DÜNYANIN NERESİNDEN GELDİĞİNİ KİM BİLİR? UZUN ZAMANDIR KORUNMUŞ HÂLDE, ARTIK DÜNYAYA YENİDEN ÇIKMAYA HAZIR.",
["bm_msk_myh_begins_desc"] = "BU, İKONİK DUKE MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_myh_desc"] = "DUKE KÜLTÜRLÜ, ERDEMLİ VE TAŞ GİBİ SOĞUKKANLI BİR ADAMDIR. BU YÜZDEN MASKESİ, KİŞİLİĞİNİ YANSITMASI İÇİN TARİHİN BÜYÜK HEYKELLERİNDEN ESİNLENEREK TASARLANMIŞTIR. BU MASKE, HER SOYGUNDA ZARİF VE SARSILMAZ KALAN, İNCELİKLİ SUÇUN KARARLI TEMSİLCİSİNİN ZİHNİNE VE KALBİNE AÇILAN BİR PENCEREDİR.$NL;$NL;DUKE’U ÇEKEN ŞEYLERDEN BİRİ GİZEM SEVGİSİDİR. KASAYI AÇMADAN İÇİNDE NE OLDUĞUNU, TABLOYU ÇERÇEVESİNDEN ÇIKARMADAN ARKASINDA NE BULUNDUĞUNU ASLA TAM BİLEMEZSİN. PAYDAY GANG İLE EN BÜYÜK GİZEM HEMEN KÖŞENİN ARDINDA OLABİLİR...",
["bm_msk_ninja_hood_desc"] = "BAŞINA BAĞLANAN BASİT BİR KUMAŞ PARÇASI; DİLENCİYİ, ÇİFTÇİYİ, SIRADAN İNSANI, HERKESİ NİNJAYA DÖNÜŞTÜREBİLİR. GÖLGELER ARASINDA BİR GÖLGE, KARANLIKTA BİR HANÇER. AMANSIZ VEYA SİNSİ OLABİLİR; KALABALIKTAKİ HERHANGİ BİRİ OLABİLİR. YAPMAYA GELDİĞİ İŞİ BİTİRİR, SONRA KAYBOLUR.",
["bm_msk_nixon_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETMEYİ AMAÇLIYORDU.$NL;$NL;KESİNLİKLE BİR SAHTEKÂR DEĞİLDİ.$NL;$NL;37. BAŞKAN, GÖREVİNDEN İSTİFA EDEN TEK BAŞKANDI. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_msk_nomegusta_desc"] = "BANKA SOYARKEN KİRALIK KASADAN YALNIZCA BİR TOST ÇIKTIĞINDA.",
["bm_msk_nun_town_desc"] = "GERÇEK BİR KATOLİK RAHİBE TANIMIYORSAN KATOLİK RAHİBE MASKESİ KORKUTUCU BİR SEÇİM GİBİ GELMEYEBİLİR. TANIYORSAN DA SEVECEN, BÜYÜKANNE GİBİ PENGUEN DÜŞÜNCESİNİN NE KADAR YERSİZ OLDUĞUNU BİLİRSİN. BU ACIMASIZ KOCAKARILAR KÖTÜLÜĞÜN TA KENDİSİDİR; ELLERİNİN ERİŞTİĞİ HER GENÇ POPOYU PATAKLARLAR.",
["bm_msk_nutcracker_desc"] = "HANS İNSANLARDAN NEFRET EDER, KARŞISINA ÇIKANIN KAFATASINI KIRAR. AMA KORKUTUCU GÖRÜNÜMÜNÜN ALTINDA İYİ BİR ÇOCUKTUR. NEREDEYSE KILIK DEĞİŞTİRMİŞ BİR PRENS DENEBİLİR. ONA İYİ DAVRANIRSAN SENİ TATLILAR ÜLKESİ’NE GÖTÜREBİLİR.",
["bm_msk_obama_desc"] = "SİYASETÇİ, BAŞKOMUTAN, BABA. BU BÜYÜK ULUSA 8 YIL HİZMET ETTİ. UMUT DOLU BİR ADAM OLDUĞUNA ŞÜPHE YOK.$NL;$NL;44. BAŞKAN, TARİHİN EN İDDİALI BAŞKANLARINDAN BİRİYDİ. SUÇLULAR ARASINDA İSE HÂLÂ SON DERECE POPÜLER.",
["bm_msk_oilbaron_desc"] = "MİLYONLARCA YIL BEKLEDİ.$NL;$NL;BİR ZAMANLAR PEK ÇOK ŞEYDİ; ÖLÜP TOPRAĞA GÖMÜLMÜŞ SAYISIZ KÜÇÜK ORGANİZMA. ZAMANIN ALTINDA EZİLİP GEZEGENİN SICAĞINDA PİŞEREK TEK BİR KARA KÜTLEYE DÖNÜŞTÜLER. KENDİ DEĞERİNDEN HABERSİZ, ÇALKALANAN BİR SIVI. ADSIZ BİR ŞEY. BEKLEYEN BİR ŞEY.$NL;$NL;BİNYILLAR DAKİKALAR GİBİ GEÇTİ; SONUNDA BEKLEYİŞ SONA ERDİ. SAĞIR EDİCİ BİR UĞULTU, ADSIZ ŞEYİ DÜNYA’NIN KARANLIK RAHMİNDEN FIRLATTI. TOPRAKTAN YUKARI, METAL BİR KULENİN İÇİNDEN GEÇİP BİR YANARDAĞ GİBİ TEKSAS GÜNEŞİNE DOĞRU PÜSKÜRDÜ. COŞKULU ALKIŞLARLA, SEVİNÇ VE AÇGÖZLÜLÜK GÖZYAŞLARIYLA KARŞILANDI. HAYRANLARININ ÜZERİNE YAĞARKEN, SIRITAN BİR YÜZ ONA ADINI VERDİ:$NL;$NL;\"EH ÇOCUKLAR, GALİBA PETROL BULDUK.\"$NL;",
["bm_msk_old_hoxton_begins_desc"] = "BU, İKONİK HOXTON REBORN MASKESİNİN BOYANMADAN ÖNCEKİ TEMİZ HÂLİ.$NL;$NL;ORİJİNALİNİN SON HÂLİNİ HİÇ BEĞENMEDİN Mİ? İŞTE TARİHİ DEĞİŞTİRME ŞANSIN.",
["bm_msk_old_hoxton_desc"] = "HOXTON REBORN, HOXTON’IN HAPİSTE YAPTIĞI MASKEDİR. PAYDAY GANG ONSUZ DEVAM EDERKEN GEÇEN YILLARDA YAŞADIĞI HER ŞEYİN SİMGESİDİR. HAPİSHANE DENEYİMLERİNİN ONU NASIL DEĞİŞTİRDİĞİNİ KİMSE BİLMİYOR; SORULDUĞUNDA DA KONUŞMUYOR.$NL;$NL;TEK VARSAYABİLDİĞİMİZ, SONSUZA DEK DEĞİŞTİĞİ VE... BAŞKA BİR ŞEYE YENİDEN DOĞDUĞU.",
["bm_msk_oliver_desc"] = "\"DÜNYANIN EN BÜYÜK SOYGUNCULARI ÖDÜLÜNÜN ADAYLARI.....\"",
["bm_msk_onebelow_desc"] = "BU BAŞ, KARANLIK LORDLARIN DİYARLARA HÜKMETTİĞİ, İYİ İNSANLARIN YALNIZCA ÖLMEK İÇİN BÜYÜDÜĞÜ ESKİ GÜNLERİN SU DEHŞETİNDEN GERİYE KALAN TEK ŞEY. YAZIN KISA, KIŞIN SONSUZ GELDİĞİ; ONE BELOW’UN OKYANUSTAN ÇIKIP YERYÜZÜNDE YÜRÜDÜĞÜ GÜNLERDEN.",
["bm_msk_oni_desc"] = "ONİ, BİR JAPON ŞEYTANIDIR.$NL;$NL;KESKİN PENÇELİ, BAŞINDAN İKİ BOYNUZ ÇIKAN, ÇİRKİN VE DEVASA, DEVE BENZER YARATIKLARDIR.$NL;$NL;DERİLERİ PEK ÇOK RENKTE OLABİLİR AMA EN YAYGINLARI KIRMIZI VE MAVİDİR.",
["bm_msk_optimist_prime_desc"] = "\"DÜNYADA GÖRMEK İSTEDİĞİN DEĞİŞİMİN KENDİSİ OL.\"$NL;$NL;THE OPTIMIST’İN İNANDIĞI ŞEY BU.$NL;$NL;BARIŞÇIL BİR ROBOT GRUBUNUN LİDERİ OLARAK, OLUMSUZLUK VE YOK ETME SAPLANTILI RAKİP ROBOT ÇETELERİYLE SAVAŞMANIN SORUMLULUĞU OLDUĞUNU DÜŞÜNÜYOR. BAŞLICA SİLAHI, YAPICI AKIL YÜRÜTME VE TARAFSIZ MANTIKLA OLUMLU DÜŞÜNCEYİ YAYMAK.$NL;$NL;YA DA ZORLA YÜKSELTME YAPMAK. BUNLAR ZORUNLU.$NL;$NL;BU MASKE BİR POETRY JAM MASKESİDİR. SOYGUN SONU ÖDÜLLERİNDEN ÇIKMAZ VE SATILAMAZ. BUNUN YERİNE MASKE DEPONA ÜCRETSİZ İADE EDEBİLİRSİN AMA TÜM ÖZELLEŞTİRMELER VE BUNLAR İÇİN ÖDEDİĞİN ÜCRET KAYBOLUR.",
