["bm_msk_oro_desc"] = "BODHI, FRANSIZ POLİNEZYASI ADALARINI KEŞFEDERKEN SAVAŞ TANRISI ORO’NUN TAKİPÇİLERİYLE KARŞILAŞTI. GENÇ MACERACI, MÜCADELE SANATI KADAR GÜZEL ZANAAT İŞLERİNİ DE TAKDİR EDEN BU TANRIYA HIZLA HAYRAN OLDU.",
